十一、Widget 生命周期与状态管理
StatefulWidget
有状态的 widget，可以管理内部状态。
class MyWidget extends StatefulWidget {
  final String title;

  const MyWidget({Key? key, required this.title}) : super(key: key);

  @override
  _MyWidgetState createState() =&gt; _MyWidgetState();
}

class _MyWidgetState extends State&lt;MyWidget&gt; {
  int _counter = 0;

  @override
  void initState() {
    super.initState();
    // 初始化操作
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // 依赖变化
  }

  @override
  void didUpdateWidget(MyWidget oldWidget) {
    super.didUpdateWidget(oldWidget);
    // widget 更新
  }

  @override
  void setState(VoidCallback fn) {
    super.setState(fn);
    // 更新 UI
  }

  @override
  void deactivate() {
    super.deactivate();
    // 从树中移除
  }

  @override
  void dispose() {
    super.dispose();
    // 清理资源
  }

  @override
  Widget build(BuildContext context) {
    return Text(&#039;Counter: $_counter&#039;);
  }
}

InheritedWidget
用于向下传递数据给子树。
class MyData extends InheritedWidget {
  final String data;

  const MyData({required this.data, required Widget child})
      : super(child: child);

  static MyData of(BuildContext context) {
    return context.dependOnInheritedWidgetOfExactType&lt;MyData&gt;()!;
  }

  @override
  bool updateShouldNotify(MyData oldWidget) {
    return data != oldWidget.data;
  }
}

// 使用
MyData(
  data: &#039;Shared Data&#039;,
  child: ChildWidget(),
)

// 在子组件中访问
class ChildWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final data = MyData.of(context).data;
    return Text(data);
  }
}

十二、性能优化建议
1. 使用 const 构造函数
const Text(&#039;Static Text&#039;)
const SizedBox(height: 20)
2. 避免在 build 方法中创建对象
// 不好
class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final style = TextStyle(fontSize: 20);  // 每次 build 都创建
    return Text(&#039;Hello&#039;, style: style);
  }
}

// 好
class MyWidget extends StatelessWidget {
  final _style = TextStyle(fontSize: 20);  // 只创建一次

  @override
  Widget build(BuildContext context) {
    return Text(&#039;Hello&#039;, style: _style);
  }
}
3. 使用 ListView.builder 而非 ListView
// 不好：一次性创建所有子项
ListView(
  children: List.generate(10000, (i) =&gt; ListTile(title: Text(&#039;Item $i&#039;))),
)

// 好：按需创建
ListView.builder(
  itemCount: 10000,
  itemBuilder: (context, i) =&gt; ListTile(title: Text(&#039;Item $i&#039;)),
)
4. 避免不必要的 rebuild
// 使用 const 和提取 widgets
class ParentWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ExpensiveWidget(),  // const 或独立 widget
        Text(&#039;Dynamic content&#039;),
      ],
    );
  }
}

class ExpensiveWidget extends StatelessWidget {
  const ExpensiveWidget({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Container(/* 复杂内容 */);
  }
}

十三、Material Components (Material 组件)



                  Material Design 



Material 组件实现了 Google 的 Material Design 设计语言，提供了一套完整的 UI 组件库。使用这些组件需要包裹在 MaterialApp 或 Material widget 中。


1. Scaffold
Material 应用的基本布局结构，提供 AppBar、Drawer、BottomNavigationBar 等插槽。
Scaffold(
  appBar: AppBar(
    title: Text(&#039;My App&#039;),
    leading: Icon(Icons.menu),
    actions: [
      IconButton(icon: Icon(Icons.search), onPressed: () {}),
      IconButton(icon: Icon(Icons.more_vert), onPressed: () {}),
    ],
  ),
  body: Center(child: Text(&#039;Body&#039;)),
  floatingActionButton: FloatingActionButton(
    onPressed: () {},
    child: Icon(Icons.add),
  ),
  floatingActionButtonLocation: FloatingActionButtonLocation.endFloat,
  drawer: Drawer(
    child: ListView(
      children: [
        DrawerHeader(
          child: Text(&#039;Drawer Header&#039;),
          decoration: BoxDecoration(color: Colors.blue),
        ),
        ListTile(title: Text(&#039;Item 1&#039;)),
        ListTile(title: Text(&#039;Item 2&#039;)),
      ],
    ),
  ),
  endDrawer: Drawer(child: Text(&#039;End Drawer&#039;)),
  bottomNavigationBar: BottomNavigationBar(
    items: [
      BottomNavigationBarItem(icon: Icon(Icons.home), label: &#039;Home&#039;),
      BottomNavigationBarItem(icon: Icon(Icons.business), label: &#039;Business&#039;),
      BottomNavigationBarItem(icon: Icon(Icons.school), label: &#039;School&#039;),
    ],
  ),
  bottomSheet: Container(height: 50, color: Colors.blue),
  backgroundColor: Colors.white,
  resizeToAvoidBottomInset: true,
  primary: true,
)
主要属性：

appBar: 顶部应用栏
body: 主内容区域
floatingActionButton: 浮动操作按钮
drawer: 左侧抽屉菜单
endDrawer: 右侧抽屉菜单
bottomNavigationBar: 底部导航栏
bottomSheet: 底部面板
persistentFooterButtons: 固定在底部的按钮
backgroundColor: 背景色


