23. Stepper
步骤指示器。
int _currentStep = 0;

Stepper(
  currentStep: _currentStep,
  onStepContinue: () {
    if (_currentStep &lt; 2) {
      setState(() =&gt; _currentStep++);
    }
  },
  onStepCancel: () {
    if (_currentStep &gt; 0) {
      setState(() =&gt; _currentStep--);
    }
  },
  onStepTapped: (step) =&gt; setState(() =&gt; _currentStep = step),
  steps: [
    Step(
      title: Text(&#039;Step 1&#039;),
      content: Text(&#039;Content for step 1&#039;),
      subtitle: Text(&#039;Subtitle&#039;),
      state: StepState.indexed,  // indexed, editing, complete, disabled, error
      isActive: _currentStep == 0,
      label: Text(&#039;1&#039;),
    ),
    Step(
      title: Text(&#039;Step 2&#039;),
      content: Text(&#039;Content for step 2&#039;),
      isActive: _currentStep == 1,
    ),
    Step(
      title: Text(&#039;Step 3&#039;),
      content: Text(&#039;Content for step 3&#039;),
      isActive: _currentStep == 2,
    ),
  ],
  type: StepperType.vertical,  // vertical 或 horizontal
  controlsBuilder: (context, details) {
    return Row(
      children: [
        ElevatedButton(
          onPressed: details.onStepContinue,
          child: Text(&#039;Continue&#039;),
        ),
        SizedBox(width: 8),
        TextButton(
          onPressed: details.onStepCancel,
          child: Text(&#039;Cancel&#039;),
        ),
      ],
    );
  },
)

