)

// Flutter 3.12+ 使用 PopScope
PopScope(
  canPop: false,
  onPopInvoked: (didPop) async {
    if (didPop) return;
    final shouldPop = await showConfirmDialog();
    if (shouldPop &amp;&amp; context.mounted) {
      Navigator.pop(context);
    }
  },
  child: Scaffold(...),
)

