Q5: 如何实现响应式布局？
// ✅ 使用 LayoutBuilder
class ResponsiveWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth &gt; 600) {
          return DesktopLayout();
        } else {
          return MobileLayout();
        }
      },
    );
  }
}

// ✅ 使用 MediaQuery
class AnotherResponsiveWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final screenWidth = MediaQuery.of(context).size.width;

    return Column(
      children: List.generate(
        screenWidth &gt; 600 ? 4 : 2, // 大屏 4 列，小屏 2 列
        (index) =&gt; Card(child: Text(&#039;Item $index&#039;)),
      ),
    );
  }
}
Q6: Key 的作用是什么？
// ❌ 没有 key，状态可能混乱
class WithoutKey extends StatefulWidget {
  @override
  _WithoutKeyState createState() =&gt; _WithoutKeyState();
}

class _WithoutKeyState extends State&lt;WithoutKey&gt; {
  List&lt;Color&gt; colors = [Colors.red, Colors.blue, Colors.green];

  @override
  Widget build(BuildContext context) {
    return Column(
      children: colors
          .map((color) =&gt; ColorBox(color: color))
          .toList(),
    );
  }
}

// ✅ 使用 ValueKey 保持状态
class WithKey extends StatefulWidget {
  @override
  _WithKeyState createState() =&gt; _WithKeyState();
}

class _WithKeyState extends State&lt;WithKey&gt; {
  List&lt;Color&gt; colors = [Colors.red, Colors.blue, Colors.green];

  @override
  Widget build(BuildContext context) {
    return Column(
      children: colors
          .map((color) =&gt; ColorBox(
                key: ValueKey(color.toString()), // 使用颜色作为 key
                color: color,
              ))
          .toList(),
    );
  }
}
Key 类型选择：

























Key 类型使用场景ValueKey基于值 (字符串、数字等)ObjectKey基于对象实例UniqueKey每次都不同 (强制重建)GlobalKey跨 Widget 访问状态
