1. 构建高性能 Widget
// ✅ 最佳实践
class OptimizedCard extends StatelessWidget {
  final String title;
  final String subtitle;

  const OptimizedCard({
    Key? key,
    required this.title,
    required this.subtitle,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Card(
      child: ListTile(
        title: Text(title, maxLines: 1, overflow: TextOverflow.ellipsis),
        subtitle: Text(subtitle, maxLines: 2, overflow: TextOverflow.ellipsis),
      ),
    );
  }
}
关键点：

✅ 使用 const 构造函数
✅ 提取常用 Widget 为独立组件
✅ 使用 RepaintBoundary 隔离重绘
✅ 避免在 build 方法中创建对象
❌ 不要过度拆分 Widget

2. 状态管理最佳实践
// ✅ 简单状态：使用 setState
class SimpleCounter extends StatefulWidget {
  @override
  _SimpleCounterState createState() =&gt; _SimpleCounterState();
}

class _SimpleCounterState extends State&lt;SimpleCounter&gt; {
  int _count = 0;

  void increment() =&gt; setState(() =&gt; _count++);

  @override
  Widget build(BuildContext context) {
    return Text(&#039;Count: $_count&#039;);
  }
}

// ✅ 跨组件状态：使用 InheritedWidget
class CounterProvider extends InheritedWidget {
  final int count;
  final Function() increment;

  const CounterProvider({
    Key? key,
    required this.count,
    required this.increment,
    required Widget child,
  }) : super(key: key, child: child);

  static CounterProvider of(BuildContext context) {
    return context.dependOnInheritedWidgetOfExactType&lt;CounterProvider&gt;()!;
  }

  @override
  bool updateShouldNotify(CounterProvider oldWidget) {
    return count != oldWidget.count;
  }
}

// 使用
class CounterWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final provider = CounterProvider.of(context);
    return Text(&#039;Count: ${provider.count}&#039;);
  }
}
3. 布局优化技巧
// ✅ 使用 const 提高性能
const Padding(
  padding: EdgeInsets.all(8.0),
  child: Text(&#039;Constant Text&#039;),
)

// ✅ 避免嵌套过深的布局
// ❌ 不好
Container(
  child: Padding(
    padding: EdgeInsets.all(10),
    child: Center(
      child: Text(&#039;Bad&#039;),
    ),
  ),
)

// ✅ 更好
const Center(
  child: Padding(
    padding: EdgeInsets.all(10),
    child: Text(&#039;Better&#039;),
  ),
)

// ✅ 使用 Builder 减少嵌套
Column(
  children: [
    Text(&#039;Header&#039;),
    if (items.isEmpty)
      const Text(&#039;No items&#039;)
    else
      Expanded(
        child: ListView.builder(
          itemCount: items.length,
          itemBuilder: (context, index) =&gt; ListTile(title: Text(items[index])),
        ),
      ),
  ],
)
4. 动画性能优化
// ✅ 使用 AnimatedWidget 而非手动监听
class AnimatedRotation extends AnimatedWidget {
  const AnimatedRotation({
    Key? key,
    required Animation&lt;double&gt; animation,
  }) : super(key: key, listenable: animation);

  @override
  Widget build(BuildContext context) {
    final animation = listenable as Animation&lt;double&gt;;
    return Transform.rotate(
      angle: animation.value,
      child: const FlutterLogo(),
    );
  }
}

// ✅ 使用 RepaintBoundary 隔离动画
RepaintBoundary(
  child: AnimatedContainer(
    duration: Duration(milliseconds: 300),
    color: Colors.blue,
    child: Text(&#039;Animated&#039;),
  ),
)
5. 常用性能优化清单

 使用 const 构造函数
 避免在 build 方法中创建对象
 使用 ListView.builder 而非 ListView(children)
 使用 RepaintBoundary 隔离重绘
 合理使用 Keys 帮助 Flutter 复用 Widget
 避免过度拆分 Widget
 使用 Opacity 而非改变颜色透明度
 使用 AutomaticKeepAliveClientMixin 保持状态
 使用 AddRepaintBoundaries 为列表项添加边界
 使用 Image.network 的缓存机制


