6. showDatePicker
显示日期选择器对话框。
// 基础用法
Future&lt;void&gt; _selectDate() async {
  final DateTime? picked = await showDatePicker(
    context: context,
    initialDate: DateTime.now(),
    firstDate: DateTime(2020),
    lastDate: DateTime(2025),
  );
  if (picked != null) {
    setState(() =&gt; _selectedDate = picked);
  }
}

// 完整配置
Future&lt;void&gt; _selectDateAdvanced() async {
  final DateTime? picked = await showDatePicker(
    context: context,
    initialDate: DateTime.now(),
    firstDate: DateTime(2020),
    lastDate: DateTime(2030),
    initialEntryMode: DatePickerEntryMode.calendar,  // calendar 或 calendarOnly
    helpText: &#039;选择日期&#039;,
    cancelText: &#039;取消&#039;,
    confirmText: &#039;确定&#039;,
    errorFormatText: &#039;格式无效&#039;,
    errorInvalidText: &#039;日期无效&#039;,
    fieldLabelText: &#039;输入日期&#039;,
    fieldHintText: &#039;月/日/年&#039;,
    keyboardType: TextInputType.datetime,
    currentDate: DateTime.now(),
    restoreEntry: true,
    initialDatePickerMode: DatePickerMode.day,  // day, year, 或 无
    useRootNavigator: true,
    routeSettings: RouteSettings(name: &#039;/date_picker&#039;),
    textDirection: TextDirection.ltr,
    builder: (context, child) {
      return Theme(
        data: ThemeData.light().copyWith(
          colorScheme: ColorScheme.fromSeed(
            seedColor: Colors.blue,
            brightness: Brightness.light,
          ),
          dialogBackgroundColor: Colors.white,
        ),
        child: child!,
      );
    },
  );
  if (picked != null) {
    setState(() =&gt; _selectedDate = picked);
  }
}
DatePickerMode 枚举：

day: 日视图 (默认)
year: 年视图


