// 脉冲效果示例
class PulseAnimation extends StatefulWidget {
  @override
  _PulseAnimationState createState() =&gt; _PulseAnimationState();
}

class _PulseAnimationState extends State&lt;PulseAnimation&gt;
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation&lt;double&gt; _animation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 1000),
    );
    _animation = Tween&lt;double&gt;(begin: 0.8, end: 1.2).animate(
      CurvedAnimation(
        parent: _controller,
        curve: Curves.easeInOut,
      ),
    );
    _controller.repeat(reverse: true);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ScaleTransition(
      scale: _animation,
      child: FlutterLogo(size: 100),
    );
  }
}

5. SlideTransition
滑动转场动画。
SlideTransition(
  position: Tween&lt;Offset&gt;(
    begin: Offset(-1.0, 0.0),  // 从左侧滑入
    end: Offset.zero,
  ).animate(_animation),
  child: Container(
    width: 200,
    height: 200,
    color: Colors.green,
    child: Center(child: Text(&#039;滑动动画&#039;)),
  ),
)

// 从不同方向滑入
// 从上滑入
Tween&lt;Offset&gt;(begin: Offset(0.0, -1.0), end: Offset.zero)

// 从下滑入
Tween&lt;Offset&gt;(begin: Offset(0.0, 1.0), end: Offset.zero)

// 从右侧滑入
Tween&lt;Offset&gt;(begin: Offset(1.0, 0.0), end: Offset.zero)

6. RotationTransition
旋转转场动画。
RotationTransition(
  turns: _animation,  // 旋转圈数
  alignment: Alignment.center,
  filterQuality: FilterQuality.high,
  child: Container(
    width: 100,
    height: 100,
    color: Colors.orange,
    child: Icon(Icons.refresh),
  ),
)

// 无限旋转示例
class InfiniteRotation extends StatefulWidget {
  @override
  _InfiniteRotationState createState() =&gt; _InfiniteRotationState();
}

class _InfiniteRotationState extends State&lt;InfiniteRotation&gt;
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 2),
    );
    _controller.repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return RotationTransition(
      turns: _controller,
