// 复杂动画示例
class ComplexAnimation extends StatefulWidget {
  @override
  _ComplexAnimationState createState() =&gt; _ComplexAnimationState();
}

class _ComplexAnimationState extends State&lt;ComplexAnimation&gt;
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation&lt;double&gt; _scaleAnimation;
  late Animation&lt;Color?&gt; _colorAnimation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 2),
    );
    _scaleAnimation = Tween&lt;double&gt;(begin: 1.0, end: 1.5).animate(_controller);
    _colorAnimation = ColorTween(
      begin: Colors.blue,
      end: Colors.red,
    ).animate(_controller);
    _controller.repeat(reverse: true);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        return Container(
          width: 100 * _scaleAnimation.value,
          height: 100 * _scaleAnimation.value,
          decoration: BoxDecoration(
            color: _colorAnimation.value,
            shape: BoxShape.circle,
          ),
          child: child,
        );
      },
      child: Icon(Icons.star, color: Colors.white),
    );
  }
}

