4. DragTarget
拖拽目标组件。
DragTarget&lt;String&gt;(
  onAccept: (String data) {
    print(&#039;接受：$data&#039;);
    setState(() =&gt; _acceptedData.add(data));
  },
  onWillAccept: (String? data) {
    // 决定是否接受拖拽数据
    return data != null &amp;&amp; data.startsWith(&#039;drag&#039;);
  },
  onAcceptWithDetails: (DragTargetDetails&lt;String&gt; details) {
    print(&#039;接受带详情：${details.data}, 偏移：${details.offset}&#039;);
  },
  onLeave: (String? data) {
    print(&#039;离开：$data&#039;);
  },
  builder: (context, candidateData, rejectedData) {
    return Container(
      width: 200,
      height: 200,
      decoration: BoxDecoration(
        color: candidateData.isNotEmpty
            ? Colors.green.withOpacity(0.5)
            : Colors.grey.withOpacity(0.3),
        border: Border.all(color: Colors.black),
      ),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(&#039;放置区域&#039;),
          if (candidateData.isNotEmpty)
            Text(&#039;候选数据：${candidateData.length}&#039;),
          if (_acceptedData.isNotEmpty)
            Text(&#039;已接受：${_acceptedData.length}&#039;),
        ],
      ),
    );
  },
)

5. Dismissible
可滑动删除的列表项。
Dismissible(
  key: Key(item.id),  // 必须唯一
