十八、性能优化进阶



                  概述 



本章详细介绍 Flutter 性能优化技术，包括重绘边界、状态保持、内存优化等。


1. RepaintBoundary
隔离重绘区域，避免不必要的重绘。
// 基础用法
RepaintBoundary(
  child: AnimatedContainer(
    duration: Duration(seconds: 1),
    color: Colors.blue,
    child: Text(&#039;只有这个区域会重绘&#039;),
  ),
)

// 实际场景示例
class PerformanceExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 静态内容 - 不会重绘
        Text(&#039;标题&#039;, style: TextStyle(fontSize: 24)),
        Divider(),

        // 动画内容 - 使用 RepaintBoundary 隔离
        RepaintBoundary(
          child: AnimatedContainer(
            duration: Duration(milliseconds: 300),
            width: _width,
            height: _height,
            color: _color,
            child: Center(child: Text(&#039;动画内容&#039;)),
          ),
        ),

        // 静态内容 - 不会重绘
        Text(&#039;底部内容&#039;),
      ],
    );
  }
}

// 列表中的 RepaintBoundary
ListView.builder(
  itemCount: 1000,
  itemBuilder: (context, index) {
    return RepaintBoundary(
      child: ComplexWidget(index: index),
    );
  },
)
RepaintBoundary 使用场景：

动画组件周围
复杂的静态内容与动态内容之间
列表项组件
频繁更新的组件


2. AutomaticKeepAliveClientMixin
保持页面状态，避免重建。
class KeepAlivePage extends StatefulWidget {
  @override
  _KeepAlivePageState createState() =&gt; _KeepAlivePageState();
}

class _KeepAlivePageState extends State&lt;KeepAlivePage&gt;
    with AutomaticKeepAliveClientMixin {
  int _counter = 0;

  @override
  bool get wantKeepAlive =&gt; true;  // 返回 true 保持状态

  @override
  Widget build(BuildContext context) {
    super.build(context);  // 必须调用

    return ListView.builder(
      itemCount: 100,
      itemBuilder: (context, index) {
        if (index == 0) {
          return ListTile(
            title: Text(&#039;计数：$_counter&#039;),
            trailing: IconButton(
              icon: Icon(Icons.add),
              onPressed: () =&gt; setState(() =&gt; _counter++),
            ),
          );
        }
        return ListTile(title: Text(&#039;Item $index&#039;));
      },
    );
  }
}

// 在 TabBarView 中使用
TabBarView(
  children: [
    KeepAlivePage(),  // 切换时保持状态
    KeepAlivePage(),
    KeepAlivePage(),
  ],
)
wantKeepAlive 动态控制：
bool get wantKeepAlive =&gt; _counter &gt; 0;  // 条件保持状态

3. AddRepaintBoundary
为列表项添加重绘边界 (性能优化)。
ListView.builder(
  addRepaintBoundaries: true,  // 默认为 true
  addSemanticIndexes: true,
  addAutomaticKeepAlives: true,
  itemCount: 1000,
  itemBuilder: (context, index) {
    return ListTile(
      title: Text(&#039;Item $index&#039;),
    );
  },
)

// 禁用自动添加 RepaintBoundary
ListView.builder(
  addRepaintBoundaries: false,  // 手动控制
  itemBuilder: (context, index) {
    return RepaintBoundary(
      child: ListTile(title: Text(&#039;Item $index&#039;)),
    );
  },
)

4. const 构造函数优化
使用 const 避免不必要的重建。
// ✅ 好的做法
class OptimizedWidget extends StatelessWidget {
  const OptimizedWidget({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Column(
      children: const [
        Text(&#039;静态文本 1&#039;),
        Text(&#039;静态文本 2&#039;),
        SizedBox(height: 20),
        Icon(Icons.star),
      ],
    );
  }
}

// ❌ 不好的做法
class NonOptimizedWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(&#039;静态文本 1&#039;),
        Text(&#039;静态文本 2&#039;),
        SizedBox(height: 20),
        Icon(Icons.star),
      ],
    );
  }
}

// 提取 const 组件
class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: const [
        StaticHeader(),  // const 组件
        DynamicContent(),  // 动态组件
      ],
    );
  }
}

class StaticHeader extends StatelessWidget {
  const StaticHeader({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: EdgeInsets.all(16),
      child: Text(&#039;静态标题&#039;),
    );
  }
}

5. 避免 build 方法中创建对象
// ❌ 不好：每次 build 都创建对象
class BadExample extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final style = TextStyle(fontSize: 20);  // 每次都创建
    final padding = EdgeInsets.all(16);  // 每次都创建
    return Container(
      padding: padding,
      child: Text(&#039;Hello&#039;, style: style),
    );
  }
}

// ✅ 好：对象只创建一次
class GoodExample extends StatelessWidget {
  final _style = TextStyle(fontSize: 20);  // 只创建一次
  final _padding = EdgeInsets.all(16);  // 只创建一次

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: _padding,
      child: Text(&#039;Hello&#039;, style: _style),
    );
  }
}

// ✅ 使用 static const
class StaticExample extends StatelessWidget {
  static const _style = TextStyle(fontSize: 20);
  static const _padding = EdgeInsets.all(16);

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: _padding,
      child: Text(&#039;Hello&#039;, style: _style),
    );
  }
}

6. ListView.builder vs ListView
// ❌ 不好：一次性创建所有子项
ListView(
  children: List.generate(10000, (i) =&gt; ListTile(title: Text(&#039;Item $i&#039;))),
)

// ✅ 好：按需创建
ListView.builder(
  itemCount: 10000,
  itemBuilder: (context, index) {
    return ListTile(title: Text(&#039;Item $index&#039;));
  },
)

// 性能对比
class PerformanceComparison extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ElevatedButton(
          onPressed: () =&gt; Navigator.push(
            context,
            MaterialPageRoute(builder: (context) =&gt; BadListView()),
          ),
          child: Text(&#039;ListView(children)&#039;),  // 卡顿
        ),
        ElevatedButton(
          onPressed: () =&gt; Navigator.push(
            context,
            MaterialPageRoute(builder: (context) =&gt; GoodListView()),
          ),
          child: Text(&#039;ListView.builder&#039;),  // 流畅
        ),
      ],
    );
  }
}

7. 提取 Widget 避免过度重建
// ❌ 不好：整个 Column 都会重建
class ParentWidget extends StatefulWidget {
  @override
  _ParentWidgetState createState() =&gt; _ParentWidgetState();
}

class _ParentWidgetState extends State&lt;ParentWidget&gt; {
  int _counter = 0;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ExpensiveWidget(),  // 每次都重建
        Text(&#039;计数：$_counter&#039;),
        ElevatedButton(
          onPressed: () =&gt; setState(() =&gt; _counter++),
          child: Text(&#039;增加&#039;),
        ),
      ],
    );
  }
}

// ✅ 好：使用 const 构造函数
class ParentWidget extends StatefulWidget {
  @override
  _ParentWidgetState createState() =&gt; _ParentWidgetState();
}

class _ParentWidgetState extends State&lt;ParentWidget&gt; {
  int _counter = 0;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        const ExpensiveWidget(),  // 不会重建
        Text(&#039;计数：$_counter&#039;),
        ElevatedButton(
          onPressed: () =&gt; setState(() =&gt; _counter++),
          child: Text(&#039;增加&#039;),
        ),
      ],
    );
  }
}

// ✅ 更好：使用独立 Widget
class OptimizedParentWidget extends StatefulWidget {
  @override
  _OptimizedParentWidgetState createState() =&gt; _OptimizedParentWidgetState();
}

class _OptimizedParentWidgetState extends State&lt;OptimizedParentWidget&gt; {
  int _counter = 0;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ExpensiveWidget(key: ValueKey(&#039;static&#039;)),  // 使用 key 保持稳定
        Text(&#039;计数：$_counter&#039;),
        ElevatedButton(
          onPressed: () =&gt; setState(() =&gt; _counter++),
          child: Text(&#039;增加&#039;),
        ),
      ],
    );
  }
}

8. GlobalKey 和 Key 的正确使用
// GlobalKey 用于跨 Widget 访问
class GlobalKeyExample extends StatefulWidget {
  final GlobalKey&lt;_ChildWidgetState&gt; _childKey = GlobalKey();

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        ChildWidget(key: _childKey),
        ElevatedButton(
          onPressed: () {
            // 通过 GlobalKey 访问子组件状态
            _childKey.currentState();
          },
          child: Text(&#039;调用子组件方法&#039;),
        ),
      ],
    );
  }
}

class ChildWidget extends StatefulWidget {
  const ChildWidget({Key? key}) : super(key: key);

  @override
  _ChildWidgetState createState() =&gt; _ChildWidgetState();
}

class _ChildWidgetState extends State&lt;ChildWidget&gt; {
  void doSomething() {
    print(&#039;子组件方法被调用&#039;);
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      width: 100,
      height: 100,
      color: Colors.blue,
    );
  }
}

// ValueKey 用于保持状态
List&lt;Color&gt; colors = [Colors.red, Colors.blue, Colors.green];

// ❌ 没有 key，状态可能混乱
Column(
  children: colors
      .map((color) =&gt; ColorBox(color: color))
      .toList(),
)

// ✅ 使用 ValueKey 保持状态
Column(
  children: colors
      .map((color) =&gt; ColorBox(
            key: ValueKey(color.toString()),
            color: color,
          ))
      .toList(),
)

// UniqueKey 强制重建
Widget build(BuildContext context) {
  return Column(
    children: [
      UniqueChild(key: UniqueKey()),  // 每次都重建
      Text(&#039;其他内容&#039;),
    ],
  );
}

// ObjectKey 基于对象实例
ObjectKey objKey = ObjectKey(myObject);
Widget build(BuildContext context) {
  return Container(
    key: objKey,
    child: Text(&#039;基于对象的 key&#039;),
  );
}

9. 使用 Builder 减少嵌套
// ❌ 不好：深层嵌套
Container(
  child: Padding(
    padding: EdgeInsets.all(10),
    child: Column(
      children: [
        if (condition)
          Container(
            child: Padding(
              padding: EdgeInsets.all(8),
              child: Text(&#039;深层嵌套&#039;),
            ),
          ),
      ],
    ),
  ),
)

// ✅ 好：使用 Builder 减少嵌套
Container(
  child: Padding(
    padding: EdgeInsets.all(10),
    child: Builder(
      builder: (context) {
        if (condition) {
          return Padding(
            padding: EdgeInsets.all(8),
            child: Text(&#039;减少嵌套&#039;),
          );
        }
        return SizedBox.shrink();
      },
    ),
  ),
)

// ✅ 更好：提取 Widget
class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Container(
      child: Padding(
        padding: EdgeInsets.all(10),
        child: condition ? NestedWidget() : SizedBox.shrink(),
      ),
    );
  }
}

class NestedWidget extends StatelessWidget {
  const NestedWidget({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: EdgeInsets.all(8),
      child: Text(&#039;提取的 Widget&#039;),
    );
  }
}

