七、导航操作
7.1 基础导航方法
// 1. 导航到指定路径
context.go(&#039;/settings&#039;);

// 2. 返回上一页
context.pop();

// 3. 替换当前路由（不能返回）
context.go(&#039;/home&#039;);  // 默认就是 replace

// 4. 强制刷新当前页面
context.go(&#039;/home&#039;);  // 如果已经在 /home，会刷新

// 5. replace 方法（17.x 新增）
// 替换当前路由但保持相同的 page key，用于更新查询参数而不重新创建页面
context.replace(&#039;/search?q=flutter&amp;page=2&#039;);
replace 方法详解（17.x 新增）：



                  使用场景 



replace 方法用于更新当前路由的参数（如查询参数）但不重新创建页面，保持页面状态。


class SearchPage extends StatefulWidget {
  const SearchPage({super.key});

  @override
  State&lt;SearchPage&gt; createState() =&gt; _SearchPageState();
}

class _SearchPageState extends State&lt;SearchPage&gt; {
  String query = &#039;&#039;;
  int page = 1;

  void _updateQuery(String newQuery) {
    setState(() {
      query = newQuery;
    });
    // 更新 URL 但不重建页面
    context.replace(&#039;/search?q=$query&amp;page=$page&#039;);
  }

  void _nextPage() {
    setState(() {
      page++;
    });
    // 更新 URL 但不重建页面
    context.replace(&#039;/search?q=$query&amp;page=$page&#039;);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text(&#039;搜索&#039;)),
      body: Column(
        children: [
          TextField(
            onChanged: _updateQuery,
            decoration: const InputDecoration(hintText: &#039;输入搜索关键词&#039;),
          ),
          Expanded(
            child: ListView.builder(
              itemCount: 20,
              itemBuilder: (context, index) =&gt; ListTile(
                title: Text(&#039;结果 ${index + 1} - 第 $page 页&#039;),
              ),
            ),
          ),
          ElevatedButton(
            onPressed: _nextPage,
            child: const Text(&#039;下一页&#039;),
          ),
        ],
      ),
    );
  }
}
7.2 相对路径导航（17.x 增强）



                  相对路径支持 



17.x 版本增强了相对路径导航，支持 ./ 前缀。


// 绝对路径
context.go(&#039;/home/settings&#039;);

// 相对路径（17.x 新增）
context.go(&#039;./details&#039;);  // 相对于当前路由
context.go(&#039;../parent&#039;);  // 父级路由

// 在嵌套路由中使用
GoRoute(
  path: &#039;/user/:userId&#039;,
  builder: (context, state) =&gt; UserPage(),
  routes: [
    GoRoute(
      path: &#039;posts&#039;,  // 实际路径为 /user/:userId/posts
      builder: (context, state) =&gt; UserPostsPage(),
    ),
  ],
)
使用场景：
class UserPage extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          ElevatedButton(
            // 使用相对路径导航到子路由
            onPressed: () =&gt; context.go(&#039;./posts&#039;),
            child: Text(&#039;查看用户文章&#039;),
          ),
        ],
      ),
    );
  }
}
7.3 编程式导航
使用 GoRouter.of(context):
final router = GoRouter.of(context);

// 导航到指定路径
router.go(&#039;/settings&#039;);

// 返回
router.pop();

// 替换
router.pushReplacement(&#039;/home&#039;);

