8.4 完整示例：商品详情页
// 1. 定义路由
final router = GoRouter(
  routes: [
    GoRoute(
      path: &#039;/&#039;,
      builder: (context, state) =&gt; const ProductListPage(),
    ),
    GoRoute(
      path: &#039;/product/:id&#039;,
      builder: (context, state) {
        // 从路径获取 ID
        final productId = state.pathParameters[&#039;id&#039;];
        // 从 extra 获取完整数据
        final product = state.extra as Product?;

        return ProductDetailPage(
          productId: productId,
          product: product,
        );
      },
    ),
  ],
);

// 2. 数据模型
class Product {
  final String id;
  final String name;
  final double price;

  Product({
    required this.id,
    required this.name,
    required this.price,
  });
}

// 3. 在列表页导航
class ProductListPage extends StatelessWidget {
  final products = [
    Product(id: &#039;1&#039;, name: &#039;Laptop&#039;, price: 9999.0),
    Product(id: &#039;2&#039;, name: &#039;Mouse&#039;, price: 99.0),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text(&#039;商品列表&#039;)),
      body: ListView.builder(
        itemCount: products.length,
        itemBuilder: (context, index) {
          final product = products[index];
          return ListTile(
            title: Text(product.name),
            subtitle: Text(&#039;¥${product.price}&#039;),
            onTap: () =&gt; _navigateToDetail(context, product),
          );
        },
      ),
    );
  }

  void _navigateToDetail(BuildContext context, Product product) {
    // 传递完整数据到详情页
    context.go(&#039;/product/${product.id}&#039;, extra: product);
  }
}

// 4. 详情页
class ProductDetailPage extends StatelessWidget {
  const ProductDetailPage({
    required this.productId,
    this.product,
    super.key});

  final String productId;
  final Product?;

  @override
  Widget build(BuildContext context) {
    // 如果没有 extra 数据，显示产品 ID
    if (product == null) {
      return Scaffold(
        appBar: AppBar(title: Text(&#039;商品 $productId&#039;)),
        body: Center(child: Text(&#039;加载中...&#039;)),
      );
    }

    return Scaffold(
      appBar: AppBar(title: Text(product!.name)),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            Text(&#039;ID: ${product!.id}&#039;),
            Text(&#039;名称：${product!.name}&#039;),
            Text(&#039;价格：¥${product!.price}&#039;),
          ],
        ),
      ),
    );
  }
}

