);

class ErrorPage extends StatelessWidget {
  const ErrorPage({super.key, required this.error});

  final Exception? error;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text(&#039;出错了&#039;)),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const Icon(Icons.error, size: 64, color: Colors.red),
            const SizedBox(height: 16),
            Text(&#039;发生错误：$error&#039;),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: () =&gt; context.go(&#039;/&#039;),
              child: const Text(&#039;返回首页&#039;),
            ),
          ],
        ),
      ),
    );
  }
}

十二、实战项目
12.1 完整应用结构
项目结构：
lib/
├── main.dart
├── models/
│   ├── product.dart
│   └── user.dart
├── pages/
│   ├── home_page.dart
│   ├── product_list_page.dart
│   ├── product_detail_page.dart
│   ├── profile_page.dart
│   └── settings_page.dart
├── widgets/
│   ├── main_scaffold.dart
│   └── app_shell.dart
└── router.dart

12.2 完整路由配置
// lib/router.dart
import &#039;package:flutter/material.dart&#039;;
import &#039;package:go_router/go_router.dart&#039;;

import &#039;models/product.dart&#039;;
import &#039;pages/home_page.dart&#039;;
import &#039;pages/product_list_page.dart&#039;;
import &#039;pages/product_detail_page.dart&#039;;
import &#039;pages/profile_page.dart&#039;;
import &#039;pages/settings_page.dart&#039;;
import &#039;widgets/app_shell.dart&#039;;

class AppRouter {
  static final config = GoRouter(
    routes: [
      // 主应用 Shell（包含底部导航）
      ShellRoute(
        builder: (context, state, child) =&gt; const AppShell(),
        routes: [
          // 首页
          GoRoute(
            path: &#039;/&#039;,
            pageBuilder: (context, state) =&gt; const NoTransitionPage(
              child: HomePage(),
            ),
          ),

          // 商品列表
          GoRoute(
            path: &#039;/products&#039;,
            pageBuilder: (context, state) =&gt; const NoTransitionPage(
              child: ProductListPage(),
            ),
          ),

          // 商品详情（支持深层链接）
          GoRoute(
            path: &#039;/product/:id&#039;,
            builder: (context, state) {
              return ProductDetailPage(
                productId: state.pathParameters[&#039;id&#039;],
              );
            },
          ),

          // 个人资料
          GoRoute(
            path: &#039;/profile&#039;,
            pageBuilder: (context, state) =&gt; const NoTransitionPage(
              child: ProfilePage(),
            ),
          ),

          // 设置
          GoRoute(
            path: &#039;/settings&#039;,
            pageBuilder: (context, state) =&gt; const NoTransitionPage(
              child: SettingsPage(),
            ),
          ),
        ],
      ),

      // 404 页面
      GoRoute(
        path: &#039;*&#039;,
        pageBuilder: (context, state) =&gt; const NoTransitionPage(
          child: NotFoundPage(),
        ),
      ),
    ],
    errorBuilder: (context, state) =&gt; ErrorPage(state.error),
  );
}
12.3 主应用入口
// lib/main.dart
import &#039;package:flutter/material.dart&#039;;
import &#039;package:flutter_riverpod/flutter_riverpod.dart&#039;;
import &#039;package:go_router/go_router.dart&#039;;

import &#039;router.dart&#039;;

void main() {
  runApp(const ProviderScope(child: MyApp()));
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp.router(
      title: &#039;E-Commerce App&#039;,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
        useMaterial3: true,
      ),
      routerConfig: AppRouter.config,
    );
  }
}

十三、迁移指南
13.1 从 16.x 迁移到 17.x



                  重大变更 



Go Router 17.0 引入了一些重要的行为变化和新增功能。


主要变更：

ShellRoute 导航变化通知

// 17.x 中，ShellRoute 的导航变化默认会通知 GoRouter 的 observers
// 如果不需要此行为，可以设置 notifyRootObserver: false

ShellRoute(
  notifyRootObserver: false,  // 17.x 新参数
  builder: (context, state, child) =&gt; MyShell(child: child),
  routes: [...],
)

onEnter 回调新增

// 可以在 GoRouter 顶层添加 onEnter 回调
final router = GoRouter(
  onEnter: (context, currentState, nextState) {
    // 监听所有路由进入事件
    return null;
  },
  routes: [...],
);

redirect 回调中的 context 支持

// 17.x 修复：现在可以在 redirect 回调中使用 context 扩展方法
GoRoute(
  path: &#039;/protected&#039;,
  redirect: (context, state) {
    // 现在可以直接使用 context.go() 等
    if (!isLoggedIn) {
      // 这在 17.x 中现在可以工作了
      return &#039;/login&#039;;
    }
    return null;
  },
)

GoRouter.of(context) 在 redirect 中的访问

// 17.x 修复：通过 Zone-based context tracking 支持
GoRoute(
  path: &#039;/example&#039;,
  redirect: (context, state) {
    final router = GoRouter.of(context);  // 现在可用
    return null;
  },
)

StatefulShellRoute 预加载

// 17.x 新增：支持预加载
StatefulShellBranch(
  preload: true,  // 预加载此分支
  routes: [...],
)

caseSensitive 行为变更

// 从 15.x 开始，URL 默认大小写敏感
final router = GoRouter(
  caseSensitive: true,  // 默认值，/Home 和 /home 是不同路由
  routes: [...],
);

Fragment 支持

// 17.x 新增：完整的 Fragment 支持
context.go(&#039;/article#section1&#039;);
final state = GoRouterState.of(context);
print(state.fragment);  // 输出：section1
13.2 从 15.x 迁移到 16.x



                  架构优化 



16.0 版本主要是内部架构优化，API 保持高度兼容。


注意事项：

大部分代码无需修改
建议测试所有导航流程
检查第三方路由库兼容性

13.3 从 14.x 迁移到 15.x



                  重大变更 



Go Router 15.0 包含破坏性变更，特别是 extra 的传递方式。


主要变更：

Extra 数据传递

// ❌ 14.x 方式
context.go(&#039;/product/123&#039;, extra: {&#039;id&#039;: &#039;123&#039;, &#039;name&#039;: &#039;Laptop&#039;});

// ✅ 15.x 方式
final product = Product(id: &#039;123&#039;, name: &#039;Laptop&#039;);
context.go(&#039;/product/123&#039;, extra: product);

路由信息获取

// ❌ 旧方式
final router = GoRouter.of(context);
final location = router.location;

// ✅ 新方式
final route = GoRouterState.of(context);
final location = route.uri;
13.4 从 Navigator 1.0 迁移



                  逐步迁移 



可以在同一应用中同时使用 Navigator 和 GoRouter，逐步迁移。


迁移对照表：

























Navigator 1.0GoRouterNavigator.pushNamed(&#039;/route&#039;)context.go(&#039;/route&#039;)Navigator.pop()context.pop()Navigator.pushReplacementNamed(&#039;/route&#039;)context.go(&#039;/route&#039;)Navigator.popUntil()context.popUntil()

十四、最佳实践
14.1 路由组织原则


按功能分组

将相关路由放在一起
使用注释分组



命名规范

路由名称使用小写和下划线
参数名要有意义



文档化

为复杂路由添加注释
说明参数含义



14.2 性能优化
使用 StatefulShellRoute 保持状态
// ✅ 推荐：使用 StatefulShellRoute 保持 Tab 状态
StatefulShellRoute.indexedStack(
  builder: (context, state, child) =&gt; ScaffoldWithNavBar(child: child),
  branches: [
    StatefulShellBranch(routes: [...]),
    StatefulShellBranch(routes: [...]),
  ],
)
使用 pageBuilder 避免不必要的重建
// 使用 pageBuilder 避免不必要的重建
GoRoute(
  path: &#039;/home&#039;,
  pageBuilder: (context, state) =&gt; const NoTransitionPage(
    child: HomePage(),
  ),
)
预加载关键分支
StatefulShellBranch(
  preload: true,  // 预加载高访问量的分支
  routes: [
    GoRoute(path: &#039;/frequent&#039;, pageBuilder: (context, state) =&gt; ...),
  ],
)
14.3 类型安全路由
使用代码生成实现类型安全：
// 1. 安装 go_router_builder
// pubspec.yaml
dependencies:
  go_router: ^17.0.1
  go_router_builder: ^2.7.0

// 2. 运行代码生成
// flutter pub run build_runner

// 3. 定义类型安全的路由
@TypedRoute(&#039;/&#039;)
class HomeRoute extends GoRouteData {
  const HomeRoute();
}

@TypedRoute(&#039;/product/:id&#039;)
class ProductRoute extends GoRouteData {
  const ProductRoute({required this.id});
  final String id;
}

十五、常见问题
15.1 浏览器地址栏不更新
问题： 使用 context.push() 导致地址栏不更新。
解决： 使用 GoRouter 的导航方法。
// ❌ 错误
Navigator.push(context, MaterialPageRoute(...));

// ✅ 正确
context.go(&#039;/product/123&#039;);
15.2 路由参数中文乱码
问题： URL 中的中文显示为编码。
解决： GoRouter 15.x 自动处理 UTF-8 编码。
context.go(&#039;/product/商品名称&#039;);  // 自动编码
15.3 热重载问题
问题： 频繁路由导致动画卡顿。
解决： 使用 pageBuilder 替代 builder。

十六、参考资源
官方资源

Go Router 官方文档
Go Router GitHub
Flutter 导航文档
Go Router 发布说明

社区资源

Go Router 17.0 发布说明
Go Router 16.0 发布说明
Go Router 15.0 发布说明
Flutter Navigation 官方教程

推荐阅读

Deep Linking in Flutter
State Management with GoRouter
Web Support in Flutter


Sources:

go_router package
Go Router 17.0 发布说明
GoRouter 官方文档
Flutter 导航文档


🎯 总结
Go Router 17.x 是 Flutter 官方推荐的路由方案，提供：
✅ 简单易用的 API
✅ 声明式路由定义
✅ 原生的深度链接支持
✅ 完美的 Web 支持
✅ 类型安全的路由参数
✅ 强大的嵌套路由（ShellRoute）
✅ StatefulShellRoute 状态保持
✅ Fragment 支持
✅ onEnter 全局回调
✅ replace 方法
✅ 预加载 支持
通过学习本指南，你已经掌握了 Go Router 的核心用法，可以开始构建复杂的 Flutter 应用导航系统了！

