9.2 AsyncNotifierProvider - 可修改的异步状态



                  推荐使用 



AsyncNotifierProvider 是 Riverpod 3 最强大的特性之一！


完整例子： 带加载、刷新功能的用户列表
// 1. 定义 Notifier
class UserListNotifier extends AsyncNotifier&lt;List&lt;User&gt;&gt; {
  @override
  Future&lt;List&lt;User&gt;&gt; build() async {
    // 初始加载
    return _fetchUsers();
  }

  // 获取用户列表的方法
  Future&lt;List&lt;User&gt;&gt; _fetchUsers() async {
    await Future.delayed(const Duration(seconds: 1));
    return [
      User(name: &#039;张三&#039;, age: 25),
      User(name: &#039;李四&#039;, age: 30),
      User(name: &#039;王五&#039;, age: 28),
    ];
  }

  // 刷新方法
  Future&lt;void&gt; refresh() async {
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(() async {
      return _fetchUsers();
    });
  }

  // 添加用户
  Future&lt;void&gt; addUser(String name, int age) async {
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(() async {
      final users = await future;
      final newUser = User(name: name, age: age);
      return [...users, newUser];
    });
  }
}

// 2. 创建 Provider
final userListProvider = AsyncNotifierProvider&lt;UserListNotifier, List&lt;User&gt;&gt;(
  UserListNotifier.new,
);

// 3. 在 UI 中使用
class UserListPage extends ConsumerWidget {
  const UserListPage({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final usersAsync = ref.watch(userListProvider);

    return Scaffold(
      appBar: AppBar(
        title: const Text(&#039;用户列表&#039;),
        actions: [
          // 刷新按钮
          IconButton(
            icon: const Icon(Icons.refresh),
            onPressed: () =&gt; ref.read(userListProvider.notifier).refresh(),
          ),
        ],
      ),
      body: usersAsync.when(
        data: (users) =&gt; ListView.builder(
          itemCount: users.length,
          itemBuilder: (context, index) {
            final user = users[index];
            return ListTile(
              title: Text(user.name),
              subtitle: Text(&#039;年龄：${user.age}&#039;),
              trailing: const Icon(Icons.arrow_forward),
            );
          },
        ),
        loading: () =&gt; const Center(child: CircularProgressIndicator()),
        error: (error, stack) =&gt; Center(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(&#039;错误：$error&#039;),
              const SizedBox(height: 16),
              ElevatedButton(
                onPressed: () =&gt; ref.read(userListProvider.notifier).refresh(),
                child: const Text(&#039;重试&#039;),
              ),
            ],
          ),
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () =&gt; _showAddUserDialog(context, ref),
        child: const Icon(Icons.add),
      ),
    );
  }

  void _showAddUserDialog(BuildContext context, WidgetRef ref) {
    final nameController = TextEditingController();
    final ageController = TextEditingController();

    showDialog(
      context: context,
      builder: (context) =&gt; AlertDialog(
