13. Todo 应用



                  真实项目经验 



Todo 应用是学习状态管理的经典案例，因为：

包含多个状态（列表、过滤器）
有增删改查操作
需要异步处理（如果加持久化）



13.1 数据模型
创建 lib/models/todo.dart：
class Todo {
  final String id;
  final String title;
  final bool isCompleted;

  Todo({
    required this.id,
    required this.title,
    this.isCompleted = false,
  });

  Todo copyWith({String? id, String? title, bool? isCompleted}) {
    return Todo(
      id: id ?? this.id,
      title: title ?? this.title,
      isCompleted: isCompleted ?? this.isCompleted,
    );
  }
}
13.2 Provider
在 lib/providers.dart 中添加：
import &#039;package:riverpod_annotation/riverpod_annotation.dart&#039;;
import &#039;../models/todo.dart&#039;;

part &#039;providers.g.dart&#039;;

enum TodoFilter { all, active, completed }

@riverpod
class TodoList extends _$TodoList {
  @override
  List&lt;Todo&gt; build() =&gt; [];

  void add(String title) {
    final todo = Todo(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      title: title,
    );
    state = [...state, todo];
  }

  void toggle(String id) {
    state = [
      for (final todo in state)
        if (todo.id == id)
          todo.copyWith(isCompleted: !todo.isCompleted)
        else
          todo,
    ];
  }

  void remove(String id) {
    state = state.where((todo) =&gt; todo.id != id).toList();
  }
}

@riverpod
class Filter extends _$Filter {
  @override
  TodoFilter build() =&gt; TodoFilter.all;

  void setFilter(TodoFilter filter) =&gt; state = filter;
}

// 过滤后的 Todo 列表
@riverpod
List&lt;Todo&gt; filteredTodos(Ref ref) {
  final todos = ref.watch(todoListProvider);
  final filter = ref.watch(filterProvider);

  return switch (filter) {
    TodoFilter.all =&gt; todos,
    TodoFilter.active =&gt; todos.where((t) =&gt; !t.isCompleted).toList(),
    TodoFilter.completed =&gt; todos.where((t) =&gt; t.isCompleted).toList(),
  };
}
