}
5.7 AsyncNotifierProvider（推荐）
最新的异步状态管理方式，推荐使用。
// 1. 定义 AsyncNotifier
class UserNotifier extends AsyncNotifier&lt;User&gt; {
  @override
  Future&lt;User&gt; build() async {
    // 初始数据加载
    final response = await http.get(Uri.parse(&#039;api.example.com/user&#039;));
    return User.fromJson(jsonDecode(response.body));
  }

  // 更新用户
  Future&lt;void&gt; updateUser(String name) async {
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(() async {
      final response = await http.patch(
        Uri.parse(&#039;api.example.com/user&#039;),
        body: jsonEncode({&#039;name&#039;: name}),
      );
      return User.fromJson(jsonDecode(response.body));
    });
  }

  // 刷新数据
  Future&lt;void&gt; refresh() async {
    // 使用 ref.invalidate() 会重新执行 build
    ref.invalidateSelf();
  }
}

// 2. 创建 Provider
final userProvider = AsyncNotifierProvider&lt;UserNotifier, User&gt;(() {
  return UserNotifier();
});

// 3. 使用
class UserProfile extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final userAsync = ref.watch(userProvider);

    return Scaffold(
      body: userAsync.when(
        data: (user) =&gt; Column(
          children: [
            Text(&#039;Name: ${user.name}&#039;),
            ElevatedButton(
              onPressed: () =&gt; ref.read(userProvider.notifier).updateUser(&#039;New Name&#039;),
              child: Text(&#039;Update Name&#039;),
            ),
          ],
        ),
        loading: () =&gt; CircularProgressIndicator(),
        error: (error, stack) =&gt; Text(&#039;Error: $error&#039;),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () =&gt; ref.refresh(userProvider),
        child: Icon(Icons.refresh),
      ),
    );
  }
}



                  AsyncValue.guard 



使用 AsyncValue.guard() 可以自动捕获异常并转换为 AsyncValue.error：


state = await AsyncValue.guard(() async {
  // 可能抛出异常的异步操作
  return fetchData();
});

