6.3 Consumer
只在需要优化性能时使用，局部重建。
class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(&#039;Static Header&#039;),
        // 只有这个 Consumer 会重建
        Consumer(
          builder: (context, ref, child) {
            final value = ref.watch(expensiveProvider);
            return Text(&#039;Value: $value&#039;);
          },
