9.3 AsyncNotifierProvider 最佳实践
// 1. 数据模型
class Post {
  final int id;
  final String title;
  final String body;

  Post({required this.id, required this.title, required this.body});

  factory Post.fromJson(Map&lt;String, dynamic&gt; json) {
    return Post(
      id: json[&#039;id&#039;],
      title: json[&#039;title&#039;],
      body: json[&#039;body&#039;],
    );
  }
}

// 2. AsyncNotifier
class PostsNotifier extends AsyncNotifier&lt;List&lt;Post&gt;&gt; {
  @override
  Future&lt;List&lt;Post&gt;&gt; build() async {
    // 加载初始数据
    return _fetchPosts();
  }

  Future&lt;List&lt;Post&gt;&gt; _fetchPosts() async {
    final response = await http.get(
      Uri.parse(&#039;jsonplaceholder.typicode.com/posts&#039;),
    );

    if (response.statusCode == 200) {
      final List&lt;dynamic&gt; json = jsonDecode(response.body);
      return json.map((e) =&gt; Post.fromJson(e)).toList();
    }

    throw Exception(&#039;Failed to load posts&#039;);
  }

  // 刷新数据
  Future&lt;void&gt; refresh() async {
    state = const AsyncValue.loading();
    state = await AsyncValue.guard(() =&gt; _fetchPosts());
  }

  // 添加新帖子
  Future&lt;void&gt; addPost(String title, String body) async {
    state = const AsyncValue.loading();

    state = await AsyncValue.guard(() async {
      final response = await http.post(
        Uri.parse(&#039;jsonplaceholder.typicode.com/posts&#039;),
        body: jsonEncode({&#039;title&#039;: title, &#039;body&#039;: body}),
      );

      if (response.statusCode == 201) {
        final newPost = Post.fromJson(jsonDecode(response.body));
        return [...state.value ?? [], newPost];
      }

      throw Exception(&#039;Failed to add post&#039;);
    });
  }
}

// 3. Provider
final postsProvider = AsyncNotifierProvider&lt;PostsNotifier, List&lt;Post&gt;&gt;(() {
  return PostsNotifier();
});

// 4. UI
