  }

  void _showAddPostDialog(BuildContext context, WidgetRef ref) {
    final titleController = TextEditingController();
    final bodyController = TextEditingController();

    showDialog(
      context: context,
      builder: (context) =&gt; AlertDialog(
        title: Text(&#039;Add Post&#039;),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: titleController,
              decoration: InputDecoration(labelText: &#039;Title&#039;),
            ),
            TextField(
              controller: bodyController,
              decoration: InputDecoration(labelText: &#039;Body&#039;),
              maxLines: 3,
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () =&gt; Navigator.pop(context),
            child: Text(&#039;Cancel&#039;),
          ),
          TextButton(
            onPressed: () async {
              await ref.read(postsProvider.notifier).addPost(
                    titleController.text,
                    bodyController.text,
                  );
              Navigator.pop(context);
            },
            child: Text(&#039;Add&#039;),
          ),
        ],
      ),
    );
  }
}

十、最佳实践
10.1 文件组织结构
lib/
├── main.dart
├── providers/
│   ├── providers.dart          # 导出所有 providers
│   ├── auth_providers.dart      # 认证相关
│   ├── user_providers.dart     # 用户相关
│   └── config_providers.dart   # 配置相关
├── models/
│   ├── user.dart
│   ├── post.dart
│   └── ...
├── notifiers/
│   ├── auth_notifier.dart
│   ├── posts_notifier.dart
│   └── ...
└── ui/
    ├── pages/
    └── widgets/

10.2 Provider 命名规范
// ✅ 好的命名
final userProvider = Provider&lt;User&gt;((ref) =&gt; User());
final postsProvider = FutureProvider&lt;List&lt;Post&gt;&gt;((ref) =&gt; fetchPosts());
final counterProvider = StateProvider&lt;int&gt;((ref) =&gt; 0);

// ❌ 不好的命名
final data = Provider((ref) =&gt; User());
final posts = FutureProvider((ref) =&gt; fetchPosts());
final count = StateProvider((ref) =&gt; 0);
命名规则：

Provider 名称以 Provider 结尾
Notifier 名称以 Notifier 结尾
使用描述性名称

10.3 分离业务逻辑
// ✅ 好的做法 - 业务逻辑在 Notifier 中
class AuthNotifier extends StateNotifier&lt;AuthState&gt; {
  AuthNotifier(this._authService) : super(AuthState.initial()) {
    _init();
  }

  final AuthService _authService;

  Future&lt;void&gt; _init() async {
    final user = await _authService.getCurrentUser();
    state = AuthState.authenticated(user);
  }

  Future&lt;void&gt; login(String email, String password) async {
    state = AuthState.loading();
    try {
      final user = await _authService.signIn(email, password);
      state = AuthState.authenticated(user);
    } catch (e) {
      state = AuthState.error(e.toString());
    }
  }
}

// ❌ 不好的做法 - 业务逻辑在 UI 中
class LoginWidget extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return ElevatedButton(
      onPressed: () async {
        state = AuthState.loading();
        try {
          final user = await authService.signIn(email, password);
          state = AuthState.authenticated(user);
        } catch (e) {
          state = AuthState.error(e.toString());
        }
      },
      child: Text(&#039;Login&#039;),
    );
  }
}
10.4 使用代码生成（Riverpod Generator）
// 1. 定义注解
@riverpod
class Counter extends _$Counter {
  @override
  int build() =&gt; 0;

  void increment() =&gt; state++;
  void decrement() =&gt; state--;
}

// 2. 运行代码生成
// flutter pub run build_runner watch

// 3. 使用（生成的 Provider）
class CounterWidget extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final count = ref.watch(counterProvider);

    return ElevatedButton(
      onPressed: () =&gt; ref.read(counterProvider.notifier).increment(),
      child: Text(&#039;Count: $count&#039;),
    );
  }
}
代码生成的优势：

✅ 减少样板代码
✅ 类型安全
✅ 自动处理依赖
✅ 更好的 IDE 支持

10.5 错误处理
// ✅ 好的做法 - 完整的错误处理
final userProvider = FutureProvider.autoDispose&lt;User&gt;((ref) async {
  try {
    final response = await http.get(Uri.parse(&#039;api.example.com/user&#039;));

    if (response.statusCode == 200) {
      return User.fromJson(jsonDecode(response.body));
    } else if (response.statusCode == 401) {
      throw UnauthorizedException();
    } else if (response.statusCode == 404) {
      throw NotFoundException();
    } else {
      throw ServerException();
    }
  } on SocketException {
    throw NetworkException();
  }
});

// 使用时显示适当的错误信息
class UserWidget extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final userAsync = ref.watch(userProvider);

    return userAsync.when(
      data: (user) =&gt; Text(&#039;Welcome, ${user.name}&#039;),
      loading: () =&gt; CircularProgressIndicator(),
      error: (error, stack) {
        if (error is UnauthorizedException) {
          return Text(&#039;Please login&#039;);
        } else if (error is NetworkException) {
          return Text(&#039;No internet connection&#039;);
        } else {
          return Text(&#039;An error occurred&#039;);
        }
      },
    );
  }
}
10.6 性能优化
// 1. 使用 select 避免不必要的重建
class MyWidget extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // ✅ 只监听 name 字段
    final name = ref.watch(userProvider.select((user) =&gt; user.name));
    return Text(name);
  }
}

// 2. 使用 autoDispose 释放资源
final tempDataProvider = FutureProvider.autoDispose&lt;Data&gt;((ref) async {
  // 当不再使用时自动销毁
  return fetchData();
});

// 3. 缓存策略
final cachedDataProvider = FutureProvider.autoDispose&lt;Data&gt;((ref) {
  // 保留 5 分钟
  final link = ref.keepAlive();
  final timer = Timer(Duration(minutes: 5), () {
    link.close();
  });
  ref.onDispose(timer.cancel);

  return fetchData();
});

十一、常见问题
11.1 Riverpod vs Provider 选择？



                  选择建议 




新项目：使用 Riverpod 3.x（最新版本）
学习：Riverpod 有更好的文档和社区支持
代码生成：Riverpod 3.x 的代码生成功能强大
迁移：可以从 Provider 或 Riverpod 2.x 逐步迁移到 3.x






                  从 2.x 升级到 3.x 



如果你的项目使用 Riverpod 2.x，可以逐步升级到 3.x。主要的变更包括：

StateProvider 等移到 package:riverpod/legacy.dart
AutoDisposeRef 等接口统一为 Ref
所有 updateShouldNotify 现在使用 ==
AsyncValue 的 valueOrNull 改为 value



11.2 什么时候使用 autoDispose？
// ✅ 使用 autoDispose 的场景
final userProfileProvider = FutureProvider.autoDispose&lt;User&gt;((ref) {
  // 用户资料只在查看时需要，查看完可以释放
  return fetchUser();
});

final tempFormDataProvider = StateProvider.autoDispose&lt;String&gt;((ref) {
  // 表单临时数据，提交后可以释放
  return &#039;&#039;;
});

// ❌ 不使用 autoDispose 的场景
final configProvider = Provider&lt;AppConfig&gt;((ref) {
  // 应用配置，全程需要
  return AppConfig();
});

final authProvider = StateProvider&lt;AuthState&gt;((ref) {
  // 认证状态，全程需要
  return AuthState.initial();
});
11.3 如何在 Provider 外部修改状态？
final counterProvider = StateProvider&lt;int&gt;((ref) =&gt; 0);

// 在任何地方修改状态
void incrementCounter(WidgetRef ref) {
  ref.read(counterProvider.notifier).state++;
}

// 或在普通类中
class MyService {
  final Ref ref;

  MyService(this.ref);

  void doSomething() {
    ref.read(counterProvider.notifier).state++;
  }
}
11.4 如何测试 Riverpod 应用？
// 1. 创建 ProviderContainer
test(&#039;Counter should increment&#039;, () {
  final container = ProviderContainer();
  addTearDown(container.dispose);

  // 2. 读取 Provider
  expect(container.read(counterProvider), 0);

  // 3. 修改状态
  container.read(counterProvider.notifier).state++;

  // 4. 验证结果
  expect(container.read(counterProvider), 1);
});

// 5. 测试 Widget
testWidgets(&#039;Counter increments when button is tapped&#039;, (tester) async {
  await tester.pumpWidget(
    ProviderScope(
      child: MaterialApp(home: CounterScreen()),
    ),
  );

  expect(find.text(&#039;Count: 0&#039;), findsOneWidget);

  await tester.tap(find.byIcon(Icons.add));
  await tester.pump();

  expect(find.text(&#039;Count: 1&#039;), findsOneWidget);
});
11.5 如何处理多个异步操作？
class MultiAsyncNotifier extends AsyncNotifier&lt;List&lt;Data&gt;&gt; {
  @override
  Future&lt;List&lt;Data&gt;&gt; build() async {
    // 并行执行多个异步操作
    final results = await Future.wait([
      fetchUsers(),
      fetchPosts(),
      fetchComments(),
    ]);

    return results.expand((e) =&gt; e).toList();
  }
}

// 或者分别管理
final usersProvider = FutureProvider&lt;List&lt;User&gt;&gt;((ref) =&gt; fetchUsers());
final postsProvider = FutureProvider&lt;List&lt;Post&gt;&gt;((ref) =&gt; fetchPosts());

// 组合使用
final contentProvider = Provider&lt;Content&gt;((ref) {
  final usersAsync = ref.watch(usersProvider);
  final postsAsync = ref.watch(postsProvider);

  return usersAsync.when(
    data: (users) =&gt; postsAsync.when(
      data: (posts) =&gt; Content(users: users, posts: posts),
      loading: () =&gt; Content.loading(),
      error: (e, s) =&gt; Content.error(e),
    ),
    loading: () =&gt; Content.loading(),
    error: (e, s) =&gt; Content.error(e),
  );
});
11.6 常见错误和解决方案
错误 1: Riverpod 3.x 中使用旧 API
// ❌ 错误 - 3.x 中这些 provider 移动了
import &#039;package:riverpod/riverpod.dart&#039;;
final provider = StateProvider&lt;int&gt;((ref) =&gt; 0);

// ✅ 正确 - 使用 legacy 导入或改用 NotifierProvider
import &#039;package:riverpod/legacy.dart&#039;;
final provider = StateProvider&lt;int&gt;((ref) =&gt; 0);

// 或者使用推荐的 NotifierProvider
final provider = NotifierProvider&lt;MyNotifier, int&gt;(MyNotifier.new);
class MyNotifier extends Notifier&lt;int&gt; {
  @override
  int build() =&gt; 0;
}
错误 2: AsyncValue.valueOrNull 不存在
// ❌ 错误 - 3.x 中已移除
final value = asyncValue.valueOrNull;

// ✅ 正确 - 直接使用 value
final value = asyncValue.value; // 如果错误返回 null
错误 3: ProviderException 处理
// 3.x 中异常被包装在 ProviderException 中
try {
  ref.watch(failingProvider);
} on ProviderException catch (e) {
  // 访问原始异常
  switch (e.exception) {
    case SomeSpecificError():
      // 处理特定错误
    default:
      rethrow;
  }
}
错误 4: disposed Provider 交互
// ❌ 错误 - 3.x 会严格检查
class MyNotifier extends Notifier&lt;int&gt; {
  @override
  int build() =&gt; 0;

  Future&lt;void&gt; fetch() async {
    await Future.delayed(Duration(seconds: 1));
    state = 1; // 如果 provider 已释放会抛出错误
  }
}

// ✅ 正确 - 使用 ref.mounted 检查
class MyNotifier extends Notifier&lt;int&gt; {
  @override
  int build() =&gt; 0;

  Future&lt;void&gt; fetch() async {
    await Future.delayed(Duration(seconds: 1));
    if (!ref.mounted) return;
    state = 1;
  }
}

十二、从 2.x 升级到 3.x
12.1 主要破坏性变更



                  升级前必读 



Riverpod 3.0 包含一些破坏性变更。在升级前，请务必阅读官方迁移指南。


变更 1: Legacy Providers
StateProvider、StateNotifierProvider 和 ChangeNotifierProvider 移动到 package:riverpod/legacy.dart。
迁移步骤：

更新导入：

// 旧
import &#039;package:riverpod/riverpod.dart&#039;;

// 新
import &#039;package:riverpod/legacy.dart&#039;;

或者迁移到推荐的方式（使用 Notifier）：

// 旧方式
final counterProvider = StateProvider&lt;int&gt;((ref) =&gt; 0);

// 新方式
@riverpod
class Counter extends _$Counter {
  @override
  int build() =&gt; 0;

  void increment() =&gt; state++;
}
变更 2: AutoDispose 接口统一
不再有 AutoDisposeRef、AutoDisposeNotifier 等，统一为 Ref、Notifier。
迁移步骤：
// 旧方式
class MyNotifier extends AutoDisposeNotifier&lt;int&gt; {
  @override
  int build() =&gt; 0;
}

// 新方式
@riverpod
class MyNotifier extends _$MyNotifier {
  @override
  int build() =&gt; 0;
}
变更 3: FamilyNotifier 和 Notifier 融合
// 旧方式
class CounterNotifier extends FamilyNotifier&lt;int, int&gt; {
  @override
  int build(int arg) =&gt; 0;
}

// 新方式
@riverpod
class Counter extends _$Counter {
  @override
  int build(int arg) =&gt; 0;
}
变更 4: Ref 统一
所有 Provider-specific Ref 统一为 Ref：
// 旧方式
Future&lt;int&gt; myFuture(FutureProviderRef ref) async {
  return 42;
}

// 新方式
@riverpod
Future&lt;int&gt; myFuture(Ref ref) async {
  return 42;
}
变更 5: AsyncValue 改进
// 旧方式
final value = asyncValue.valueOrNull;

// 新方式
final value = asyncValue.value; // null 如果错误

// 新增：检查是否来自缓存
if (asyncValue.isFromCache) {
  print(&#039;From database&#039;);
}

// 新增：加载进度
state = AsyncLoading(progress: 0.5);
变更 6: updateShouldNotify 统一
所有 updateShouldNotify 现在使用 ==：
// 如果需要自定义行为
class MyNotifier extends AsyncNotifier&lt;User&gt; {
  @override
  bool updateShouldNotify(AsyncValue&lt;User&gt; previous, AsyncValue&lt;User&gt; next) {
    // 自定义实现
    return true;
  }
}
变更 7: ProviderException
异常现在被包装在 ProviderException 中：
try {
  ref.watch(provider.future);
} on ProviderException catch (e) {
  print(&#039;Original error: ${e.exception}&#039;);
  print(&#039;Stack trace: ${e.stackTrace}&#039;);
}
12.2 升级步骤
步骤 1: 更新依赖
dependencies:
  flutter_riverpod: ^3.0.0
  riverpod_annotation: ^3.0.0

dev_dependencies:
  riverpod_generator: ^3.0.0
  riverpod_lint: ^3.0.0
步骤 2: 运行代码生成
flutter pub get
dart run build_runner build --delete-conflicting-outputs
步骤 3: 检查编译错误
升级后，运行 dart analyze 查看编译错误。主要问题可能是：

Legacy providers 需要更新导入
AutoDispose 相关的类型需要移除前缀

步骤 4: 测试
运行所有测试，确保功能正常：
flutter test
步骤 5: 检查运行时行为

Provider 是否正常工作
异步操作是否正确
状态更新是否符合预期

12.3 升级后最佳实践

使用代码生成：将现有 providers 迁移到 @riverpod 注解
利用新功能：使用 Ref.mounted、自动重试等新特性
简化代码：利用统一的 API 减少样板代码
更新错误处理：处理 ProviderException 和新的 AsyncValue


十三、参考资源
