20-areas/技术知识/grpc.content:
gRPC 远程过程调用



                  概述 



gRPC 是 Google 开发的高性能 RPC 框架，使用 Protocol Buffers。


核心概念
Protocol Buffers
// user.proto
syntax = &quot;proto3&quot;;

message User {
    int32 id = 1;
    string name = 2;
    string email = 3;
}

service UserService {
    rpc GetUser(GetUserRequest) returns (User);
    rpc CreateUser(User) returns (User);
}
生成代码
Python
# 安装
pip install grpcio grpcio-tools

# 生成代码
python -m grpc_tools.protoc -I. --python_out=. --grpc_python_out=. user.proto
Go
# 安装
go install google.golang.org/protobuf/cmd/protoc-gen-go@latest
go install google.golang.org/grpc/cmd/protoc-gen-go-grpc@latest

# 生成代码
protoc --go_out=. --go_opt=paths=source_relative     --go-grpc_out=. --go-grpc_opt=paths=source_relative     user.proto
服务端实现
Python
import grpc
from concurrent import futures
import user_pb2
import user_pb2_grpc

class UserServiceImpl(user_pb2_grpc.UserServiceServicer):
    def GetUser(self, request, context):
        user = user_pb2.User(
            id=request.id,
            name=&quot;John Doe&quot;,
            email=&quot;john@example.com&quot;
        )
        return user

    def CreateUser(self, request, context):
        # 保存用户
        return request

# 启动服务器
server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
user_pb2_grpc.add_UserServiceServicer_to_server(
    UserServiceImpl(), server
)
server.add_insecure_port(&#039;[::]:50051&#039;)
server.start()
server.wait_for_termination()
Go
package main

import (
    &quot;context&quot;
    &quot;log&quot;
    &quot;net&quot;

    &quot;google.golang.org/grpc&quot;
    pb &quot;path/to/proto&quot;
)

type server struct {
    pb.UnimplementedUserServiceServer
}

func (s *server) GetUser(ctx context.Context, req *pb.GetUserRequest) (*pb.User, error) {
    return &amp;pb.User{
        Id:    req.Id,
        Name:  &quot;John Doe&quot;,
        Email: &quot;john@example.com&quot;,
    }, nil
}

func main() {
    lis, err := net.Listen(&quot;tcp&quot;, &quot;:50051&quot;)
    if err != nil {
        log.Fatal(err)
    }

    s := grpc.NewServer()
    pb.RegisterUserServiceServer(s, &amp;server{})
    log.Fatal(s.Serve(lis))
}
客户端调用
Python
import grpc
import user_pb2
import user_pb2_grpc

channel = grpc.insecure_channel(&#039;localhost:50051&#039;)
stub = user_pb2_grpc.UserServiceStub(channel)

# 调用 RPC
request = user_pb2.GetUserRequest(id=1)
response = stub.GetUser(request)
print(response.name)  # &quot;John Doe&quot;
Go
conn, err := grpc.Dial(&quot;localhost:50051&quot;, grpc.WithInsecure())
if err != nil {
    log.Fatal(err)
}
defer conn.Close()

client := pb.NewUserServiceClient(conn)

// 调用 RPC
ctx := context.Background()
resp, err := client.GetUser(ctx, &amp;pb.GetUserRequest{Id: 1})
if err != nil {
    log.Fatal(err)
}
fmt.Println(resp.Name)
高级特性
流式 RPC
