def auth interceptor(context, method_name, request, response):
    # 验证 token
    if not is_valid_token(context.metadata.get(&#039;token&#039;)):
        context.abort(grpc.StatusCode.UNAUTHENTICATED, &#039;Invalid token&#039;)
    return response(request)
