搭建 cgit Git 仓库浏览器。
安装
sudo pacman -S cgit fcgiwrap
Web 服务器
Nginx
server {
    listen 80;
    server_name git.example.com;

    location / {
        include fastcgi_params;
        fastcgi_param SCRIPT_FILENAME /usr/lib/cgit/cgit.cgi;
        fastcgi_pass unix:/run/fcgiwrap.sock;
    }

    location /cgit.css {
        alias /usr/share/webapps/cgit/cgit.css;
    }

    location /cgit.png {
        alias /usr/share/webapps/cgit/cgit.png;
    }
}
Apache
&lt;VirtualHost *:80&gt;
    ServerName git.example.com
    DocumentRoot /usr/share/webapps/cgit

    ScriptAlias /cgit/ &quot;/usr/lib/cgit/cgit.cgi/&quot;
    Alias /cgit.css &quot;/usr/share/webapps/cgit/cgit.css&quot;

    &lt;Directory &quot;/usr/lib/cgit/cgit.cgi&quot;&gt;
        Options ExecCGI FollowSymLinks
        AllowOverride All
        Require all granted
    &lt;/Directory&gt;
&lt;/VirtualHost&gt;
