创建任务
void vTaskFunction(void *pvParameters) {
    while (1) {
        // 任务代码
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

xTaskCreate(
    vTaskFunction,      // 任务函数
    &quot;TaskName&quot;,         // 任务名称
