基础配置
GPIO
// 输出
gpio_set_direction(GPIO_NUM_2, GPIO_MODE_OUTPUT);
gpio_set_level(GPIO_NUM_2, 1);

// 输入
gpio_set_direction(GPIO_NUM_4, GPIO_MODE_INPUT);
int level = gpio_get_level(GPIO_NUM_4);
中断
// 安装中断服务
gpio_install_isr_service(0);

// 配置中断
gpio_config_t io_conf = {
    .pin_bit_mask = (1ULL &lt;&lt; GPIO_NUM_4),
    .mode = GPIO_MODE_INPUT,
    .pull_up_en = 1,
    .intr_type = GPIO_INTR_POSEDGE
};
gpio_config(&amp;io_conf);

// 添加处理函数
gpio_isr_handler_add(GPIO_NUM_4, gpio_isr_handler, NULL);

// 中断处理函数
void IRAM_ATTR gpio_isr_handler(void* arg) {
    // 处理中断
}
任务
创建任务
void task(void* arg) {
    while (1) {
        // 任务代码
        vTaskDelay(1000 / portTICK_PERIOD_MS);
    }
}

xTaskCreate(task, &quot;task&quot;, 4096, NULL, 5, NULL);
定时器
硬件定时器
// 配置
timer_config_t config = {
    .divider = 80,
    .counter_dir = TIMER_COUNT_UP,
    .counter_en = TIMER_PAUSE,
    .alarm_en = TIMER_ALARM_EN,
    .auto_reload = true
};
timer_init(TIMER_GROUP_0, TIMER_0, &amp;config);

// 设置报警值
timer_set_alarm_value(TIMER_GROUP_0, TIMER_0, 1000000);
timer_start(TIMER_GROUP_0, TIMER_0);
PWM
配置
// LEDC
ledc_timer_config_t timer_conf = {
    .speed_mode = LEDC_LOW_SPEED_MODE,
    .duty_resolution = LEDC_TIMER_10_BIT,
    .timer_num = LEDC_TIMER_0,
    .freq_hz = 5000,
};
ledc_timer_config(&amp;timer_conf);

ledc_channel_config_t channel_conf = {
    .gpio_num = GPIO_NUM_2,
    .speed_mode = LEDC_LOW_SPEED_MODE,
    .channel = LEDC_CHANNEL_0,
    .intr_type = LEDC_INTR_DISABLE,
    .timer_sel = LEDC_TIMER_0,
    .duty = 0,
};
ledc_channel_config(&amp;channel_conf);

// 设置占空比
ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0, 512);
ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_0);
UART
配置
// 配置 UART
uart_config_t uart_config = {
    .baud_rate = 115200,
    .data_bits = UART_DATA_8_BITS,
    .parity = UART_PARITY_DISABLE,
    .stop_bits = UART_STOP_BITS_1,
    .flow_ctrl = UART_HW_FLOWCTRL_DISABLE,
};
uart_param_config(UART_NUM_0, &amp;uart_config);
uart_driver_install(UART_NUM_0, 256, 0, 0, NULL, 0);

// 发送
uart_write_bytes(UART_NUM_0, &quot;Hello&quot;, 5);
Wi-Fi
STA 模式
// 初始化 Wi-Fi
wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
esp_wifi_init(&amp;cfg);

// 配置 STA
wifi_config_t wifi_config = {
    .sta = {
        .ssid = &quot;SSID&quot;,
        .password = &quot;password&quot;,
    },
};
esp_wifi_set_config(ESP_IF_WIFI_STA, &amp;wifi_config);
esp_wifi_start();
esp_wifi_connect();
蓝牙
BLE
// 初始化 NimBLE
NimBLEDevice::init(&quot;DeviceName&quot;);

// 创建服务
BLEServer* pServer = NimBLEDevice::createServer();
BLEService* pService = pServer-&gt;createService(SERVICE_UUID);

// 创建特征
BLECharacteristic* pCharacteristic = pService-&gt;createCharacteristic(
    CHARACTERISTIC_UUID,
    NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE
);

pService-&gt;start();
pServer-&gt;getAdvertising()-&gt;start();
存储
NVS
// 初始化
nvs_handle_t handle;
nvs_open(&quot;storage&quot;, NVS_READWRITE, &amp;handle);

// 写入
nvs_set_str(handle, &quot;key&quot;, &quot;value&quot;);
nvs_commit(handle);

// 读取
char value[64];
size_t size = sizeof(value);
nvs_get_str(handle, &quot;key&quot;, value, &amp;size);

nvs_close(handle);
SPIFFS
// 挂载
esp_vfs_spiffs_conf_t conf = {
    .base_path = &quot;/spiffs&quot;,
    .partition_label = NULL,
    .max_files = 5,
};
esp_vfs_spiffs_register(&amp;conf);

// 使用
FILE* f = fopen(&quot;/spiffs/test.txt&quot;, &quot;w&quot;);
fprintf(f, &quot;Hello&quot;);
fclose(f);
