lwIP TCP/IP 协议栈



                  概述 



轻量级 TCP/IP 协议栈。
简介
lwIP (lightweight IP) 是为嵌入式系统设计的 TCP/IP 协议栈。
核心概念
进程模型
// 单线程
// 使用回调函数处理事件
内存管理
// 内存池
MEMP_NUM_TCP_PCB

// 动态内存
mem_malloc
mem_free
初始化
基本初始化
// 初始化
lwip_init();

// 初始化网络接口
netif_add(&amp;netif, &amp;ipaddr, &amp;netmask, &amp;gw, NULL, ethernet_init, ethernet_input);
netif_set_up(&amp;netif);
netif_set_link_up(&amp;netif);
网络接口
添加接口
static struct netif netif;

ip4_addr_t ipaddr, netmask, gw;
IP4_ADDR(&amp;ipaddr, 192, 168, 1, 10);
IP4_ADDR(&amp;netmask, 255, 255, 255, 0);
IP4_ADDR(&amp;gw, 192, 168, 1, 1);

netif_add(&amp;netif, &amp;ipaddr, &amp;netmask, &amp;gw, NULL, ethernetif_init, ethernet_input);
DHCP
启用 DHCP
// 启动 DHCP
dhcp_start(&amp;netif);

// DHCP 回调
struct dhcp* dhcp_struct = netif_dhcp_data(&amp;netif);

// 检查状态
if (netif.dhcp-&gt;state != DHCP_STATE_BOUND) {
    // 未获取 IP
}
Socket API
TCP 客户端
// 创建 socket
int sock = lwip_socket(AF_INET, SOCK_STREAM, 0);

// 连接
struct sockaddr_in addr;
addr.sin_family = AF_INET;
addr.sin_port = htons(80);
addr.sin_addr.s_addr = ipaddr_addr(&quot;192.168.1.1&quot;);
lwip_connect(sock, (struct sockaddr*)&amp;addr, sizeof(addr));

// 发送/接收
lwip_send(sock, data, len, 0);
lwip_recv(sock, buf, size, 0);

// 关闭
lwip_close(sock);
UDP
// 创建 socket
int sock = lwip_socket(AF_INET, SOCK_DGRAM, 0);

// 发送
struct sockaddr_in addr;
addr.sin_family = AF_INET;
addr.sin_port = htons(8080);
addr.sin_addr.s_addr = ipaddr_addr(&quot;192.168.1.1&quot;);
lwip_sendto(sock, data, len, 0, (struct sockaddr*)&amp;addr, sizeof(addr));

// 接收
lwip_recvfrom(sock, buf, size, 0, (struct sockaddr*)&amp;addr, &amp;addrlen);
Raw API
TCP 连接
// 创建 PCB
struct tcp_pcb* pcb = tcp_new();

// 连接
tcp_connect(pcb, &amp;ipaddr, port, connected_callback);

// 连接回调
err_t connected_callback(void* arg, struct tcp_pcb* tpcb, err_t err) {
    // 连接完成
    tcp_recv(tpcb, recv_callback);
    return ERR_OK;
}

// 接收回调
err_t recv_callback(void* arg, struct tcp_pcb* tpcb, struct pbuf* p, err_t err) {
    if (p != NULL) {
        // 处理数据
        tcp_recved(tpcb, p-&gt;tot_len);
        pbuf_free(p);
    }
    return ERR_OK;
}

// 发送
tcp_write(tpcb, data, len, TCP_WRITE_FLAG_COPY);
