C++ 编程笔记



                  概述 



现代 C++ 语言特性和最佳实践。
基础语法
智能指针
#include &lt;memory&gt;

std::unique_ptr&lt;MyClass&gt; ptr = std::make_unique&lt;MyClass&gt;();
std::shared_ptr&lt;MyClass&gt; shared = std::make_shared&lt;MyClass&gt;();

// 循环引用用 weak_ptr
std::weak_ptr&lt;MyClass&gt; weak = shared;
右值引用
// 移动语义
std::string str1 = &quot;Hello&quot;;
std::string str2 = std::move(str1);  // str1 现在为空

// 完美转发
template&lt;typename T&gt;
void wrapper(T&amp;&amp; arg) {
    func(std::forward&lt;T&gt;(arg));
}
STL 容器
vector
std::vector&lt;int&gt; vec = {1, 2, 3};
vec.push_back(4);
vec.emplace_back(5);  // 更高效
map
std::map&lt;std::string, int&gt; m;
m[&quot;key&quot;] = 42;

// 结构化绑定 (C++17)
for (const auto&amp; [key, value] : m) {
    std::cout &lt;&lt; key &lt;&lt; &quot;: &quot; &lt;&lt; value &lt;&lt; &quot;\n&quot;;
}
unordered_map
std::unordered_map&lt;std::string, int&gt; um;
um[&quot;key&quot;] = 42;
Lambda 表达式
auto lambda = [](int x, int y) { return x + y; };

// 捕获
int a = 10;
auto capture = [a](int x) { return x + a; };      // 值捕获
auto ref_capture = [&amp;a](int x) { return x + a; }; // 引用捕获
auto all = [=](int x) { return x + a; };          // 全部值捕获
auto all_ref = [&amp;](int x) { return x + a; };      // 全部引用捕获
模板
函数模板
template&lt;typename T&gt;
T max(T a, T b) {
    return a &gt; b ? a : b;
}
类模板
template&lt;typename T&gt;
class Stack {
    std::vector&lt;T&gt; data;
public:
    void push(T val) { data.push_back(val); }
    T pop() {
        T val = data.back();
        data.pop_back();
        return val;
    }
};
模板特化
// 全特化
template&lt;&gt;
class Stack&lt;bool&gt; {
    // bool 的特殊实现
};
并发
thread
#include &lt;thread&gt;

void func(int x) { /* ... */ }

std::thread t(func, 42);
t.join();
mutex
#include &lt;mutex&gt;

std::mutex mtx;
std::lock_guard&lt;std::mutex&gt; lock(mtx);
// 临界区
atomic
std::atomic&lt;int&gt; counter{0};
counter++;
future/promise
std::promise&lt;int&gt; p;
std::future&lt;int&gt; f = p.get_future();

std::thread t([&amp;p] {
    p.set_value(42);
});

int result = f.get();
t.join();
C++17 特性
std::optional
std::optional&lt;int&gt; divide(int a, int b) {
    if (b == 0) return std::nullopt;
    return a / b;
}

if (auto result = divide(10, 2)) {
    std::cout &lt;&lt; *result &lt;&lt; &quot;\n&quot;;
}
std::variant
std::variant&lt;int, std::string&gt; v = 42;
v = &quot;Hello&quot;;

std::visit([](auto&amp;&amp; arg) {
    std::cout &lt;&lt; arg &lt;&lt; &quot;\n&quot;;
}, v);
结构化绑定
std::tuple&lt;int, std::string&gt; t{42, &quot;Hello&quot;};
auto [i, s] = t;
C++20 特性
Concepts
template&lt;typename T&gt;
concept Integral = std::is_integral_v&lt;T&gt;;

template&lt;Integral T&gt;
T add(T a, T b) {
    return a + b;
}
Ranges
#include &lt;ranges&gt;

std::vector&lt;int&gt; vec{1, 2, 3, 4, 5};
auto evens = vec | std::views::filter([](int n) { return n % 2 == 0; });
Coroutines
Task&lt;int&gt; compute() {
    co_return 42;
}
最佳实践
RAII
class FileHandle {
    FILE* file;
public:
    FileHandle(const char* name) { file = fopen(name, &quot;r&quot;); }
    ~FileHandle() { fclose(file); }  // 自动关闭
};
const 正确性
void func(const std::string&amp; str);  // 不修改参数
class MyClass {
    int get() const;  // 不修改成员
};
override 关键字
