运算符详解



                  概述 



Dart 提供了丰富的运算符，包括算术、关系、逻辑、位运算等。理解这些运算符的使用方法和优先级对于编写正确的 Dart 代码至关重要。
运算符分类
1. 算术运算符
void main() {
  int a = 10, b = 3;

  print(a + b);   // 13 - 加法
  print(a - b);   // 7  - 减法
  print(a * b);   // 30 - 乘法
  print(a / b);   // 3.333... - 除法（返回 double）
  print(a ~/ b);  // 3  - 整除
  print(a % b);   // 1  - 取模（余数）

  // 一元运算符
  var x = 5;
  print(++x);     // 6  - 前置递增
  print(x++);     // 6  - 后置递增
  print(x);       // 7
  print(--x);     // 6  - 前置递减
  print(x--);     // 6  - 后置递减
}



                  除法运算符 




/ 始终返回 double
~/ 返回整除结果

2. 关系运算符
void main() {
  int a = 5, b = 10;

  print(a == b);  // false - 等于
  print(a != b);  // true  - 不等于
  print(a &gt; b);   // false - 大于
  print(a &lt; b);   // true  - 小于
  print(a &gt;= b);  // false - 大于等于
  print(a &lt;= b);  // true  - 小于等于
}
3. 逻辑运算符
void main() {
  bool a = true, b = false;

  print(a &amp;&amp; b);  // false - 逻辑与
  print(a || b);  // true  - 逻辑或
  print(!a);      // false - 逻辑非

  // 短路求值
  var value = null;
  if (value != null &amp;&amp; value.length &gt; 0) {
    print(&#039;Not executed&#039;);
  }
}
4. 位运算符
void main() {
  int a = 5;  // 二进制：101
  int b = 3;  // 二进制：011

  print(a &amp; b);   // 1  - 按位与 (001)
  print(a | b);   // 7  - 按位或 (111)
  print(a ^ b);   // 6  - 按位异或 (110)
  print(~a);      // -6 - 按位取反
  print(a &lt;&lt; 1);  // 10 - 左移
  print(a &gt;&gt; 1);  // 2  - 右移
}
5. 赋值运算符
void main() {
  int a = 10;

  a += 5;  // a = a + 5  =&gt; 15
  a -= 3;  // a = a - 3  =&gt; 12
  a *= 2;  // a = a * 2  =&gt; 24
  a ~/= 4; // a = a ~/ 4 =&gt; 6
  a %= 4;  // a = a % 4  =&gt; 2

  // ??= - 仅在为 null 时赋值
  int? b;
  b ??= 10;  // b 为 null，赋值为 10
  b ??= 20;  // b 不为 null，保持 10
}
6. 条件运算符
void main() {
  // 三元运算符 ?:
  int age = 18;
  String status = age &gt;= 18 ? &#039;Adult&#039; : &#039;Minor&#039;;
  print(status);  // Adult

  // 空值合并运算符 ??
  String? name;
  String displayName = name ?? &#039;Guest&#039;;
  print(displayName);  // Guest

  // 条件访问运算符 ?.
  List&lt;String&gt;? names;
  print(names?.length);  // null

  names = [&#039;Alice&#039;, &#039;Bob&#039;];
  print(names?.length);  // 2
}
7. 级联运算符
class Person {
  String? name;
  int? age;

  void greet() {
    print(&#039;Hello, $name&#039;);
  }

  void introduce() {
    print(&#039;I am $age years old&#039;);
  }
}

void main() {
  // 级联运算符 ..
  var person = Person()
    ..name = &#039;Alice&#039;
    ..age = 30
    ..greet()
    ..introduce();

  // 空值级联 ?..
  Person? maybePerson;
  maybePerson
    ?..name = &#039;Bob&#039;
    ..age = 25;  // 不会执行，因为 maybePerson 为 null
}



                  级联运算符 




.. 返回对象本身，支持链式调用
?.. 用于可空对象，安全调用

8. 其他运算符
void main() {
  // [] - 索引访问
  var list = [1, 2, 3];
  print(list[0]);  // 1

  // . - 成员访问
  var map = {&#039;key&#039;: &#039;value&#039;};
  print(map[&#039;key&#039;]);  // value

  // ?. - 条件成员访问
  List&lt;int&gt;? numbers;
  print(numbers?.first);  // null

  // ! - 非空断言
  String? name = &#039;Bob&#039;;
  print(name!.length);  // 3

  // as - 类型转换
  dynamic value = &#039;Hello&#039;;
  String text = value as String;
  print(text);  // Hello

  // is - 类型检查
  print(value is String);  // true
  print(value is! int);    // true
}
运算符优先级
从高到低的优先级顺序：
void main() {
  var result = 2 + 3 * 4;
  print(result);  // 14（先乘后加）

  var result2 = (2 + 3) * 4;
  print(result2);  // 20（括号优先）

  // 优先级示例
  bool a = true, b = false, c = true;
  print(a || b &amp;&amp; c);  // true（&amp;&amp; 优先于 ||）
  print((a || b) &amp;&amp; c);  // true
}
优先级表































































































优先级运算符说明1 (最高). ?. ..成员访问2() []函数调用、索引3- ! ~ ++ --一元运算符4* / % ~/乘除模5+ -加减6&lt;&lt; &gt;&gt; &gt;&gt;&gt;移位7&gt; &lt; &gt;= &lt;=比较8is is!类型检查9== !=等值比较10&amp;按位与11^按位异或12|按位或13&amp;&amp;逻辑与14||逻辑或15??空值合并16? :条件运算符17= *= /= 等赋值
运算符重载
Dart 允许重载大部分运算符：
class Vector {
  final double x;
  final double y;

  Vector(this.x, this.y);

  // 重载 + 运算符
  Vector operator +(Vector other) {
    return Vector(x + other.x, y + other.y);
  }

  // 重载 - 运算符
  Vector operator -(Vector other) {
    return Vector(x - other.x, y - other.y);
  }

  // 重载 * 运算符（标量乘法）
  Vector operator *(double scalar) {
    return Vector(x * scalar, y * scalar);
  }

  // 重载 == 运算符
  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is Vector &amp;&amp; other.x == x &amp;&amp; other.y == y;
  }

  @override
  int get hashCode =&gt; x.hashCode ^ y.hashCode;

  @override
  String toString() =&gt; &#039;Vector($x, $y)&#039;;
}

void main() {
  var v1 = Vector(1, 2);
  var v2 = Vector(3, 4);

  print(v1 + v2);  // Vector(4.0, 6.0)
  print(v1 - v2);  // Vector(-2.0, -2.0)
  print(v1 * 2);   // Vector(2.0, 4.0)
  print(v1 == v2); // false
}
特殊运算符用法
扩展运算符
void main() {
  // ... - 展开运算符
  var list1 = [1, 2, 3];
  var list2 = [0, ...list1, 4];
  print(list2);  // [0, 1, 2, 3, 4]

  // ...? - 空值展开运算符
  List&lt;int&gt;? nullableList;
  var list3 = [0, ...?nullableList, 4];
  print(list3);  // [0, 4]

  // Map 展开
  var map1 = {&#039;a&#039;: 1, &#039;b&#039;: 2};
  var map2 = {&#039;c&#039;: 3, ...map1};
  print(map2);  // {c: 3, a: 1, b: 2}
}
索引赋值运算符
void main() {
  var list = [1, 2, 3];

  // []= 索引赋值
  list[0] = 10;

  // ??= 空值赋值
  int? value;
  value ??= 5;  // value 为 5
  value ??= 10; // value 仍为 5
}
常见模式
1. 类型安全的转换
void main() {
  dynamic value = &#039;42&#039;;

  // 安全转换
  if (value is int) {
    int number = value;
    print(number + 10);
  } else if (value is String) {
    String text = value;
    print(text.length);
  }

  // 使用 as 转换（可能抛出异常）
  try {
    int number = value as int;
  } catch (e) {
    print(&#039;Not an int&#039;);
  }
}
2. 空值处理链
class User {
  String? name;
  Address? address;
}

class Address {
  String? city;
  String? street;
}

void main() {
  User? user = User();

  // 安全的深层访问
  String? city = user?.address?.city;

  // 带默认值
  String displayName = user?.name ?? &#039;Guest&#039;;

  // 链式调用
  user
    ?..name = &#039;Alice&#039;
    ..address = Address()
    ..address = &#039;New York&#039;;
}
常见陷阱



                  陷阱 1：除法返回 double 



var result = 5 / 2;  // 2.5（double）
var intResult = 5 ~/ 2;  // 2（int）



                  陷阱 2：== 与 equals 



var s1 = &#039;hello&#039;;
var s2 = &#039;hello&#039;;
print(s1 == s2);  // true（内容相同）

// 自定义类需要重载 ==



                  陷阱 3：位运算符优先级 



var result = 5 &amp; 3 == 1;  // (5 &amp; 3) == 1，不是 5 &amp; (3 == 1)
print(result);  // true



                  陷阱 4：级联运算符返回值 



var list = [1, 2, 3];
var result = list..add(4);
print(result);  // [1, 2, 3, 4]（返回对象本身）
最佳实践



                  运算符使用建议 





使用括号提高可读性
if ((a &amp;&amp; b) || (c &amp;&amp; d)) { }  // ✅ 清晰
if (a &amp;&amp; b || c &amp;&amp; d) { }       // ❌ 难以理解


优先使用 ?? 而不是三元运算符
var name = username ?? &#039;Guest&#039;;     // ✅ 简洁
var name = username != null ? username : &#039;Guest&#039;;  // ❌ 冗长


谨慎使用 !
print(name!);  // ⚠️ 确保不为 null
print(name ?? &#039;Default&#039;);  // ✅ 更安全


利用级联简化代码
var button = Button()
  ..text = &#039;Click&#039;
  ..onClick = handleAction;  // ✅ 简洁


相关概念

类型系统 - 类型检查和转换
控制流语句 - 条件和循环中的运算符使用
类与对象 - 运算符重载

