Mixin 机制



                  概述 



Mixin 是 Dart 中一种强大的代码复用机制，允许在不使用继承的情况下，在多个类层次结构中复用代码。Mixin 是 Dart 区别于其他语言的重要特性之一。
Mixin 基本概念
Mixin 是一种可以在多个类层次结构中复用的类。它提供了一种灵活的方式来组合功能。
与继承的区别
graph TD
    A[继承] --&gt; B[建立 is-a 关系]
    A --&gt; C[单继承限制]
    A --&gt; D[类层次结构]

    E[Mixin] --&gt; F[代码复用]
    E --&gt; G[多混入]
    E --&gt; H[横向扩展]

    style A fill:#e3f2fd
    style E fill:#e8f5e9

定义 Mixin
基本语法
// 定义 Mixin
mixin Flying {
  void fly() {
    print(&#039;Flying&#039;);
  }
}

mixin Swimming {
  void swim() {
    print(&#039;Swimming&#039;);
  }
}

// 使用 Mixin
class Bird with Flying {
  void chirp() {
    print(&#039;Chirp chirp&#039;);
  }
}

class Fish with Swimming {
  void bubble() {
    print(&#039;Bubble bubble&#039;);
  }
}

// 混入多个 Mixin
class Duck with Flying, Swimming {
  void quack() {
    print(&#039;Quack quack&#039;);
  }
}
Mixin 约束
on 关键字
使用 on 限制 Mixin 只能用于特定类或其子类：
class Animal {
  String name = &#039;Animal&#039;;
  void move() {
    print(&#039;$name is moving&#039;);
  }
}

// 这个 Mixin 只能用于 Animal 的子类
mixin Walker on Animal {
  void walk() {
    print(&#039;$name is walking&#039;);
  }
}

class Dog extends Animal with Walker {
  // ✅ Dog 继承自 Animal，可以使用 Walker
}

class Plant {
  // Plant 不是 Animal 的子类
}

// class Tree extends Plant with Walker { }
// ❌ 编译错误：Tree 不能使用 Walker
Mixin 的成员
方法
mixin Logger {
  void log(String message) {
    print(&#039;[LOG] $message&#039;);
  }

  void error(String message) {
    print(&#039;[ERROR] $message&#039;);
  }
}

class Service with Logger {
  void doWork() {
    log(&#039;Starting work&#039;);
    // do something
    log(&#039;Work completed&#039;);
  }
}
变量
mixin Configurable {
  String config = &#039;default&#039;;

  void setConfig(String value) {
    config = value;
  }

  String getConfig() {
    return config;
  }
}

class App with Configurable {
  void init() {
    print(config);  // default
    setConfig(&#039;production&#039;);
    print(getConfig());  // production
  }
}
抽象方法
mixin Validator {
  // 抽象方法：使用类必须实现
  bool isValid(String value);

  void validate(String value) {
    if (!isValid(value)) {
      throw ArgumentError(&#039;Invalid value: $value&#039;);
    }
  }
}

class EmailValidator with Validator {
  @override
  bool isValid(String value) {
    return value.contains(&#039;@&#039;);
  }
}
Mixin 与 this
Mixin 可以访问使用它的类的成员：
class Base {
  String name = &#039;Base&#039;;
  void greet() {
    print(&#039;Hello from $name&#039;);
  }
}

mixin ExtendedGreeting on Base {
  void extendedGreet() {
    // 可以访问 Base 的成员
    print(&#039;Extended greeting for $name&#039;);
    greet();  // 调用 Base 的方法
  }
}

class Derived extends Base with ExtendedGreeting {
  // 同时拥有 Base 和 ExtendedGreeting 的功能
}
Mixin 的应用场景
1. 功能模块化
mixin Serializable {
  Map&lt;String, dynamic&gt; toJson();

  factory Serializable.fromJson(Map&lt;String, dynamic&gt; json) {
    throw UnimplementedError();
  }
}

mixin Validatable {
  bool validate();
}

class User with Serializable, Validatable {
  String name;
  String email;

  User(this.name, this.email);

  @override
  Map&lt;String, dynamic&gt; toJson() {
    return {&#039;name&#039;: name, &#039;email&#039;: email};
  }

  @override
  bool validate() {
    return name.isNotEmpty &amp;&amp; email.contains(&#039;@&#039;);
  }
}
2. 跨领域关注点
mixin Timestamped {
  DateTime? createdAt;
  DateTime? updatedAt;

  void markCreated() {
    createdAt = DateTime.now();
  }

  void markUpdated() {
    updatedAt = DateTime.now();
  }
}

mixin Identifiable {
  String? id;

  String generateId() {
    id = DateTime.now().millisecondsSinceEpoch.toString();
    return id!;
  }
}

class Document with Timestamped, Identifiable {
  String content;

  Document(this.content) {
    generateId();
    markCreated();
  }

  void update(String newContent) {
    content = newContent;
    markUpdated();
  }
}
3. 能力注入
mixin Flyable {
  void fly() {
    print(&#039;Flying high!&#039;);
  }
}

mixin Swimmable {
  void swim() {
    print(&#039;Swimming deep!&#039;);
  }
}

mixin Runnable {
  void run() {
    print(&#039;Running fast!&#039;);
  }
}

class Animal {
  String name;
  Animal(this.name);
}

class Bird extends Animal with Flyable {
  Bird(String name) : super(name);
}

class Fish extends Animal with Swimmable {
  Fish(String name) : super(name);
}

class Dog extends Animal with Runnable {
  Dog(String name) : super(name);
}

class Duck extends Animal with Flyable, Swimmable {
  Duck(String name) : super(name);
}

class SuperHero extends Animal with Flyable, Runnable, Swimmable {
  SuperHero(String name) : super(name);
}
Mixin 的限制
不能继承
// ❌ Mixin 不能继承其他类
// mixin Walker on Legs { }

// ✅ Mixin 可以约束在特定类上
mixin Walker on Animal {
  void walk() {
    print(&#039;Walking&#039;);
  }
}
不能构造
// ❌ Mixin 不能有构造函数
mixin Example {
  // Example();  // 编译错误
  // Example.named();  // 编译错误
}
不能 extends
// ❌ Mixin 不能继承其他类
// mixin MyMixin extends OtherClass { }

// ✅ Mixin 可以约束在特定类上
mixin MyMixin on OtherClass {
  void method() {
    // 可以使用 OtherClass 的成员
  }
}
Mixin 解析顺序
当类使用多个 Mixin 时，方法的解析顺序很重要：
class A {
  void method() {
    print(&#039;A&#039;);
  }
}

mixin B on A {
  void method() {
    print(&#039;B&#039;);
    super.method();  // 调用 A 的 method
  }
}

mixin C on A {
  void method() {
    print(&#039;C&#039;);
    super.method();  // 调用 A 的 method
  }
}

class D extends A with B, C {
  // 方法解析顺序：D -&gt; C -&gt; B -&gt; A
}

void main() {
  D d = D();
  d.method();  // 输出：C -&gt; B -&gt; A
}
class vs mixin vs mixin class
// class - 普通类，可以被继承和混入
class Logger {
  void log(String message) {
    print(message);
  }
}

// mixin - 只能被混入，不能被实例化或继承
mixin Validator {
  bool validate(String value) =&gt; value.isNotEmpty;
}

// mixin class - 既可以被混入，也可以被继承和实例化
mixin class Utility {
  void helper() {
    print(&#039;Helper&#039;);
  }
}

// 使用
class Service with Logger, Validator {}
class AnotherService extends Utility {}
Utility utility = Utility();  // ✅ 可以实例化
// Validator validator = Validator();  // ❌ 不能实例化 mixin
最佳实践



                  Mixin 使用建议 




单一职责：每个 Mixin 只负责一个功能
明确命名：使用 -able、-ible、-ible 等后缀
避免状态：优先提供方法而不是存储状态
合理约束：使用 on 限制适用范围
文档说明：明确 Mixin 的用途和要求

// ✅ 好的 Mixin 设计
mixin Enumerable&lt;T&gt; {
  List&lt;T&gt; get items;

  List&lt;T&gt; where(bool Function(T) test) {
    return items.where(test).toList();
  }

  T? firstWhere(bool Function(T) test) {
    for (var item in items) {
      if (test(item)) return item;
    }
    return null;
  }
}

class Numbers with Enumerable&lt;int&gt; {
  @override
  List&lt;int&gt; get items =&gt; [1, 2, 3, 4, 5];
}
常见模式
1. 能力模式
mixin Singable {
  void sing() {
    print(&#039;La la la&#039;);
  }
}

mixin Danceable {
  void dance() {
    print(&#039;Shake it!&#039;);
  }
}

class Performer with Singable, Danceable {
  void perform() {
    sing();
    dance();
  }
}
2. 装饰器模式
mixin BoldDecorator {
  String render(String text) {
    return &#039;**$text**&#039;;
  }
}

mixin ItalicDecorator {
  String render(String text) {
    return &#039;*$text*&#039;;
  }
}

class Text with BoldDecorator, ItalicDecorator {
  // render 来自 ItalicDecorator
  // 但 ItalicDecorator 的 super 调用 BoldDecorator
}

void main() {
  Text text = Text();
  print(text.render(&#039;Hello&#039;));  // **Hello**
}
相关概念

继承机制 - 传统继承
抽象类与接口 - 接口和抽象类
类与对象 - 类的基础知识

参考资源

Dart Mixin 文档
Dart Mixin 最佳实践

30-resources/开发/dart/02-面向对象篇/扩展方法.content:
扩展方法



                  概述 



扩展方法（Extension Methods）是 Dart 2.7 引入的特性，允许为现有类添加新的方法，而无需继承或修改原类。这对于扩展第三方库的类特别有用。
基本语法
定义扩展方法
extension StringExtension on String {
  bool get isBlank =&gt; trim().isEmpty;

  String capitalize() {
    return &#039;${this[0].toUpperCase()}${substring(1)}&#039;;
  }

  String repeat(int times) {
    return List.generate(times, (index) =&gt; this).join(&#039;&#039;);
  }
}

void main() {
  var text = &#039;  hello  &#039;;

  // 使用扩展方法
  print(text.isBlank);         // true
  print(&#039;hello&#039;.capitalize()); // Hello
  print(&#039;ha&#039;.repeat(3));       // hahahaha
}
扩展命名
extension NumberParsing on String {
  int parseInt() {
    return int.parse(this);
  }

  double parseDouble() {
    return double.parse(this);
  }
}

void main() {
  print(&#039;42&#039;.parseInt());      // 42
  print(&#039;3.14&#039;.parseDouble()); // 3.14
}
扩展成员类型
扩展方法
extension ListExtension on List {
  List&lt;T&gt; whereNotNull&lt;T&gt;() {
    return where((element) =&gt; element != null).cast&lt;T&gt;();
  }
}

void main() {
  var list = [1, 2, null, 3, null, 4];
  var notNull = list.whereNotNull&lt;int&gt;();
  print(notNull);  // [1, 2, 3, 4]
}
扩展 getter
extension IntExtension on int {
  bool get isEven =&gt; this % 2 == 0;
  bool get isOdd =&gt; this % 2 != 0;

  String get toWords {
    const words = [&#039;zero&#039;, &#039;one&#039;, &#039;two&#039;, &#039;three&#039;, &#039;four&#039;, &#039;five&#039;];
    return words[this] ?? &#039;unknown&#039;;
  }
}

void main() {
  print(4.isEven);   // true
  print(5.isOdd);    // true
  print(3.toWords);  // three
}
扩展 setter
extension MapExtension on Map {
  set updateIfAbsent(String key, dynamic value) {
    if (!containsKey(key)) {
      this[key] = value;
    }
  }
}

void main() {
  var map = {&#039;a&#039;: 1};
  map.updateIfAbsent = (&#039;b&#039;, 2);
  print(map);  // {a: 1, b: 2}
}
扩展操作符
extension ComparableExtension on Comparable {
  bool operator &lt;(dynamic other) =&gt; false;
  bool operator &gt;(dynamic other) =&gt; false;
}

// 注意：不能扩展 ==、=、[]、[]=
扩展泛型类
extension ListExtension&lt;T&gt; on List&lt;T&gt; {
  List&lt;T&gt; sortedBy(int Function(T, T) compare) {
    var newList = [...this];
    newList.sort(compare);
    return newList;
  }

  T? firstWhereOrNull(bool Function(T) test) {
    for (var item in this) {
      if (test(item)) return item;
    }
    return null;
  }
}

void main() {
  var numbers = [3, 1, 4, 1, 5, 9];
  var sorted = numbers.sortedBy((a, b) =&gt; a.compareTo(b));
  print(sorted);  // [1, 1, 3, 4, 5, 9]

  var found = numbers.firstWhereOrNull((n) =&gt; n &gt; 10);
  print(found);  // null
}
扩展的冲突
成员冲突
class MyClass {
  void method() {
    print(&#039;Class method&#039;);
  }
}

extension MyExtension on MyClass {
  void method() {
    print(&#039;Extension method&#039;);
  }
}

void main() {
  var obj = MyClass();
  obj.method();  // Class method（类成员优先）
}
扩展冲突
extension Extension1 on String {
  void greet() {
    print(&#039;Hello from Extension1&#039;);
  }
}

extension Extension2 on String {
  void greet() {
    print(&#039;Hello from Extension2&#039;);
  }
}

void main() {
  var text = &#039;hello&#039;;
  // text.greet();  // ❌ 编译错误：冲突

  // 解决方法 1：使用显式导入
  // 解决方法 2：使用 hide 导入
  // 解决方法 3：重命名扩展
}
解决冲突的方法
// 方式 1：使用前缀
import &#039;extensions.dart&#039; as ext;

void main() {
  &#039;hello&#039;.ext.Extension1.greet();
}

// 方式 2：hide 导入
import &#039;extensions.dart&#039; hide Extension2;

// 方式 3：show 导入
import &#039;extensions.dart&#039; show Extension1;
扩展的实际应用
1. 字符串处理
extension StringValidation on String {
  bool get isEmail {
    return RegExp(r&#039;^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$&#039;).hasMatch(this);
  }

  bool get isUrl {
    return RegExp(r&#039;^https?:\/\/.+&#039;).hasMatch(this);
  }

  bool get isPhoneNumber {
    return RegExp(r&#039;^\+?[\d\s-]+$&#039;).hasMatch(this);
  }

  String get capitalize {
    if (isEmpty) return this;
    return &#039;${this[0].toUpperCase()}${substring(1)}&#039;;
  }

  List&lt;String&gt; get toWords {
    return split(RegExp(r&#039;\s+&#039;));
  }
}

void main() {
  print(&#039;user@example.com&#039;.isEmail);      // true
  print(&#039;dart.dev&#039;.isUrl);         // true
  print(&#039;+1 234 567 8900&#039;.isPhoneNumber); // true
  print(&#039;hello&#039;.capitalize);               // Hello
  print(&#039;hello world dart&#039;.toWords);       // [hello, world, dart]
}
2. 日期时间处理
extension DateExtension on DateTime {
  bool get isToday {
    final now = DateTime.now();
    return year == now.year &amp;&amp; month == now.month &amp;&amp; day == now.day;
  }

  bool get isYesterday {
    final yesterday = DateTime.now().subtract(Duration(days: 1));
    return year == yesterday.year &amp;&amp;
           month == yesterday.month &amp;&amp;
           day == yesterday.day;
  }

  String get toFormattedString {
    return &#039;$year-${month.toString().padLeft(2, &#039;0&#039;)}-${day.toString().padLeft(2, &#039;0&#039;)}&#039;;
  }

  DateTime get startOfDay {
    return DateTime(year, month, day);
  }

  DateTime get endOfDay {
    return DateTime(year, month, day, 23, 59, 59, 999);
  }
}

void main() {
  var now = DateTime.now();
  print(now.isToday);           // true
  print(now.toFormattedString); // 2026-02-07
}
3. 集合操作
extension ListExtension on List {
  List chunked(int size) {
    var chunks = &lt;List&gt;[];
    for (var i = 0; i &lt; length; i += size) {
      chunks.add(sublist(i, i + size &gt; length ? length : i + size));
    }
    return chunks;
  }

  T? get firstOrNull {
    return isEmpty ? null : first;
  }

  T? get lastOrNull {
    return isEmpty ? null : last;
  }

  List distinctBy&lt;T&gt;(T Function(dynamic) key) {
    final seen = &lt;T&gt;{};
    return where((element) {
      final k = key(element);
      if (seen.contains(k)) {
        return false;
      }
      seen.add(k);
      return true;
    }).toList();
  }
}

void main() {
  var list = [1, 2, 3, 4, 5, 6, 7, 8, 9];
  print(list.chunked(3));  // [[1, 2, 3], [4, 5, 6], [7, 8, 9]]

  var empty = &lt;int&gt;[];
  print(empty.firstOrNull);  // null

  var users = [
    {&#039;id&#039;: 1, &#039;name&#039;: &#039;Alice&#039;},
    {&#039;id&#039;: 2, &#039;name&#039;: &#039;Bob&#039;},
    {&#039;id&#039;: 1, &#039;name&#039;: &#039;Alice&#039;},
  ];
  var distinct = users.distinctBy((u) =&gt; u[&#039;id&#039;]);
  print(distinct.length);  // 2
}
4. 数字操作
extension NumExtension on num {
  String get toCurrency {
    return &#039;\$${toStringAsFixed(2)}&#039;;
  }

  String get toPercent {
    return &#039;${toStringAsFixed(1)}%&#039;;
  }

  Duration get milliseconds =&gt; Duration(microseconds: toInt() * 1000);
  Duration get seconds =&gt; Duration(seconds: toInt());
  Duration get minutes =&gt; Duration(minutes: toInt());
  Duration get hours =&gt; Duration(hours: toInt());
  Duration get days =&gt; Duration(days: toInt());
}

void main() {
  print(123.456.toCurrency);  // $123.46
  print(0.756.toPercent);     // 0.8%
  print(5.minutes);           // 0:05:00.000000
  print(2.days);              // 48:00:00.000000
}
5. 颜色处理
extension ColorExtension on String {
  int get toColor {
    var hexColor = replaceAll(&#039;#&#039;, &#039;&#039;);
    if (hexColor.length == 6) {
      hexColor = &#039;FF$hexColor&#039;;
    }
    return int.parse(hexColor, radix: 16);
  }
}

void main() {
  print(&#039;#FF5733&#039;.toColor);  // 4282736051
  print(&#039;FF5733&#039;.toColor);   // 4282736051
}
扩展的局限性
不能扩展的内容
// ❌ 不能添加实例变量
extension MyExtension on String {
  // int myVariable;  // 编译错误
}

// ❌ 不能扩展 final 类以添加成员
extension on String {
  // String 是 final 的，但这不影响扩展方法

// ❌ 不能重写现有成员
extension on String {
  // int toInt() { }  // 编译错误：成员已存在
}

// ❌ 不能实现接口
extension MyExtension on String {
  // void myMethod() implements SomeInterface { }
}
扩展 vs 继承 vs Mixin









































特性扩展继承Mixin是否修改原类否是是是否需要继承否是是（with）是否支持第三方类是否否是否有运行时开销无无无是否可以访问私有成员否是是
使用建议
// ✅ 使用扩展：为第三方库添加功能
extension StringX on String {
  bool get isValidEmail { }
}

// ✅ 使用继承：IS-A 关系
class Dog extends Animal { }

// ✅ 使用 Mixin：代码复用
class Dog with Flying { }
最佳实践

[!tip&gt; 扩展使用建议



为扩展添加文档
/// Extension on String to provide validation methods.
extension StringValidation on String {
  /// Returns true if the string is a valid email address.
  bool get isEmail { }
}


谨慎扩展常用类
// ⚠️ 避免为 String、int 等常用类添加过多扩展
// 可能导致命名冲突和代码混乱


使用有意义的命名
extension DateTimeFormatting on DateTime { }  // ✅ 清晰
extension DateUtils on DateTime { }            // ✅ 清晰
extension MyExtension on DateTime { }          // ❌ 不明确


避免过度使用
// ❌ 不要用扩展替代简单的工具函数
extension on int {
  int add(int a, int b) =&gt; a + b;  // 应该是普通函数
}


