30-resources/开发/dart/02-面向对象篇/抽象类与接口.content:
抽象类与接口



                  概述 



抽象类定义了类的通用接口和行为模板，接口定义了类必须实现的方法。Dart 中的每个类都隐式定义了接口，这与许多其他语言不同。
抽象类
abstract 关键字
abstract class Shape {
  // 抽象方法（没有实现）
  double area();
  double perimeter();

  // 具体方法（有实现）
  void describe() {
    print(&#039;Area: ${area()}, Perimeter: ${perimeter()}&#039;);
  }
}

class Circle extends Shape {
  final double radius;

  Circle(this.radius);

  @override
  double area() =&gt; 3.14 * radius * radius;

  @override
  double perimeter() =&gt; 2 * 3.14 * radius;
}

void main() {
  // Shape shape = Shape();  // ❌ 不能实例化抽象类
  Shape circle = Circle(5);  // ✅ 可以使用子类
  circle.describe();
}
抽象类的特点
abstract class Animal {
  String? name;

  // 抽象方法：子类必须实现
  void makeSound();

  // 具体方法：子类可以直接使用或重写
  void sleep() {
    print(&#039;$name is sleeping&#039;);
  }

  // 可以有构造函数（但只能被子类调用）
  Animal(this.name);
}

class Dog extends Animal {
  String breed;

  Dog(String name, this.breed) : super(name);

  @override
  void makeSound() {
    print(&#039;$name barks&#039;);
  }
}
接口
隐式接口
在 Dart 中，每个类都隐式定义了一个接口：
class Person {
  final String name;
  final int age;

  Person(this.name, this.age);

  void greet() {
    print(&#039;Hello, I am $name&#039;);
  }

  int getBirthYear() {
    return DateTime.now().year - age;
  }
}

// implements 实现接口
class Employee implements Person {
  @override
  final String name;
  @override
  final int age;
  final String job;

  Employee(this.name, this.age, this.job);

  @override
  void greet() {
    print(&#039;Hi, I am $name, working as $job&#039;);
  }

  @override
  int getBirthYear() {
    return DateTime.now().year - age;
  }
}

void main() {
  Employee emp = Employee(&#039;Alice&#039;, 30, &#039;Engineer&#039;);
  emp.greet();
}
显式接口（interface modifier）
Dart 3 引入了 interface 和 final 修饰符：
// interface class - 只能实现，不能继承
interface class Shape {
  double area();
  double perimeter();
}

class Circle implements Shape {
  final double radius;
  Circle(this.radius);

  @override
  double area() =&gt; 3.14 * radius * radius;

  @override
  double perimeter() =&gt; 2 * 3.14 * radius;
}

// class AnotherCircle extends Shape { }  // ❌ 不能继承 interface class

// final class - 不能被继承或实现
final class Constants {
  static const pi = 3.14;
  static const e = 2.718;
}
实现多个接口
class Runnable {
  void run() {
    print(&#039;Running&#039;);
  }
}

class Flyable {
  void fly() {
    print(&#039;Flying&#039;);
  }
}

class SuperHero implements Runnable, Flyable {
  @override
  void run() {
    print(&#039;Running fast&#039;);
  }

  @override
  void fly() {
    print(&#039;Flying high&#039;);
  }
}
抽象类 vs 接口













































特性抽象类接口关键字abstract classinterface class 或普通类实现方式extendsimplements能否实例化否否能有构造函数是否能有实例变量是否（只有接口）能有具体方法是否单/多实现单继承多实现
使用场景
// 抽象类：部分实现
abstract class Animal {
  String name;

  Animal(this.name);

  void sleep() {  // 具体方法
    print(&#039;$name sleeps&#039;);
  }

  void makeSound();  // 抽象方法
}

// 接口：纯规范
interface class Drawable {
  void draw();
  void clear();
}

class Dog extends Animal implements Drawable {
  Dog(String name) : super(name);

  @override
  void makeSound() {
    print(&#039;$name barks&#039;);
  }

  @override
  void draw() {
    print(&#039;Drawing a dog&#039;);
  }

  @override
  void clear() {
    print(&#039;Clearing the dog&#039;);
  }
}
接口的实现要求
必须实现所有成员
class Interface {
  void method1() {}
  void method2() {}
  int get getter =&gt; 0;
  set setter(int value) {}
}

class Implementation implements Interface {
  @override
  void method1() {}

  @override
  void method2() {}

  @override
  int get getter =&gt; 0;

  @override
  set setter(int value) {}
}
接口不支持实现
class Interface {
  void method() {
    print(&#039;Default implementation&#039;);
  }
}

class Implementation implements Interface {
  @override
  void method() {
    // ❌ 不能调用 super.method()
    // 必须提供自己的实现
    print(&#039;New implementation&#039;);
  }
}
抽象类与接口的组合使用
// 抽象基类
abstract class Vehicle {
  String brand;
  int year;

  Vehicle(this.brand, this.year);

  void start() {
    print(&#039;$brand vehicle started&#039;);
  }

  abstract void drive();
}

// 接口
interface class Electric {
  void charge();
  int get batteryLevel;
}

// 组合使用
class ElectricCar extends Vehicle implements Electric {
  int _batteryLevel = 100;

  ElectricCar(String brand, int year) : super(brand, year);

  @override
  void drive() {
    print(&#039;Driving electric car&#039;);
  }

  @override
  void charge() {
    _batteryLevel = 100;
    print(&#039;Charged to 100%&#039;);
  }

  @override
  int get batteryLevel =&gt; _batteryLevel;
}
常见模式
1. 策略模式
interface class SortStrategy {
  List&lt;int&gt; sort(List&lt;int&gt; data);
}

class BubbleSort implements SortStrategy {
  @override
  List&lt;int&gt; sort(List&lt;int&gt; data) {
    // 冒泡排序实现
    return data..sort();
  }
}

class QuickSort implements SortStrategy {
  @override
  List&lt;int&gt; sort(List&lt;int&gt; data) {
    // 快速排序实现
    return data..sort();
  }
}

class Sorter {
  final SortStrategy strategy;

  Sorter(this.strategy);

  List&lt;int&gt; sort(List&lt;int&gt; data) {
    return strategy.sort(data);
  }
}
2. 模板方法模式
abstract class DataProcessor {
  // 模板方法
  void process(String data) {
    validate(data);
    var transformed = transform(data);
    save(transformed);
  }

  void validate(String data) {
    if (data.isEmpty) {
      throw ArgumentError(&#039;Data cannot be empty&#039;);
    }
  }

  String transform(String data);
  void save(String data);
}

class UpperCaseProcessor extends DataProcessor {
  @override
  String transform(String data) {
    return data.toUpperCase();
  }

  @override
  void save(String data) {
    print(&#039;Saving: $data&#039;);
  }
}
3. 适配器模式
interface class Target {
  void request();
}

class Adaptee {
  void specificRequest() {
    print(&#039;Specific request&#039;);
  }
}

class Adapter implements Target {
  final Adaptee _adaptee;

  Adapter(this._adaptee);

  @override
  void request() {
    _adaptee.specificRequest();
  }
}
最佳实践



                  设计建议 





抽象类用于部分实现
abstract class Animal {
  void sleep() { }  // 共同实现
  void makeSound();  // 子类实现
}


接口用于定义契约
interface class Drawable {
  void draw();
}


优先使用组合而不是继承
class Dog extends Animal { }  // ✅ IS-A 关系
class Dog with Flying { }    // ✅ 能力组合


使用 interface class 明确意图
interface class Shape { }  // 只能实现
abstract class Animal { }  // 可以继承


常见陷阱



                  陷阱 1：混淆 implements 和 extends 



class Base {
  void method() { }
}

// ❌ 错误使用
class Derived implements Base {
  // 必须实现所有方法，不能使用 super.method()
}

// ✅ 正确使用
class Derived extends Base {
  @override
  void method() {
    super.method();  // 可以调用父类方法
  }
}

[!danger&gt; 陷阱 2：抽象类的构造函数

abstract class Base {
  Base(String name) { }
}

class Derived extends Base {
  Derived(String name) : super(name);  // ✅ 必须调用父类构造函数
}

[!danger&gt; 陷阱 3：接口的私有成员

class Interface {
  void _privateMethod() { }
}

class Implementation implements Interface {
  // ❌ 不需要实现私有方法
  // 但也访问不到 Interface 的私有成员
}
相关概念

继承机制 - extends 的使用
Mixin 机制 - 代码复用
类与对象 - 类的基础

