Dart 抽象类
Dart 接口
Dart 3 接口修饰符

30-resources/开发/dart/02-面向对象篇/构造函数.content:
构造函数



                  概述 



构造函数用于创建和初始化类的实例。Dart 提供了多种构造函数形式，包括默认构造函数、命名构造函数、常量构造函数、工厂构造函数等。
默认构造函数
生成默认构造函数
class Point {
  double x;
  double y;

  // 默认构造函数
  Point(this.x, this.y);
}

// 使用
var p = Point(10.0, 20.0);
未声明构造函数
class Person {
  String? name;
  int? age;

  // 如果没有声明构造函数，Dart 提供默认构造函数
}

// 使用
var person = Person();  // ✅ 使用默认构造函数
person.name = &#039;Alice&#039;;
person.age = 30;
自定义构造函数
class Point {
  double x;
  double y;

  Point(double x, double y) {
    this.x = x;
    this.y = y;
  }

  // 等价于使用语法糖
  // Point(this.x, this.y);
}
命名构造函数
基本语法
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  // 命名构造函数
  Point.origin()
      : x = 0,
        y = 0;

  Point.fromJson(Map&lt;String, dynamic&gt; json)
      : x = json[&#039;x&#039;]?.toDouble() ?? 0.0,
        y = json[&#039;y&#039;]?.toDouble() ?? 0.0;
}

// 使用
void main() {
  var p1 = Point(10.0, 20.0);
  var p2 = Point.origin();
  var p3 = Point.fromJson({&#039;x&#039;: 5.0, &#039;y&#039;: 15.0});
}
多个命名构造函数
class Color {
  final int red;
  final int green;
  final int blue;

  const Color(this.red, this.green, this.blue);

  // 命名构造函数
  Color.black()
      : red = 0,
        green = 0,
        blue = 0;

  Color.white()
      : red = 255,
        green = 255,
        blue = 255;

  Color.red()
      : red = 255,
        green = 0,
        blue = 0;
}
常量构造函数
定义常量构造函数
class Point {
  final double x;
  final double y;

  const Point(this.x, this.y);
}

// 使用
void main() {
  const p1 = Point(0, 0);
  const p2 = Point(0, 0);

  print(identical(p1, p2));  // true - 同一个实例

  // 编译时常量
  var p3 = const Point(1, 1);
}
常量构造函数的要求
class Point {
  // ✅ 所有字段必须是 final
  final double x;
  final double y;

  // ✅ 只能初始化字段，不能有其他逻辑
  const Point(this.x, this.y);
}

class InvalidPoint {
  double x;  // ❌ 不是 final
  double y;

  // const InvalidPoint(this.x, this.y);  // ❌ 编译错误
}
工厂构造函数
基本语法
class Logger {
  final String name;
  static final Map&lt;String, Logger&gt; _cache = {};

  // 私有构造函数
  Logger._(this.name);

  // 工厂构造函数
  factory Logger(String name) {
    return _cache.putIfAbsent(name, () =&gt; Logger._(name));
  }
}

// 使用
void main() {
  var logger1 = Logger(&#039;app&#039;);
  var logger2 = Logger(&#039;app&#039;);

  print(identical(logger1, logger2));  // true
}
单例模式
class Database {
  static Database? _instance;

  // 私有构造函数
  Database._();

  // 工厂构造函数
  factory Database.getInstance() {
    _instance ??= Database._();
    return _instance!;
  }

  void connect() {
    print(&#039;Connected to database&#039;);
  }
}

// 使用
void main() {
  var db1 = Database.getInstance();
  var db2 = Database.getInstance();

  print(identical(db1, db2));  // true
}
工厂构造函数返回子类
abstract class Shape {
  factory Shape(String type) {
    switch (type) {
      case &#039;circle&#039;:
        return Circle() as Shape;
      case &#039;square&#039;:
        return Square() as Shape;
      default:
        throw ArgumentError(&#039;Invalid type&#039;);
    }
  }

  void draw();
}

class Circle implements Shape {
  @override
  void draw() {
    print(&#039;Drawing circle&#039;);
  }
}

class Square implements Shape {
  @override
  void draw() {
    print(&#039;Drawing square&#039;);
  }
}
重定向构造函数
基本语法
class Point {
  double x;
  double y;

  Point(this.x, this.y);

  // 重定向到主构造函数
  Point.alongX(double x) : this(x, 0);
  Point.alongY(double y) : this(0, y);
}

// 使用
void main() {
  var p1 = Point.alongX(10);  // Point(10, 0)
  var p2 = Point.alongY(20);  // Point(0, 20)
}
重定向到命名构造函数
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  Point.origin() : this(0, 0);

  // 重定向到命名构造函数
  Point.unit() : this.origin();
}
初始化列表
基本语法
class Point {
  final double x;
  final double y;

  Point(double x, double y)
      : x = x,
        y = y;

  // 使用表达式
  Point.fromList(List&lt;double&gt; coords)
      : assert(coords.length &gt;= 2),
        x = coords[0],
        y = coords[1];
}
初始化列表的用途
class Rectangle {
  final double width;
  final double height;
  final double area;

  // 在构造函数体执行前计算 area
  Rectangle(double width, double height)
      : width = width,
        height = height,
        area = width * height;

  // 验证
  Rectangle.square(double size)
      : assert(size &gt; 0),
        width = size,
        height = size,
        area = size * size;
}
使用 this
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  // 初始化列表中使用 this
  Point.clone(Point other)
      : x = other.x,
        y = other.y;
}
super 构造函数
调用父类构造函数
class Animal {
  String name;

  Animal(this.name);
}

class Dog extends Animal {
  String breed;

  // 调用父类构造函数
  Dog(String name, this.breed) : super(name);
}
初始化列表中调用 super
class Vector2D {
  final double x;
  final double y;

  Vector2D(this.x, this.y);
}

class Vector3D extends Vector2D {
  final double z;

  Vector3D(double x, double y, this.z) : super(x, y);
}
初始化顺序
class Parent {
  final String value;

  Parent() : value = &#039;parent&#039; {
    print(&#039;Parent constructor body&#039;);
  }
}

class Child extends Parent {
  final String childValue;

  Child()
      : childValue = &#039;child&#039;,
        super() {
    print(&#039;Child constructor body&#039;);
  }
}

// 执行顺序：
// 1. 初始化列表（childValue）
// 2. 父类初始化列表（value）
// 3. 父类构造函数体
// 4. 子类构造函数体
const 构造函数 vs final
class Point {
  final double x;
  final double y;

  const Point(this.x, this.y);
}

void main() {
  // const - 编译时常量
  const p1 = Point(0, 0);
  const p2 = Point(0, 0);
  print(identical(p1, p2));  // true

  // final - 运行时常量
  final p3 = Point(0, 0);
  final p4 = Point(0, 0);
  print(identical(p3, p4));  // 可能是 false
}
构造函数的最佳实践



                  构造函数建议 





使用 const 构造函数：对于不可变对象
class Point {
  final double x;
  final double y;
  const Point(this.x, this.y);
}


提供命名构造函数：提高代码可读性
Point.origin()
Point.fromJson(Map json)


使用工厂构造函数：用于缓存或单例
factory Logger(String name) {
  return _cache.putIfAbsent(name, () =&gt; Logger._(name));
}


初始化列表：用于计算 final 字段
Rectangle(double width, double height)
    : area = width * height;


私有构造函数：防止实例化
class Singleton {
  Singleton._();
  factory Singleton() =&gt; _instance;
}


常见模式
1. 不可变对象
class ImmutablePoint {
  final double x;
  final double y;

  const ImmutablePoint(this.x, this.y);

  ImmutablePoint move(double dx, double dy) {
    return ImmutablePoint(x + dx, y + dy);
  }
}
2. 建造者模式
class Pizza {
  final String size;
  final List&lt;String&gt; toppings;

  Pizza._(this.size, this.toppings);

  factory Pizza.create() {
    return Pizza._(&#039;medium&#039;, []);
  }

  Pizza addTopping(String topping) {
    return Pizza._(size, [...toppings, topping]);
  }
}
3. 工厂模式
abstract class Message {
  factory Message.fromJson(Map&lt;String, dynamic&gt; json) {
    final type = json[&#039;type&#039;] as String;
    switch (type) {
      case &#039;text&#039;:
        return TextMessage(json[&#039;content&#039;] as String);
      case &#039;image&#039;:
        return ImageMessage(json[&#039;url&#039;] as String);
      default:
        throw ArgumentError(&#039;Unknown type: $type&#039;);
    }
  }

  void send();
}

class TextMessage implements Message {
  final String content;
  TextMessage(this.content);

  @override
  void send() {
    print(&#039;Sending text: $content&#039;);
  }
}

class ImageMessage implements Message {
  final String url;
  ImageMessage(this.url);

  @override
  void send() {
    print(&#039;Sending image: $url&#039;);
  }
}
常见陷阱

[!danger&gt; 陷阱 1：const 构造函数字段不是 final

class Point {
  double x;  // ❌ 不是 final
  double y;

  // const Point(this.x, this.y);  // ❌ 编译错误
}

[!danger&gt; 陷阱 2：初始化列表访问 this

class Point {
  final double x;
  final double y;

  // Point(double x, double y)
  //     : this.x = x,
  //       this.y = y;  // ❌ 不能在初始化列表中使用 this

  Point(this.x, this.y);  // ✅ 正确
}

[!danger&gt; 陷阱 3：工厂构造函数中访问实例成员

class Example {
  String value = &#039;hello&#039;;

  factory Example.create() {
    // print(value);  // ❌ 不能在工厂构造函数中访问实例成员
    return Example._();
  }

  Example._();
}
