类与对象



                  概述 



Dart 是完全面向对象的语言，一切皆对象。类是对象的模板，定义了对象的属性和行为。理解类与对象是掌握 Dart 面向对象编程的基础。
类的基本概念
在 Dart 中：

类：对象的模板或蓝图
对象：类的实例
属性：对象的状态（变量）
方法：对象的行为（函数）

定义类
基本语法
class Person {
  // 属性（实例变量）
  String name;
  int age;

  // 构造函数
  Person(this.name, this.age);

  // 方法
  void greet() {
    print(&#039;Hello, my name is $name&#039;);
  }

  void introduce() {
    print(&#039;I am $age years old&#039;);
  }
}

// 使用类
void main() {
  // 创建对象实例
  var person = Person(&#039;Alice&#039;, 30);

  // 访问属性
  print(person.name);  // Alice
  print(person.age);   // 30

  // 调用方法
  person.greet();      // Hello, my name is Alice
  person.introduce();  // I am 30 years old
}
实例变量
成员变量
class Point {
  // 公共变量（隐式 getter/setter）
  int x;
  int y;

  Point(this.x, this.y);
}

// 使用
var point = Point(10, 20);
point.x = 15;  // setter
print(point.x);  // getter
私有变量
class BankAccount {
  // 私有变量（以下划线开头）
  double _balance = 0.0;

  // 公共方法访问私有变量
  void deposit(double amount) {
    if (amount &gt; 0) {
      _balance += amount;
    }
  }

  double get balance =&gt; _balance;
}



                  库级别的私有 




Dart 的私有是库级别的，不是类级别的
同一个库（.dart 文件）中的代码可以访问 _ 开头的成员

Getter 和 Setter
自定义访问器
class Rectangle {
  double width;
  double height;

  Rectangle(this.width, this.height);

  // 计算属性（getter）
  double get area =&gt; width * height;

  double get perimeter =&gt; 2 * (width + height);

  // 带验证的 setter
  set width(double value) {
    if (value &lt;= 0) {
      throw ArgumentError(&#039;Width must be positive&#039;);
    }
    width = value;
  }
}

// 使用
var rect = Rectangle(10, 20);
print(rect.area);  // 200.0
print(rect.perimeter);  // 60.0
计算属性
class Circle {
  double _radius;

  Circle(this._radius);

  // getter
  double get radius =&gt; _radius;

  // setter
  set radius(double value) {
    if (value &lt; 0) {
      throw ArgumentError(&#039;Radius cannot be negative&#039;);
    }
    _radius = value;
  }

  // 计算属性
  double get area =&gt; 3.14 * _radius * _radius;
  double get circumference =&gt; 2 * 3.14 * _radius;
}
方法
实例方法
class Calculator {
  // 普通方法
  int add(int a, int b) {
    return a + b;
  }

  // 表达式方法
  int multiply(int a, int b) =&gt; a * b;

  // 访问实例状态
  int addToMemory(int value) {
    _memory += value;
    return _memory;
  }

  int _memory = 0;
}
运算符重载
class Vector {
  final double x;
  final double y;

  Vector(this.x, this.y);

  // 运算符重载
  Vector operator +(Vector other) {
    return Vector(x + other.x, y + other.y);
  }

  Vector operator -(Vector other) {
    return Vector(x - other.x, y - other.y);
  }

  @override
  String toString() =&gt; &#039;Vector($x, $y)&#039;;
}

// 使用
var v1 = Vector(1, 2);
var v2 = Vector(3, 4);
var sum = v1 + v2;  // Vector(4.0, 6.0)
print(sum);  // Vector(4.0, 6.0)
可调用类
class Adder {
  int call(int a, int b) {
    return a + b;
  }
}

// 使用
var adder = Adder();
print(adder(5, 3));  // 8
print(adder.call(10, 20));  // 30
构造函数
默认构造函数
class Person {
  String name;
  int age;

  // 语法糖：自动初始化字段
  Person(this.name, this.age);
}

// 等价于
class Person {
  String name;
  int age;

  Person(String name, int age) {
    this.name = name;
    this.age = age;
  }
}
命名构造函数
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  // 命名构造函数
  Point.origin()
      : x = 0,
        y = 0;

  Point.fromJson(Map&lt;String, dynamic&gt; json)
      : x = json[&#039;x&#039;] ?? 0,
        y = json[&#039;y&#039;] ?? 0;

  Point.copy(Point other)
      : x = other.x,
        y = other.y;
}

// 使用
var p1 = Point(10, 20);
var p2 = Point.origin();
var p3 = Point.fromJson({&#039;x&#039;: 5, &#039;y&#039;: 15});
var p4 = Point.copy(p1);
常量构造函数
class Point {
  final double x;
  final double y;

  const Point(this.x, this.y);

  @override
  String toString() =&gt; &#039;Point($x, $y)&#039;;
}

// 使用
const p1 = const Point(0, 0);
const p2 = Point(0, 0);  // 省略 const
print(identical(p1, p2));  // true - 同一个实例
工厂构造函数
class Singleton {
  static Singleton? _instance;

  // 私有构造函数
  Singleton._();

  // 工厂构造函数
  factory Singleton() {
    _instance ??= Singleton._();
    return _instance!;
  }
}

// 使用
var s1 = Singleton();
var s2 = Singleton();
print(identical(s1, s2));  // true



                  更多构造函数内容 



参见 构造函数 了解更多构造函数的详细用法。
对象初始化
初始化列表
class Point {
  final double x;
  final double y;

  Point(double x, double y)
      : x = x,
        y = y;

  // 验证和转换
  Point.validated(double x, double y)
      : assert(x &gt;= 0 &amp;&amp; y &gt;= 0),
        x = x.abs(),
        y = y.abs();
}
重定向构造函数
class Point {
  double x;
  double y;

  Point(this.x, this.y);

  // 重定向到主构造函数
  Point.alongX(double x) : this(x, 0);
  Point.alongY(double y) : this(0, y);
}
对象的比较
class Person {
  String name;
  int age;

  Person(this.name, this.age);

  // == 操作符
  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is Person &amp;&amp; other.name == name &amp;&amp; other.age == age;
  }

  // hashCode
  @override
  int get hashCode =&gt; name.hashCode ^ age.hashCode;
}

// 使用
var p1 = Person(&#039;Alice&#039;, 30);
var p2 = Person(&#039;Alice&#039;, 30);
print(p1 == p2);  // true
print(p1.hashCode == p2.hashCode);  // true
对象的字符串表示
class Person {
  String name;
  int age;

  Person(this.name, this.age);

  // toString 方法
  @override
  String toString() {
    return &#039;Person(name: $name, age: $age)&#039;;
  }

  // 更简洁的版本
  // @override
  // String toString() =&gt; &#039;Person(name: $name, age: $age)&#039;;
}

// 使用
var person = Person(&#039;Alice&#039;, 30);
print(person);  // Person(name: Alice, age: 30)
print(person.toString());  // Person(name: Alice, age: 30)
noSuchMethod
class Proxy {
  @override
  void noSuchMethod(Invocation invocation) {
    print(&#039;Method ${invocation.memberName} not found&#039;);
  }
}

// 使用
var proxy = Proxy();
proxy.someMethod();  // Method someMethod not found
对象生命周期
class Resource {
  final String id;
  Resource(this.id) {
    print(&#039;Resource $id created&#039;);
  }

  // Dart 没有析构函数
  // 但可以实现 close 方法
  void close() {
    print(&#039;Resource $id closed&#039;);
  }
}

// 使用 with 语句模式
void useResource() {
  var resource = Resource(&#039;file.txt&#039;);
  try {
    // 使用资源
  } finally {
    resource.close();  // 确保清理
  }
}
最佳实践



                  类设计建议 





不可变性：优先使用 final 字段
class Point {
  final double x;
  final double y;
  const Point(this.x, this.y);
}


封装：隐藏内部实现
class BankAccount {
  double _balance = 0;
  double get balance =&gt; _balance;
  void deposit(double amount) { ... }
}


构造函数：提供便利的构造方法
Point.origin()
Point.fromJson(Map json)


toString：始终实现 toString 方法
@override
String toString() =&gt; &#039;ClassName(field1: $field1)&#039;;


操作符：谨慎重载操作符
bool operator ==(Object other) { ... }
int get hashCode =&gt; ...;


常见模式
1. 不可变对象
class ImmutablePoint {
  final double x;
  final double y;

  const ImmutablePoint(this.x, this.y);

  ImmutablePoint move(double dx, double dy) {
    return ImmutablePoint(x + dx, y + dy);
  }
}
2. Builder 模式
class Person {
  final String name;
  final int age;
  final String? email;

  Person._({required this.name, required this.age, this.email});

  factory Person.create() =&gt; Person._(name: &#039;&#039;, age: 0);
}
3. 单例模式
class Database {
  static Database? _instance;
  static Database get instance {
    _instance ??= Database._();
    return _instance!;
  }

  Database._();

  void connect() {
    print(&#039;Connected&#039;);
  }
}
相关概念

构造函数 - 各种构造函数的详解
继承机制 - 类的继承
Mixin 机制 - 代码复用机制

