Dart 类文档
Dart 实例变量
Effective Dart - 设计

30-resources/开发/dart/02-面向对象篇/继承机制.content:
继承机制



                  概述 



继承是面向对象编程的核心概念之一，允许创建新类复用现有类的属性和方法。Dart 使用 extends 关键字实现单继承。
基本继承
extends 关键字
class Animal {
  String name;

  Animal(this.name);

  void eat() {
    print(&#039;$name is eating&#039;);
  }

  void sleep() {
    print(&#039;$name is sleeping&#039;);
  }
}

class Dog extends Animal {
  String breed;

  Dog(String name, this.breed) : super(name);

  void bark() {
    print(&#039;$name is barking&#039;);
  }
}

void main() {
  var dog = Dog(&#039;Buddy&#039;, &#039;Golden Retriever&#039;);
  dog.eat();    // 继承的方法
  dog.sleep();  // 继承的方法
  dog.bark();   // 自己的方法
}
super 关键字
调用父类构造函数
class Animal {
  String name;

  Animal(this.name);

  void makeSound() {
    print(&#039;Some sound&#039;);
  }
}

class Cat extends Animal {
  Cat(String name) : super(name);

  // 隐式调用父类无参构造函数
  // Cat(String name) : super(name);
}
调用父类方法
class Animal {
  void makeSound() {
    print(&#039;Animal sound&#039;);
  }
}

class Dog extends Animal {
  @override
  void makeSound() {
    super.makeSound();  // 调用父类方法
    print(&#039;Bark bark&#039;);
  }
}

void main() {
  var dog = Dog();
  dog.makeSound();
  // Animal sound
  // Bark bark
}
调用父类 getter/setter
class Rectangle {
  double width;
  double height;

  Rectangle(this.width, this.height);

  double get area =&gt; width * height;
}

class Square extends Rectangle {
  Square(double side) : super(side, side);

  @override
  set width(double value) {
    super.width = value;
    super.height = value;  // 保持正方形
  }
}
方法重写
@override 注解
class Animal {
  void makeSound() {
    print(&#039;Animal sound&#039;);
  }
}

class Dog extends Animal {
  @override
  void makeSound() {
    print(&#039;Woof woof&#039;);
  }
}

void main() {
  Animal animal = Dog();
  animal.makeSound();  // Woof woof（多态）
}
重写规则
class Parent {
  void method1() {}
  int method2() =&gt; 0;
}

class Child extends Parent {
  @override
  void method1() {
    // ✅ 返回类型兼容
  }

  @override
  int method2() {
    // ✅ 返回类型相同或子类型
    return 1;
  }

  // @override
  // String method2() =&gt; &#039;0&#039;;  // ❌ 返回类型不兼容
}
协变返回类型
class Animal {
  Animal create() {
    return Animal();
  }
}

class Dog extends Animal {
  @override
  Dog create() {
    // ✅ 返回子类型（协变）
    return Dog();
  }
}
多态
向上转型
class Animal {
  void makeSound() {
    print(&#039;Animal sound&#039;);
  }
}

class Dog extends Animal {
  @override
  void makeSound() {
    print(&#039;Bark&#039;);
  }
}

class Cat extends Animal {
  @override
  void makeSound() {
    print(&#039;Meow&#039;);
  }
}

void main() {
  Animal dog = Dog();  // 向上转型
  Animal cat = Cat();

  dog.makeSound();  // Bark
  cat.makeSound();  // Meow

  List&lt;Animal&gt; animals = [Dog(), Cat()];
  for (var animal in animals) {
    animal.makeSound();  // 多态调用
  }
}
向下转型
void main() {
  Animal animal = Dog();

  if (animal is Dog) {
    var dog = animal as Dog;  // 向下转型
    // 或者直接使用 animal（类型提升）
    print(&#039;It\&#039;s a dog&#039;);
  }

  // 不安全的转换
  // var cat = animal as Cat;  // ❌ 抛出异常
}
继承的限制
单继承
class A {
  void methodA() {}
}

class B {
  void methodB() {}
}

// ❌ Dart 不支持多继承
// class C extends A, B { }

// ✅ 使用 Mixin 实现多继承的效果
class C extends A with B {
  void methodC() {}
}
继承 Object
// 所有类都隐式继承自 Object
class Example {
  // 继承了 Object 的方法：
  // - toString()
  // - == operator
  // - hashCode
  // - noSuchMethod()
  // - runtimeType
}

void main() {
  var example = Example();
  print(example.toString());  // Instance of &#039;Example&#039;
  print(example.hashCode);
  print(example.runtimeType);  // Example
}
抽象类与继承
abstract class Shape {
  // 抽象方法
  double area();

  // 具体方法
  void describe() {
    print(&#039;Area: ${area()}&#039;);
  }
}

class Circle extends Shape {
  final double radius;

  Circle(this.radius);

  @override
  double area() =&gt; 3.14 * radius * radius;
}

class Rectangle extends Shape {
  final double width;
  final double height;

  Rectangle(this.width, this.height);

  @override
  double area() =&gt; width * height;
}
接口与继承
// 每个类都隐式定义了接口
class Animal {
  void makeSound() {
    print(&#039;Sound&#039;);
  }
}

// 实现接口
class MockAnimal implements Animal {
  @override
  void makeSound() {
    print(&#039;Mock sound&#039;);
  }
}

// 同时继承和实现
class Dog extends Animal implements Runnable {
  @override
  void makeSound() {
    print(&#039;Bark&#039;);
  }

  @override
  void run() {
    print(&#039;Running&#039;);
  }
}

abstract class Runnable {
  void run();
}
继承的设计原则



                  继承建议 





优先使用组合而不是继承
// ❌ 过度使用继承
class FlyingDog extends Dog { }

// ✅ 使用组合
class Dog with Flying { }


明确继承关系
// ✅ IS-A 关系
class Dog extends Animal { }  // Dog IS-A Animal

// ❌ HAS-A 关系不应该用继承
// class Engine extends Car { }  // ❌ 错误
class Car {
  Engine engine;  // ✅ 组合
}


遵循里氏替换原则
// 子类应该可以替换父类而不影响程序正确性
void useAnimal(Animal animal) {
  animal.makeSound();  // 应该对所有 Animal 子类有效
}


最佳实践



                  继承最佳实践 





使用 @override 注解
@override
void makeSound() { }


谨慎使用 super
@override
void method() {
  super.method();  // 在必要时调用
  // 添加子类特定行为
}


避免深层继承
// ❌ 过深的继承层次
class A extends B extends C extends D extends E { }

// ✅ 优先使用组合和 Mixin


考虑使用接口
// 当只需要类型定义时，使用 interface
interface class Animal {
  void makeSound();
}


常见陷阱



                  陷阱 1：构造函数不继承 



class Parent {
  Parent(String name) { }
}

class Child extends Parent {
  // Child() { }  // ❌ 父类没有无参构造函数

  Child(String name) : super(name);  // ✅ 正确
}

[!danger&gt; 陷阱 2：重写方法签名不匹配

class Parent {
  void method(String name) { }
}

class Child extends Parent {
  // @override
  // void method(int name) { }  // ❌ 参数类型不同
}

[!danger&gt; 陷阱 3：私有成员不可访问

class Parent {
  void _privateMethod() { }
}

class Child extends Parent {
  void test() {
    // _privateMethod();  // ❌ 不能访问父类私有成员
  }
}
相关概念

类与对象 - 类的基础
构造函数 - super 构造函数
Mixin 机制 - 代码复用的另一种方式
抽象类与接口 - 抽象类和接口

参考资源

Dart 继承文档
Dart 类继承

30-resources/开发/dart/03-进阶特性篇/dart-进阶特性篇.content:
Dart 进阶特性篇



                  模块概述 



本篇介绍 Dart 的高级特性，包括泛型、异步编程、空安全和元编程等。掌握这些特性将帮助你写出更优雅、更高效的 Dart 代码。
学习目标
完成本篇学习后，你将能够：

熟练使用泛型编写通用代码
深入理解异步编程模型
掌握 Future 和 Stream 的使用
理解空安全机制
了解元编程的基本概念

前置知识
在学习本篇之前，请确保已掌握：

Dart 基础篇 的所有内容
Dart 面向对象篇 的所有内容

知识点列表
1. 泛型
Transclude of 泛型系统



                  核心内容 




泛型的基本概念
泛型类和泛型方法
类型参数约束
泛型的使用场景
协变与逆变

2. 异步编程基础
Transclude of 异步编程基础



                  核心内容 




异步编程的概念
Dart 的事件循环
单线程模型
Future 和 Stream 的区别

3. Future 详解
Transclude of future-详解



                  核心内容 




Future 的创建
async 和 await 语法
错误处理
