快速示例



                  进阶特性综合示例 



import &#039;dart:async&#039;;

// 泛型类
class Cache&lt;T&gt; {
  final Map&lt;String, T&gt; _storage = {};

  void set(String key, T value) {
    _storage[key] = value;
  }

  T? get(String key) =&gt; _storage[key];
}

// 异步函数
Future&lt;String&gt; fetchData() async {
  await Future.delayed(Duration(seconds: 1));
  return &#039;Data loaded&#039;;
}

// Stream 创建
Stream&lt;int&gt; countStream() async* {
  for (int i = 1; i &lt;= 5; i++) {
    await Future.delayed(Duration(milliseconds: 500));
    yield i;
  }
}

// 空安全示例
class UserProfile {
  final String name;
  final String? email; // 可空类型

  UserProfile(this.name, [this.email]);

  String get displayEmail =&gt; email ?? &#039;No email&#039;;

  void sendEmail() {
    // 使用 ?.
    email?.trim().toLowerCase();
  }
}

// 使用注解
@deprecated
class OldClass {
  // ...
}

void main() async {
  // 泛型使用
  var cache = Cache&lt;String&gt;();
  cache.set(&#039;key&#039;, &#039;value&#039;);
  print(cache.get(&#039;key&#039;)); // value

  // Future 使用
  var data = await fetchData();
  print(data); // Data loaded

  // Stream 使用
  await for (var count in countStream()) {
    print(&#039;Count: $count&#039;);
  }

  // 空安全使用
  var profile = UserProfile(&#039;Alice&#039;, &#039;alice@example.com&#039;);
  print(profile.displayEmail); // alice@example.com

  var profile2 = UserProfile(&#039;Bob&#039;);
  print(profile2.displayEmail); // No email
}
异步编程最佳实践



                  异步编程建议 




优先使用 async/await：代码更易读
避免嵌套 Future：使用 async/await 展平代码
正确处理错误：使用 try-catch 或 catchError
理解事件循环：避免阻塞事件循环
合理使用 Stream：处理多个异步事件时

泛型使用建议



                  泛型建议 




提高代码复用性：编写通用算法和数据结构
类型安全：编译时检查，减少运行时错误
明确类型参数：使用有意义的命名（如 T, E, K, V）
适当约束：使用 extends 限制类型参数范围

常见误区



                  注意事项 




async 函数返回 Future：即使返回值是 T，实际类型是 Future
await 只能在 async 函数中使用：或在 main() 函数中标记为 async
Stream 是懒加载的：只有订阅时才会开始产生数据
可空类型需要显式处理：不能直接赋值给不可空类型
late 不是延迟加载：只是延迟初始化，访问时会初始化

