30-resources/开发/dart/03-进阶特性篇/stream-详解.content:
Stream 详解



                  概述 



Stream 是 Dart 中处理异步事件序列的核心机制。与 Future 只返回单个异步结果不同，Stream 可以发出多个事件，是处理实时数据流、用户输入、文件读取等场景的理想选择。
Stream 基础
Stream vs Future
// Future - 单个异步结果
Future&lt;int&gt; fetchSingleValue() async {
  await Future.delayed(Duration(seconds: 1));
  return 42;
}

// Stream - 多个异步事件
Stream&lt;int&gt; countNumbers() async* {
  for (int i = 1; i &lt;= 5; i++) {
    await Future.delayed(Duration(seconds: 1));
    yield i;
  }
}

void main() async {
  // Future 返回一个值
  var value = await fetchSingleValue();
  print(value);  // 42

  // Stream 返回多个值
  await for (var count in countNumbers()) {
    print(count);  // 1, 2, 3, 4, 5
  }
}
创建 Stream
// 方式 1：使用 async* 和 yield
Stream&lt;int&gt; countStream() async* {
  for (int i = 1; i &lt;= 5; i++) {
    await Future.delayed(Duration(milliseconds: 500));
    yield i;
  }
}

// 方式 2：使用 StreamController
Stream&lt;int&gt; manualStream() {
  var controller = StreamController&lt;int&gt;();

  Timer.periodic(Duration(seconds: 1), (timer) {
    controller.add(timer.tick);
    if (timer.tick &gt;= 5) {
      timer.cancel();
      controller.close();
    }
  });

  return controller.stream;
}

// 方式 3：从集合创建
Stream&lt;int&gt; streamFromList() {
  return Stream.fromIterable([1, 2, 3, 4, 5]);
}

// 方式 4：使用 periodic
Stream&lt;int&gt; periodicStream() {
  return Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  ).take(5);
}
订阅 Stream
使用 listen
void main() {
  var stream = Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  ).take(5);

  // 订阅 Stream
  var subscription = stream.listen(
    (data) {
      print(&#039;Received: $data&#039;);
    },
    onError: (error) {
      print(&#039;Error: $error&#039;);
    },
    onDone: () {
      print(&#039;Done&#039;);
    },
    cancelOnError: false,  // 错误时取消订阅
  );

  // 取消订阅
  // subscription.cancel();
}
使用 await for
Future&lt;void&gt; consumeStream() async {
  var stream = Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  ).take(5);

  try {
    await for (var value in stream) {
      print(&#039;Received: $value&#039;);
    }
    print(&#039;Done&#039;);
  } catch (e) {
    print(&#039;Error: $e&#039;);
  }
}

void main() {
  consumeStream();
}
Stream 转换
常用转换方法
Future&lt;void&gt; streamTransforms() async {
  var stream = Stream.fromIterable([1, 2, 3, 4, 5]);

  // map - 转换每个元素
  var doubled = stream.map((n) =&gt; n * 2);
  print(&#039;Doubled: ${await doubled.toList()}&#039;);  // [2, 4, 6, 8, 10]

  // where - 过滤元素
  var stream2 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var evens = stream2.where((n) =&gt; n % 2 == 0);
  print(&#039;Evens: ${await evens.toList()}&#039;);  // [2, 4]

  // take - 取前 n 个元素
  var stream3 = Stream.periodic(Duration(seconds: 1), (i) =&gt; i);
  var first5 = stream3.take(5);
  // 输出：0, 1, 2, 3, 4

  // skip - 跳过前 n 个元素
  var stream4 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var skipFirst2 = stream4.skip(2);
  print(&#039;Skip first 2: ${await skipFirst2.toList()}&#039;);  // [3, 4, 5]

  // distinct - 去重
  var stream5 = Stream.fromIterable([1, 2, 2, 3, 3, 3]);
  var unique = stream5.distinct();
  print(&#039;Unique: ${await unique.toList()}&#039;);  // [1, 2, 3]
}
高级转换
Future&lt;void&gt; advancedTransforms() async {
  // expand - 将每个元素展开为多个元素
  var stream1 = Stream.fromIterable([[1, 2], [3, 4], [5]]);
  var expanded = stream1.expand((list) =&gt; list);
  print(&#039;Expanded: ${await expanded.toList()}&#039;);  // [1, 2, 3, 4, 5]

  // asyncMap - 异步转换每个元素
  var stream2 = Stream.fromIterable([1, 2, 3]);
  var asyncMapped = stream2.asyncMap((n) async {
    await Future.delayed(Duration(milliseconds: 100));
    return n * 2;
  });
  print(&#039;Async mapped: ${await asyncMapped.toList()}&#039;);  // [2, 4, 6]

  // scan - 累积器
  var stream3 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var sum = stream3.scan(
    (int acc, int value, int index) =&gt; acc + value,
    0,
  );
  print(&#039;Running sum: ${await sum.toList()}&#039;);  // [1, 3, 6, 10, 15]
}
Stream 操作符
聚合操作
Future&lt;void&gt; aggregateOperations() async {
  var stream = Stream.fromIterable([1, 2, 3, 4, 5]);

  // toList - 转换为 List
  var list = await stream.toList();
  print(&#039;List: $list&#039;);  // [1, 2, 3, 4, 5]

  // toSet - 转换为 Set
  var stream2 = Stream.fromIterable([1, 2, 2, 3, 3]);
  var set = await stream2.toSet();
  print(&#039;Set: $set&#039;);  // {1, 2, 3}

  // length - 计算元素个数
  var stream3 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var length = await stream3.length;
  print(&#039;Length: $length&#039;);  // 5

  // isEmpty - 是否为空
  var stream4 = Stream.empty();
  var isEmpty = await stream4.isEmpty;
  print(&#039;Is empty: $isEmpty&#039;);  // true

  // first - 获取第一个元素
  var stream5 = Stream.fromIterable([1, 2, 3]);
  var first = await stream5.first;
  print(&#039;First: $first&#039;);  // 1

  // last - 获取最后一个元素
  var stream6 = Stream.fromIterable([1, 2, 3]);
  var last = await stream6.last;
  print(&#039;Last: $last&#039;);  // 3

  // single - 确保只有一个元素
  var stream7 = Stream.value(42);
  var single = await stream7.single;
  print(&#039;Single: $single&#039;);  // 42
}
检查操作
Future&lt;void&gt; checkOperations() async {
  var stream = Stream.fromIterable([1, 2, 3, 4, 5]);

  // every - 所有元素是否满足条件
  var allPositive = await stream.every((n) =&gt; n &gt; 0);
  print(&#039;All positive: $allPositive&#039;);  // true

  // any - 是否有元素满足条件
  var stream2 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var hasEven = await stream2.any((n) =&gt; n % 2 == 0);
  print(&#039;Has even: $hasEven&#039;);  // true

  // contains - 是否包含特定元素
  var stream3 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var contains3 = await stream3.contains(3);
  print(&#039;Contains 3: $contains3&#039;);  // true
}
折叠操作
Future&lt;void&gt; foldOperations() async {
  var stream = Stream.fromIterable([1, 2, 3, 4, 5]);

  // reduce - 折叠
  var sum = await stream.reduce((a, b) =&gt; a + b);
  print(&#039;Sum: $sum&#039;);  // 15

  // fold - 带初始值的折叠
  var stream2 = Stream.fromIterable([1, 2, 3, 4, 5]);
  var product = await stream2.fold(1, (acc, n) =&gt; acc * n);
  print(&#039;Product: $product&#039;);  // 120
}
StreamController
基本使用
class Counter {
  final StreamController&lt;int&gt; _controller = StreamController&lt;int&gt;();
  int _count = 0;

  Stream&lt;int&gt; get stream =&gt; _controller.stream;

  void increment() {
    _count++;
    _controller.add(_count);
  }

  void dispose() {
    _controller.close();
  }
}

void main() {
  var counter = Counter();

  var subscription = counter.stream.listen(
    (count) =&gt; print(&#039;Count: $count&#039;),
  );

  counter.increment();  // Count: 1
  counter.increment();  // Count: 2
  counter.increment();  // Count: 3

  subscription.cancel();
  counter.dispose();
}
广播 Stream
void broadcastStream() {
  var controller = StreamController&lt;int&gt;();
  var broadcastStream = controller.stream.asBroadcastStream();

  // 多个订阅者
  broadcastStream.listen((data) =&gt; print(&#039;Listener 1: $data&#039;));
  broadcastStream.listen((data) =&gt; print(&#039;Listener 2: $data&#039;));

  controller.add(1);
  controller.add(2);
  controller.add(3);

  // 输出：
  // Listener 1: 1
  // Listener 2: 1
  // Listener 1: 2
  // Listener 2: 2
  // Listener 1: 3
  // Listener 2: 3
}
StreamTransformer
// 自定义转换器
final toUpperCaseTransformer = StreamTransformer&lt;String, String&gt;.fromHandlers(
  handleData: (value, sink) {
    sink.add(value.toUpperCase());
  },
);

void main() {
  var stream = Stream.fromIterable([&#039;hello&#039;, &#039;world&#039;]);

  stream
      .transform(toUpperCaseTransformer)
      .listen(print);  // HELLO, WORLD
}
Stream 的实际应用
1. 用户输入处理
import &#039;dart:async&#039;;

class InputHandler {
  final StreamController&lt;String&gt; _inputController =
      StreamController&lt;String&gt;();

  Stream&lt;String&gt; get input =&gt; _inputController.stream;

  void handleInput(String input) {
    _inputController.add(input);
  }

  void dispose() {
    _inputController.close();
  }
}

void main() {
  var handler = InputHandler();

  handler.input
      .where((input) =&gt; input.isNotEmpty)
      .map((input) =&gt; input.trim())
      .distinct()
      .listen((command) {
    print(&#039;Processing: $command&#039;);
  });

  handler.handleInput(&#039;  hello  &#039;);
  handler.handleInput(&#039;&#039;);
  handler.handleInput(&#039;hello&#039;);
  handler.handleInput(&#039;world&#039;);
  // 输出：Processing: hello, Processing: world
}
2. 文件读取
import &#039;dart:io&#039;;

Future&lt;void&gt; readFileByLines() async {
  var file = File(&#039;data.txt&#039;);

  // 按行读取大文件
  var lines = file.openRead()
      .transform(utf8.decoder)
      .transform(LineSplitter());

  await for (var line in lines) {
    print(line);
  }
}
3. 网络请求
Future&lt;void&gt; fetchPosts() async {
  var client = HttpClient();

  var request = await client.getUrl(
    Uri.parse(&#039;jsonplaceholder.typicode.com/posts&#039;),
  );

  var response = await request.close();

  // 处理响应流
  response
      .transform(utf8.decoder)
      .transform(json.decoder)
      .listen((data) {
    print(&#039;Received: ${data.length} items&#039;);
  });
}
4. 定时器
void createTimer() {
  var seconds = Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  );

  var subscription = seconds.take(10).listen((second) {
    print(&#039;Tick: $second&#039;);
  });

  // 取消定时器
  // subscription.cancel();
}
广播 Stream vs 单订阅 Stream
单订阅 Stream（默认）
void singleSubscriptionStream() {
  var stream = Stream.fromIterable([1, 2, 3]);

  // 只能有一个订阅者
  var subscription1 = stream.listen((data) {
    print(&#039;Listener 1: $data&#039;);
  });

  // var subscription2 = stream.listen((data) {
  //   print(&#039;Listener 2: $data&#039;);  // ❌ 错误：只能有一个监听器
  // });
}
广播 Stream
void broadcastStreamExample() {
  var stream = Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  ).take(5).asBroadcastStream();

  // 可以有多个订阅者
  stream.listen((data) =&gt; print(&#039;Listener 1: $data&#039;));
  stream.listen((data) =&gt; print(&#039;Listener 2: $data&#039;));

  // 输出：
  // Listener 1: 0
  // Listener 2: 0
  // Listener 1: 1
  // Listener 2: 1
  // ...
}
错误处理
错误处理策略
Future&lt;void&gt; errorHandling() async {
  var stream = Stream.periodic(
    Duration(seconds: 1),
    (count) {
      if (count == 3) {
        throw Exception(&#039;Error at $count&#039;);
      }
      return count;
    },
  ).take(10);

  try {
    await for (var value in stream) {
      print(&#039;Received: $value&#039;);
    }
  } catch (e) {
    print(&#039;Caught error: $e&#039;);
  } finally {
    print(&#039;Done&#039;);
  }

  // 输出：
  // Received: 0
  // Received: 1
  // Received: 2
  // Caught error: Exception: Error at 3
  // Done
}
handleError 转换
Future&lt;void&gt; handleErrorTransform() async {
  var stream = Stream.periodic(
    Duration(seconds: 1),
    (count) {
      if (count == 3) {
        throw Exception(&#039;Error at $count&#039;);
      }
      return count;
    },
  ).take(10);

  stream
      .handleError(
        (error) {
          print(&#039;Handled error: $error&#039;);
        },
      )
      .listen(
        (data) =&gt; print(&#039;Received: $data&#039;),
        onDone: () =&gt; print(&#039;Done&#039;),
      );

  // 输出：
  // Received: 0
  // Received: 1
  // Received: 2
  // Handled error: Exception: Error at 3
  // Done
}
最佳实践

[!tip&gt; Stream 使用建议



使用 await for 简化代码
// ✅ 推荐：await for
await for (var item in stream) {
  process(item);
}

// ❌ 不推荐：复杂的 listen
stream.listen((item) {
  process(item);
});


及时取消订阅
StreamSubscription subscription = stream.listen((data) { });

// 使用完毕后取消
subscription.cancel();


使用 StreamController 时记得关闭
class MyClass {
  final StreamController _controller = StreamController();

  void dispose() {
    _controller.close();  // 释放资源
  }
}


选择合适的 Stream 类型
// 单订阅者：使用普通 Stream
var stream1 = Stream.fromIterable([1, 2, 3]);

// 多订阅者：使用广播 Stream
var stream2 = stream1.asBroadcastStream();


常见陷阱

[!danger&gt; 陷阱 1：忘记取消订阅

void bad() {
  stream.listen((data) { });
  // ❌ 内存泄漏
}

void good() {
  var subscription = stream.listen((data) { });
  // 使用完毕后取消
  subscription.cancel();
}

[!danger&gt; 陷阱 2：多次订阅单订阅 Stream

void bad() {
  var stream = Stream.fromIterable([1, 2, 3]);
  stream.listen((data) { });
  stream.listen((data) { });  // ❌ 错误
}

void good() {
  var stream = Stream.fromIterable([1, 2, 3]).asBroadcastStream();
  stream.listen((data) { });  // ✅ 正确
  stream.listen((data) { });
}

[!danger&gt; 陷阱 3：在 Stream 中使用阻塞操作

var stream = Stream.periodic(Duration(seconds: 1), (count) {
  // ❌ 阻塞操作会延迟所有事件
  sleep(Duration(seconds: 5));
  return count;
});
