异步编程基础



                  概述 



异步编程是 Dart 的核心特性之一，用于处理耗时操作（如网络请求、文件 I/O）而不阻塞主线程。理解异步编程模型对于编写高效的 Dart 应用至关重要。
同步 vs 异步
同步执行
// 同步代码：按顺序执行
void main() {
  print(&#039;Step 1&#039;);
  print(&#039;Step 2&#039;);
  print(&#039;Step 3&#039;);
}

// 输出：
// Step 1
// Step 2
// Step 3
异步执行
// 异步代码：不按顺序执行
Future&lt;void&gt; main() async {
  print(&#039;Step 1&#039;);

  // 异步操作
  Future.delayed(Duration(seconds: 1), () {
    print(&#039;Step 2 (delayed)&#039;);
  });

  print(&#039;Step 3&#039;);
}

// 输出：
// Step 1
// Step 3
// Step 2 (delayed)
Dart 的并发模型
单线程模型
Dart 使用单线程执行模型，通过事件循环（Event Loop）处理异步操作：
graph TD
    A[主程序] --&gt; B[事件循环]
    B --&gt; C[微任务队列 Microtask Queue]
    B --&gt; D[事件队列 Event Queue]
    C --&gt; E[执行微任务]
    D --&gt; F[执行事件]
    E --&gt; B
    F --&gt; B

    style B fill:#e3f2fd
    style C fill:#fff3e0
    style D fill:#e8f5e9

执行顺序
void main() {
  print(&#039;1. Main&#039;);

  // 添加到事件队列
  Future(() =&gt; print(&#039;2. Event&#039;));

  // 添加到微任务队列
  scheduleMicrotask(() =&gt; print(&#039;3. Microtask&#039;));

  // 另一个事件
  Future(() =&gt; print(&#039;4. Event&#039;));

  print(&#039;5. Main end&#039;);
}

// 输出：
// 1. Main
// 5. Main end
// 3. Microtask（优先执行）
// 2. Event
// 4. Event
Future 和 Stream
Future - 单个异步结果
// Future 表示一个将来才会完成的操作
Future&lt;String&gt; fetchName() {
  return Future.delayed(
    Duration(seconds: 1),
    () =&gt; &#039;Alice&#039;,
  );
}

void main() async {
  print(&#039;Fetching name...&#039;);
  var name = await fetchName();
  print(&#039;Name: $name&#039;);
}
Stream - 多个异步事件
// Stream 表示一系列异步事件
Stream&lt;int&gt; countStream() {
  return Stream.periodic(
    Duration(seconds: 1),
    (count) =&gt; count,
  ).take(5);
}

void main() async {
  await for (var count in countStream()) {
    print(&#039;Count: $count&#039;);
  }
}

// 输出：
// Count: 0
// Count: 1
// Count: 2
// Count: 3
// Count: 4
async 和 await
async 函数
// async 函数自动返回 Future
Future&lt;int&gt; fetchData() async {
  await Future.delayed(Duration(seconds: 1));
  return 42;
}

// 返回 Future&lt;T&gt; 即使不显式返回
Future&lt;void&gt; greet() async {
  print(&#039;Hello&#039;);
}

void main() async {
  var data = await fetchData();
  print(data);  // 42
}
await 表达式
Future&lt;void&gt; example() async {
  // await 会暂停函数执行，直到 Future 完成
  var result1 = await Future.value(1);
  print(result1);  // 1

  var result2 = await Future.delayed(
    Duration(seconds: 1),
    () =&gt; 2,
  );
  print(result2);  // 2

  // await 只能在 async 函数中使用
}
错误处理
Future&lt;void&gt; fetchWithError() async {
  try {
    var data = await Future.error(Exception(&#039;Failed&#039;));
    print(data);
  } catch (e) {
    print(&#039;Caught: $e&#039;);
  } finally {
    print(&#039;Cleanup&#039;);
  }
}
事件循环详解
微任务队列 vs 事件队列
void main() {
  // 1. 同步代码
  print(&#039;Start&#039;);

  // 2. 添加到事件队列
  Future(() =&gt; print(&#039;Event 1&#039;));

  // 3. 添加到微任务队列
  scheduleMicrotask(() =&gt; print(&#039;Microtask 1&#039;));

  // 4. 添加到事件队列
  Future(() =&gt; print(&#039;Event 2&#039;));

  // 5. 同步代码
  print(&#039;End&#039;);

  // 执行顺序：Start -&gt; End -&gt; Microtask 1 -&gt; Event 1 -&gt; Event 2
}
Future 的执行顺序
void main() {
  // Future.value() 添加到事件队列
  Future.value(1).then((_) =&gt; print(&#039;Future.value&#039;));

  // Future.microtask() 添加到微任务队列
  Future.microtask(() =&gt; print(&#039;Future.microtask&#039;));

  // Future.sync() 同步执行
  Future.sync(() =&gt; print(&#039;Future.sync&#039;));

  // scheduleMicrotask() 添加到微任务队列
  scheduleMicrotask(() =&gt; print(&#039;scheduleMicrotask&#039;));

  print(&#039;Main&#039;);

  // 执行顺序：
  // Main -&gt; Future.sync -&gt; Future.microtask -&gt;
  // scheduleMicrotask -&gt; Future.value
}
Isolate - 真正的并发
什么是 Isolate
Isolate 是 Dart 中真正的独立执行线程，每个 Isolate 有自己的内存堆：
graph LR
    A[主 Isolate] --&gt;|消息传递| B[Worker Isolate 1]
    A --&gt;|消息传递| C[Worker Isolate 2]
    A --&gt;|消息传递| D[Worker Isolate 3]

    style A fill:#e3f2fd
    style B fill:#e8f5e9
    style C fill:#e8f5e9
    style D fill:#e8f5e9

使用 Isolate
import &#039;dart:isolate&#039;;

void worker(SendPort sendPort) {
  // 执行耗时计算
  int result = 0;
  for (int i = 0; i &lt; 1000000000; i++) {
    result += i;
  }
  // 发送结果回主 Isolate
  sendPort.send(result);
}

Future&lt;int&gt; runInIsolate() async {
  final receivePort = ReceivePort();

  // 启动新的 Isolate
  await Isolate.spawn(worker, receivePort.sendPort);

  // 等待结果
  final result = await receivePort.first as int;
  receivePort.close();

  return result;
}

void main() async {
  print(&#039;Starting computation...&#039;);
  var result = await runInIsolate();
  print(&#039;Result: $result&#039;);
}
Isolate.run() 便捷方法
Future&lt;int&gt; computeExpensive() async {
  return await Isolate.run(() =&gt; performCalculation());
}

int performCalculation() {
  // 耗时计算
  int sum = 0;
  for (int i = 0; i &lt; 1000000; i++) {
    sum += i;
  }
  return sum;
}
异步编程模式
1. 并发执行
Future&lt;void&gt; concurrent() async {
  // 并发执行多个 Future
  var results = await Future.wait([
    fetchData1(),
    fetchData2(),
    fetchData3(),
  ]);

  print(results);
}

Future&lt;String&gt; fetchData1() async {
  await Future.delayed(Duration(seconds: 1));
  return &#039;Data 1&#039;;
}

Future&lt;String&gt; fetchData2() async {
  await Future.delayed(Duration(seconds: 1));
  return &#039;Data 2&#039;;
}

Future&lt;String&gt; fetchData3() async {
  await Future.delayed(Duration(seconds: 1));
  return &#039;Data 3&#039;;
}
2. 顺序执行
Future&lt;void&gt; sequential() async {
  // 顺序执行多个 Future
  var data1 = await fetchData1();
  var data2 = await fetchData2();
  var data3 = await fetchData3();

  print(&#039;$data1, $data2, $data3&#039;);
}
3. 错误处理
Future&lt;void&gt; errorHandling() async {
  try {
    var data = await fetchWithError();
    print(data);
  } on SocketException catch (e) {
    print(&#039;Network error: $e&#039;);
  } on HttpException catch (e) {
    print(&#039;HTTP error: $e&#039;);
  } catch (e, stackTrace) {
    print(&#039;Unknown error: $e&#039;);
    print(stackTrace);
  } finally {
    print(&#039;Cleanup&#039;);
  }
}
4. 超时控制
Future&lt;T&gt; withTimeout&lt;T&gt;(Future&lt;T&gt; future, Duration timeout) async {
  return future.timeout(
    timeout,
    onTimeout: () {
      throw TimeoutException(&#039;Operation timed out&#039;, timeout);
    },
  );
}

void main() async {
  try {
    var result = await withTimeout(
      fetchData(),
      Duration(seconds: 2),
    );
    print(result);
  } on TimeoutException catch (e) {
    print(&#039;Timeout: $e&#039;);
  }
}

Future&lt;String&gt; fetchData() {
  return Future.delayed(Duration(seconds: 5), () =&gt; &#039;Data&#039;);
}
最佳实践

[!tip&gt; 异步编程建议



优先使用 async/await 而不是 then
// ✅ 推荐：async/await
Future&lt;void&gt; example() async {
  var data = await fetchData();
  print(data);
}

// ❌ 不推荐：then 链
void example() {
  fetchData().then((data) {
    print(data);
  });
}


正确处理错误
try {
  await riskyOperation();
} catch (e) {
  handleError(e);
}


避免阻塞事件循环
// ❌ 阻塞事件循环
void bad() {
  var result = expensiveCalculation();
}

// ✅ 使用 Isolate
Future&lt;int&gt; good() async {
  return await Isolate.run(() =&gt; expensiveCalculation());
}


合理并发
// ✅ 并发执行独立操作
var results = await Future.wait([
  fetchUser(),
  fetchPosts(),
  fetchComments(),
]);


常见陷阱

[!danger&gt; 陷阱 1：忘记 await

Future&lt;void&gt; example() async {
  // ❌ 忘记 await
  fetchData();
  print(&#039;Done&#039;);  // 可能在数据加载前执行

  // ✅ 正确使用 await
  await fetchData();
  print(&#039;Done&#039;);  // 数据加载后执行
}

[!danger&gt; 陷阱 2：不必要的 async

// ❌ 不需要 async
Future&lt;String&gt; getName() async {
  return &#039;Bob&#039;;
}

// ✅ 简化写法
Future&lt;String&gt; getName() {
  return Future.value(&#039;Bob&#039;);
}

[!danger&gt; 陷阱 3：在构造函数中使用 async

// ❌ 不能在构造函数中使用 async
class MyClass {
  MyClass() async {  // 编译错误
  }
}

// ✅ 使用静态工厂方法
class MyClass {
  static Future&lt;MyClass&gt; create() async {
    return MyClass._();
  }

  MyClass._();
}
性能考虑

[!info&gt; 异步性能


异步操作不是魔法，仍需执行时间
避免创建过多的微任务
使用 Isolate 处理 CPU 密集型任务
合理控制并发数量

