30-resources/开发/dart/03-进阶特性篇/泛型系统.content:
泛型系统



                  概述 



泛型（Generics）是 Dart 中强大的类型安全机制，允许编写灵活、可复用的代码，同时保持编译时类型检查。泛型在集合、API 设计和类型安全的代码复用中扮演重要角色。
泛型基础
为什么需要泛型
// ❌ 不使用泛型 - 失去类型安全
class Box {
  dynamic content;

  Box(this.content);

  dynamic getContent() =&gt; content;
}

void main() {
  var intBox = Box(42);
  print(intBox.getContent() + 10);  // 52

  var stringBox = Box(&#039;hello&#039;);
  // print(stringBox.getContent() + 10);  // ❌ 运行时错误
}

// ✅ 使用泛型 - 类型安全
class Box&lt;T&gt; {
  T content;

  Box(this.content);

  T getContent() =&gt; content;
}

void main() {
  var intBox = Box&lt;int&gt;(42);
  print(intBox.getContent() + 10);  // 52 - 类型安全

  var stringBox = Box&lt;String&gt;(&#039;hello&#039;);
  print(stringBox.getContent().length);  // 5 - 类型检查
}
泛型类
基本语法
class Cache&lt;T&gt; {
  final Map&lt;String, T&gt; _storage = {};

  void set(String key, T value) {
    _storage[key] = value;
  }

  T? get(String key) {
    return _storage[key];
  }

  bool contains(String key) {
    return _storage.containsKey(key);
  }
}

void main() {
  var intCache = Cache&lt;int&gt;();
  intCache.set(&#039;age&#039;, 30);
  // intCache.set(&#039;name&#039;, &#039;Alice&#039;);  // ❌ 编译错误

  var stringCache = Cache&lt;String&gt;();
  stringCache.set(&#039;name&#039;, &#039;Alice&#039;);
  print(stringCache.get(&#039;name&#039;));  // Alice
}
多个类型参数
class Pair&lt;K, V&gt; {
  final K key;
  final V value;

  Pair(this.key, this.value);

  @override
  String toString() =&gt; &#039;Pair($key, $value)&#039;;
}

void main() {
  var pair1 = Pair&lt;String, int&gt;(&#039;age&#039;, 30);
  print(pair1);  // Pair(age, 30)

  var pair2 = Pair&lt;int, String&gt;(1, &#039;one&#039;);
  print(pair2);  // Pair(1, one)
}
泛型集合
class Stack&lt;E&gt; {
  final List&lt;E&gt; _items = [];

  void push(E item) {
    _items.add(item);
  }

  E pop() {
    if (_items.isEmpty) {
      throw StateError(&#039;Stack is empty&#039;);
    }
    return _items.removeLast();
  }

  E get peek =&gt; _items.last;

  bool get isEmpty =&gt; _items.isEmpty;
  int get length =&gt; _items.length;
}

void main() {
  var intStack = Stack&lt;int&gt;();
  intStack.push(1);
  intStack.push(2);
  print(intStack.pop());  // 2

  var stringStack = Stack&lt;String&gt;();
  stringStack.push(&#039;hello&#039;);
  print(stringStack.pop());  // hello
}
泛型方法
泛型函数
T firstOrNull&lt;T&gt;(List&lt;T&gt; list) {
  return list.isEmpty ? null : list.first;
}

void main() {
  var numbers = [1, 2, 3];
  print(firstOrNull(numbers));  // 1

  var strings = [&#039;a&#039;, &#039;b&#039;, &#039;c&#039;];
  print(firstOrNull(strings));  // a
}
泛型返回类型
List&lt;T&gt; filter&lt;T&gt;(List&lt;T&gt; list, bool Function(T) predicate) {
  return list.where(predicate).toList();
}

void main() {
  var numbers = [1, 2, 3, 4, 5];
  var evens = filter(numbers, (n) =&gt; n % 2 == 0);
  print(evens);  // [2, 4]

  var strings = [&#039;apple&#039;, &#039;banana&#039;, &#039;cherry&#039;];
  var long = filter(strings, (s) =&gt; s.length &gt; 5);
  print(long);  // [&#039;banana&#039;, &#039;cherry&#039;]
}
多个类型参数的方法
Map&lt;K, List&lt;V&gt;&gt; groupBy&lt;K, V&gt;(List&lt;V&gt; items, K Function(V) keyFn) {
  var map = &lt;K, List&lt;V&gt;&gt;{};
  for (var item in items) {
    final key = keyFn(item);
    map.putIfAbsent(key, () =&gt; []).add(item);
  }
  return map;
}

void main() {
  var people = [
    {&#039;name&#039;: &#039;Alice&#039;, &#039;age&#039;: 30},
    {&#039;name&#039;: &#039;Bob&#039;, &#039;age&#039;: 25},
    {&#039;name&#039;: &#039;Charlie&#039;, &#039;age&#039;: 30},
  ];

  var grouped = groupBy(people, (p) =&gt; p[&#039;age&#039;]);
  print(grouped);
  // {30: [{name: Alice, age: 30}, {name: Charlie, age: 30}],
  //  25: [{name: Bob, age: 25}]}
}
类型参数约束
extends 关键字
class NumberCache&lt;T extends num&gt; {
  final List&lt;T&gt; _numbers = [];

  void add(T number) {
    _numbers.add(number);
  }

  T sum() {
    // 可以使用 num 的方法
    num total = 0;
    for (var n in _numbers) {
      total += n;
    }
    return total as T;
  }
}

void main() {
  var intCache = NumberCache&lt;int&gt;();
  intCache.add(1);
  intCache.add(2);
  print(intCache.sum());  // 3

  var doubleCache = NumberCache&lt;double&gt;();
  doubleCache.add(1.5);
  doubleCache.add(2.5);
  print(doubleCache.sum());  // 4.0

  // var stringCache = NumberCache&lt;String&gt;();  // ❌ 编译错误
}
多重约束
class Serializable {
  Map&lt;String, dynamic&gt; toJson();
}

class Model&lt;T extends Serializable&gt; {
  final List&lt;T&gt; _items = [];

  void add(T item) {
    _items.add(item);
  }

  List&lt;Map&lt;String, dynamic&gt;&gt; toJson() {
    return _items.map((item) =&gt; item.toJson()).toList();
  }
}

class User implements Serializable {
  String name;
  int age;

  User(this.name, this.age);

  @override
  Map&lt;String, dynamic&gt; toJson() {
    return {&#039;name&#039;: name, &#039;age&#039;: age};
  }
}
可空类型约束
T getValue&lt;T&gt;(T? value, T defaultValue) {
  return value ?? defaultValue;
}

void main() {
  print(getValue&lt;int&gt;(null, 0));      // 0
  print(getValue&lt;int&gt;(42, 0));        // 42
  print(getValue&lt;String&gt;(null, &#039;&#039;));  // 空字符串
}
泛型与继承
泛型类的继承
class Animal {
  String name;
  Animal(this.name);
}

class Dog extends Animal {
  String breed;
  Dog(String name, this.breed) : super(name);
}

class Cage&lt;T extends Animal&gt; {
  final List&lt;T&gt; _animals = [];

  void add(T animal) {
    _animals.add(animal);
  }

  void listAll() {
    for (var animal in _animals) {
      print(animal.name);
    }
  }
}

void main() {
  var animalCage = Cage&lt;Animal&gt;();
  animalCage.add(Animal(&#039;Generic&#039;));
  animalCage.add(Dog(&#039;Buddy&#039;, &#039;Golden&#039;));

  var dogCage = Cage&lt;Dog&gt;();
  dogCage.add(Dog(&#039;Max&#039;, &#039;Poodle&#039;));
  // dogCage.add(Animal(&#039;Generic&#039;));  // ❌ 编译错误
}
协变与逆变
//协变：泛型类型可以替换为子类型
class Producer&lt;out T&gt; {
  T produce() =&gt; throw UnimplementedError();
}

// 逆变：泛型类型可以替换为父类型
class Consumer&lt;in T&gt; {
  void consume(T item) {}
}

// 不变：泛型类型不能替换
class Container&lt;T&gt; {
  T? value;
}
限制泛型类型
限制为特定类型
class NumericList&lt;T extends num&gt; {
  final List&lt;T&gt; _values = [];

  void add(T value) {
    _values.add(value);
  }

  T sum() {
    num total = 0;
    for (var v in _values) {
      total += v;
    }
    return total as T;
  }

  double average() {
    if (_values.isEmpty) return 0;
    return sum() / _values.length;
  }
}
使用可空类型
class NullableBox&lt;T&gt; {
  T? value;

  NullableBox([this.value]);

  bool get hasValue =&gt; value != null;
  T orElse(T defaultValue) {
    return value ?? defaultValue;
  }
}

void main() {
  var box = NullableBox&lt;int&gt;();
  print(box.hasValue);  // false
  print(box.orElse(42)); // 42
}
泛型的实际应用
1. Result 类型
class Result&lt;T&gt; {
  final T? data;
  final String? error;

  Result.success(this.data) : error = null;
  Result.failure(this.error) : data = null;

  bool get isSuccess =&gt; error == null;
  bool get isFailure =&gt; error != null;

  T get dataOrThrow {
    if (error != null) {
      throw Exception(error);
    }
    return data as T;
  }
}

void main() {
  var success = Result&lt;int&gt;.success(42);
  print(success.isSuccess);  // true
  print(success.data);        // 42

  var failure = Result&lt;int&gt;.failure(&#039;Network error&#039;);
  print(failure.isFailure);  // true
  print(failure.error);       // Network error
}
2. Either 类型
class Either&lt;L, R&gt; {
  final L? left;
  final R? right;

  Either.left(this.left) : right = null;
  Either.right(this.right) : left = null;

  bool get isLeft =&gt; left != null;
  bool get isRight =&gt; right != null;

  T fold&lt;T&gt;(T Function(L) ifLeft, T Function(R) ifRight) {
    if (left != null) return ifLeft(left!);
    return ifRight(right!);
  }
}

void main() {
  var either = Either&lt;String, int&gt;.right(42);

  var message = either.fold(
    (error) =&gt; &#039;Error: $error&#039;,
    (value) =&gt; &#039;Value: $value&#039;,
  );

  print(message);  // Value: 42
}
3. 状态管理
class State&lt;T&gt; {
  final T? data;
  final bool isLoading;
  final String? error;

  State.initial()
      : data = null,
        isLoading = false,
        error = null;

  State.loading()
      : data = null,
        isLoading = true,
        error = null;

  State.success(this.data)
      : isLoading = false,
        error = null;

  State.failure(this.error)
      : data = null,
        isLoading = false;
}
泛型的最佳实践

[!tip&gt; 泛型使用建议



优先使用泛型而不是 dynamic
List&lt;String&gt; names = [];  // ✅ 类型安全
List&lt;dynamic&gt; names = [];  // ❌ 失去类型检查


使用有意义的类型参数名
class Cache&lt;K, V&gt; { }  // ✅ Key, Value
class List&lt;E&gt; { }      // ✅ Element
class Result&lt;T&gt; { }    // ✅ Type
class Box&lt;T&gt; { }       // ✅ Thing

// 不推荐
class Cache&lt;A, B&gt; { }  // ❌ 不明确


合理使用类型约束
class Cache&lt;T extends Comparable&gt; { }  // ✅ 明确约束


提供类型推断
var list = List&lt;int&gt;.filled(10, 0);  // ✅ 明确类型
var list2 = [1, 2, 3];                // ✅ 推导类型


常见陷阱

[!danger&gt; 陷阱 1：泛型类型擦除

void main() {
  List&lt;int&gt; ints = [1, 2, 3];
  List&lt;double&gt; doubles = [1.0, 2.0, 3.0];

  print(ints.runtimeType);       // List&lt;int&gt;
  print(ints is List&lt;int&gt;);       // true
  print(ints is List&lt;double&gt;);   // false

  // 但在运行时，泛型信息可能被擦除
  print(ints is List);            // true
}

[!danger&gt; 陷阱 2：不能实例化泛型类型

class Factory&lt;T&gt; {
  T create() {
    // return T();  // ❌ 不能实例化泛型类型
    throw UnimplementedError();
  }
}

// ✅ 解决方法：使用函数参数
class Factory&lt;T&gt; {
  T create(T Function() creator) {
    return creator();
  }
}

[!danger&gt; 陷阱 3：泛型默认为 Object

void process&lt;T&gt;(T value) {
  // value 是 Object 类型
  // print(value.length);  // ❌ Object 没有 length
}
性能考虑

[!info&gt; 泛型性能


Dart 在运行时保留了泛型信息（与 Java 不同）
泛型不会带来性能损失
编译时进行类型检查，提高代码质量
使用泛型可以避免运行时类型转换

相关概念

类型系统 - Dart 类型系统
List 操作 - 泛型集合
Map 操作 - 泛型映射

参考资源

Dart 泛型文档
Dart 泛型最佳实践

30-resources/开发/dart/03-进阶特性篇/空安全.content:
空安全 (Null Safety)



                  概述 



Dart 2.12 引入了 Sound Null Safety（空安全），这是一项重大改进，可以在编译时捕获空引用错误，大大提高了代码的健壮性和安全性。
核心概念
空安全基于以下原则：

默认不可为空：除非明确声明，否则类型不能包含 null
编译时检查：空错误在编译时被发现，而不是运行时
完全可靠：如果代码通过了类型检查，就不会出现空引用错误

graph LR
    A[代码编写] --&gt; B{类型检查}
    B --&gt;|通过| C[安全运行]
    B --&gt;|失败| D[编译错误]
    D --&gt; A

    style C fill:#e8f5e9
    style D fill:#ffebee

可空与不可空类型
基本语法
// 不可空类型（默认）
String name = &#039;Bob&#039;;
// name = null;  // ❌ 编译错误：不能赋值 null

// 可空类型（使用 ?）
String? nickname;
nickname = null;  // ✅ 可以为 null
nickname = &#039;Bobby&#039;; // ✅ 也可以有值
类型声明规则
// 不可空类型
int count = 0;          // 不能为 null
String text = &#039;Hello&#039;;  // 不能为 null
bool flag = true;       // 不能为 null

// 可空类型
int? count;             // 可以为 null
String? text;           // 可以为 null
bool? flag;             // 可以为 null
Null-aware 操作符
1. ?. - 安全访问
String? name;
print(name?.length);  // null（不会抛出异常）

String? optionalName = &#039;Alice&#039;;
print(optionalName?.length);  // 5
2. ?? - 空值合并
String? name;
String displayName = name ?? &#039;Guest&#039;;  // &#039;Guest&#039;

String? optionalName = &#039;Bob&#039;;
String displayName = optionalName ?? &#039;Guest&#039;;  // &#039;Bob&#039;
3. ??= - 空值赋值
String? name;
name ??= &#039;Default&#039;;  // name 现在是 &#039;Default&#039;

String? existingName = &#039;Bob&#039;;
existingName ??= &#039;Default&#039;;  // name 仍然是 &#039;Bob&#039;
4. ?[] - 安全索引访问
List&lt;int&gt;? numbers = [1, 2, 3];
print(numbers?[1]);  // 2

List&lt;int&gt;? emptyList;
print(emptyList?[1]);  // null
5. …? - 空值展开
var list1 = [1, 2, 3];
List&lt;int&gt;? list2;
var combined = [...list1, ...?list2];  // [1, 2, 3]

List&lt;int&gt;? list3 = [4, 5];
var combined2 = [...list1, ...?list3];  // [1, 2, 3, 4, 5]
断言操作符
! - 非空断言
String? name = &#039;Bob&#039;;
print(name!.length);  // 4（将 name 视为非空）

String? nullableName;
// print(nullableName!.length);  // ❌ 运行时错误：抛出 NullPointerException



                  谨慎使用 ! 




! 操作符告诉编译器”我确定这不是 null”
如果实际是 null，会在运行时抛出异常
只在确定值不为 null 时使用

late 关键字
延迟初始化
class Database {
  // late 声明非空变量，稍后初始化
  late Connection _connection;

  Database() {
    _connection = Connection.connect();
  }

  void query(String sql) {
    _connection.execute(sql);  // 无需检查 null
  }
}
懒加载（Lazy Loading）
class ExpensiveObject {
  late final HeavyResource _resource = HeavyResource.create();

  HeavyResource get resource =&gt; _resource;
}

// _resource 只在首次访问时创建



                  late 使用场景 




变量在声明后、使用前一定会被初始化
需要延迟初始化以提升性能
处理循环依赖

空安全与集合
// 可空集合
List&lt;String&gt;? nullableList;  // 集合本身可以为 null
List&lt;String?&gt; nullableElements;  // 元素可以为 null

// 示例
nullableList = null;  // ✅
nullableList = [&#039;a&#039;, null, &#039;c&#039;];  // ✅

nullableElements = [&#039;a&#039;, null, &#039;c&#039;];  // ✅
// nullableElements = null;  // ❌ 编译错误

// List&lt;int?&gt; 不能赋值给 List&lt;int&gt;
List&lt;int?&gt; nullableInts = [1, 2, null];
// List&lt;int&gt; nonNullInts = nullableInts;  // ❌ 类型不匹配
空安全与函数
函数参数
// 可空参数
String greet(String? name) {
  return &#039;Hello, ${name ?? &#039;Guest&#039;}&#039;;
}

// 默认值（非空类型）
String greet2([String name = &#039;Guest&#039;]) {
  return &#039;Hello, $name&#039;;
}

// 可选命名参数
void printUser({String? name, int? age}) {
  print(&#039;Name: ${name ?? &#039;Unknown&#039;}, Age: ${age ?? &#039;Unknown&#039;}&#039;);
}
函数返回值
// 返回可空类型
String? findUser(String id) {
  if (id == &#039;1&#039;) {
    return &#039;Alice&#039;;
  }
  return null;  // ✅ 可以返回 null
}

// 返回不可空类型
String getUser(String id) {
  var user = findUser(id);
  return user ?? &#039;Unknown&#039;;  // ✅ 确保返回非空
}
空安全与类
类成员初始化
class User {
  String name;  // 必须初始化
  int? age;     // 可以为 null

  // 构造函数中初始化
  User(this.name);

  // 使用 late
  class Database {
    late String connection;
  }

  // 使用默认值
  class Config {
    String host = &#039;localhost&#039;;
    int? port;
  }
}
初始化列表
class Point {
  final int x;
  final int y;

  // 初始化列表确保非空成员被初始化
  Point(Map&lt;String, int&gt; coords)
      : x = coords[&#039;x&#039;] ?? 0,
        y = coords[&#039;y&#039;] ?? 0;
}
类型提升 (Type Promotion)
void example(String? value) {
  if (value != null) {
    // 在这里，value 的类型从 String? 提升为 String
    print(value.length);  // ✅ 无需使用 value?.length
    print(value.toLowerCase());  // ✅ 编译器知道 value 不是 null
  }

  // 在 if 外，value 仍然是 String?
  // print(value.length);  // ❌ 编译错误
}
类型提升的条件
void promotionExample(String? value) {
  // ✅ 明确的 null 检查
  if (value != null) {
    print(value.length);
  }

  // ✅ 赋值后提升
  String? text;
  text = &#039;Hello&#039;;
  print(text.length);  // ✅ text 提升为 String

  // ❌ 不会提升的情况
  String? maybeText;
  if (randomBool()) {
    maybeText = &#039;Hello&#039;;
  }
  // print(maybeText.length);  // ❌ 编译器不确定
}
迁移到空安全
迁移步骤
// 1. 分析代码
dart analyze

// 2. 迁移
dart migrate

// 3. 测试
dart test
迁移策略
// 迁移前
String getName(String name) {
  return name;
}

// 迁移后：明确类型
String getName(String name) {
  return name;  // String 不能为 null
}

// 或者：允许 null
String? getName(String? name) {
  return name;  // String? 可以为 null
}
常见模式
1. 提前返回
void processUser(User? user) {
  if (user == null) {
    return;  // 提前返回
  }

  // user 在这里自动提升为 User
  print(user.name);
  print(user.email);
}
2. 默认值
class Config {
  String host;
  int port;

  Config({
    String? host,
    int? port,
  })  : host = host ?? &#039;localhost&#039;,
        port = port ?? 8080;
}
3. 验证模式
class Email {
  final String value;

  Email._(this.value);

  factory Email(String value) {
    if (value.contains(&#039;@&#039;)) {
      return Email._(value);
    }
    throw ArgumentError(&#039;Invalid email&#039;);
  }
}

// 使用
Email email = Email(&#039;user@example.com&#039;);  // ✅
// Email invalid = Email(&#039;invalid&#039;);  // ❌ 抛出异常
常见陷阱



                  陷阱 1：忽略可空返回值 



List&lt;String&gt;? names = getNames();
// print(names.length);  // ❌ 编译错误

// ✅ 正确处理
names?.length ?? 0;



                  陷阱 2：过度使用 ! 



String? name = getName();
// print(name!.length);  // ❌ 危险，可能崩溃

// ✅ 安全处理
print(name?.length ?? 0);



                  陷阱 3：late 变量未初始化 



late String name;
// print(name);  // ❌ 运行时错误
最佳实践



                  空安全建议 




优先使用不可空类型：只在确实需要时使用可空类型
避免过度使用 !：使用 ?. 和 ?? 代替
合理使用 late：确保变量在使用前被初始化
明确函数契约：参数和返回值的可空性
利用类型提升：编写可被编译器理解的代码

相关概念

类型系统 - 理解 Dart 类型系统
Future 详解 - 异步操作中的空安全
最佳实践篇 - 空安全的最佳实践

参考资源

Dart 空安全指南
Dart 空安全常见问题
迁移到空安全

30-resources/开发/dart/04-核心库篇/list-操作.content:
List 操作



                  概述 



List 是 Dart 中最常用的集合类型，表示有序的元素集合。掌握 List 的各种操作方法对于高效处理数据至关重要。
创建 List
基本创建方式
void main() {
  // 字面量创建
  var list1 = [1, 2, 3, 4, 5];
  print(list1);  // [1, 2, 3, 4, 5]

  // 指定类型
  List&lt;int&gt; list2 = [1, 2, 3];
  List&lt;String&gt; list3 = [&#039;a&#039;, &#039;b&#039;, &#039;c&#039;];

  // 空列表
  var emptyList = &lt;int&gt;[];
  var emptyList2 = List&lt;int&gt;.empty();

  // 固定长度列表
  var fixedList = List&lt;int&gt;.filled(5, 0);
  print(fixedList);  // [0, 0, 0, 0, 0]

  // 生成列表
  var generated = List&lt;int&gt;.generate(5, (i) =&gt; i * 2);
  print(generated);  // [0, 2, 4, 6, 8]

  // from 可迭代对象
  var fromIterable = List&lt;int&gt;.from([1, 2, 3]);
  print(fromIterable);  // [1, 2, 3]
}
可增长 vs 固定长度
void main() {
  // 可增长列表（默认）
  var growable = [1, 2, 3];
  growable.add(4);
  growable.remove(1);
  print(growable);  // [2, 3, 4]

  // 固定长度列表
  var fixed = List&lt;int&gt;.filled(3, 0, growable: false);
  // fixed.add(1);  // ❌ 不支持添加
  // fixed.remove(0);  // ❌ 不支持删除

  // 不可变列表
  var unmodifiable = List.unmodifiable([1, 2, 3]);
  // unmodifiable.add(4);  // ❌ 不支持修改
}
添加元素
添加方法
void main() {
  var list = [1, 2, 3];

  // add - 添加单个元素
  list.add(4);
  print(list);  // [1, 2, 3, 4]

  // addAll - 添加多个元素
  list.addAll([5, 6]);
  print(list);  // [1, 2, 3, 4, 5, 6]

  // insert - 在指定位置插入
  list.insert(0, 0);
  print(list);  // [0, 1, 2, 3, 4, 5, 6]

  // insertAll - 在指定位置插入多个
  list.insertAll(1, [10, 20]);
  print(list);  // [0, 10, 20, 1, 2, 3, 4, 5, 6]
}
删除元素
删除方法
void main() {
  var list = [1, 2, 3, 4, 5, 4, 3, 2, 1];

  // remove - 删除指定元素（第一个匹配）
  list.remove(3);
  print(list);  // [1, 2, 4, 5, 4, 3, 2, 1]

  // removeAt - 删除指定位置的元素
  list.removeAt(0);
  print(list);  // [2, 4, 5, 4, 3, 2, 1]

  // removeLast - 删除最后一个元素
  list.removeLast();
  print(list);  // [2, 4, 5, 4, 3, 2]

  // removeWhere - 删除满足条件的元素
  list.removeWhere((element) =&gt; element % 2 == 0);
  print(list);  // [5, 3]

  // retainWhere - 保留满足条件的元素
  list.retainWhere((element) =&gt; element &gt; 3);
  print(list);  // [5]

  // clear - 清空列表
  list.clear();
  print(list);  // []
  print(list.isEmpty);  // true
}
修改元素
修改方法
void main() {
  var list = [1, 2, 3, 4, 5];

  // 通过索引修改
  list[0] = 10;
  print(list);  // [10, 2, 3, 4, 5]

  // setAll - 设置多个位置
  list.setAll(1, [20, 30]);
  print(list);  // [10, 20, 30, 4, 5]

  // setRange - 设置范围内的元素
  var source = [100, 200];
  list.setRange(0, 2, source);
  print(list);  // [100, 200, 30, 4, 5]

  // replaceRange - 替换范围内的元素
  list.replaceRange(0, 2, [1, 2, 3]);
  print(list);  // [1, 2, 3, 30, 4, 5]

  // fillRange - 填充范围
  list.fillRange(0, 3, 0);
  print(list);  // [0, 0, 0, 30, 4, 5]
}
查询元素
查询方法
void main() {
  var list = [1, 2, 3, 4, 5];

  // 索引访问
  print(list[0]);     // 1
  print(list.first);  // 1
  print(list.last);   // 5

  // indexOf - 查找元素索引
  print(list.indexOf(3));   // 2
  print(list.indexOf(10));  // -1（未找到）

  // indexWhere - 查找满足条件的元素索引
  print(list.indexWhere((e) =&gt; e % 2 == 0));  // 1

  // contains - 是否包含元素
  print(list.contains(3));   // true
  print(list.contains(10));  // false

  // elementAt - 获取指定位置元素
  print(list.elementAt(2));  // 3

  // any - 是否有元素满足条件
  print(list.any((e) =&gt; e &gt; 3));  // true

  // every - 是否所有元素都满足条件
  print(list.every((e) =&gt; e &gt; 0));  // true

  // where - 过滤元素
  var evens = list.where((e) =&gt; e % 2 == 0);
  print(evens.toList());  // [2, 4]

  // firstWhere - 查找第一个满足条件的元素
  print(list.firstWhere((e) =&gt; e &gt; 3));  // 4

  // lastWhere - 查找最后一个满足条件的元素
  print(list.lastWhere((e) =&gt; e &lt; 5));  // 4

  // singleWhere - 查找唯一满足条件的元素
  print(list.singleWhere((e) =&gt; e == 3));  // 3
}
转换操作
转换方法
void main() {
  var list = [1, 2, 3, 4, 5];

  // map - 转换每个元素
  var doubled = list.map((e) =&gt; e * 2);
  print(doubled.toList());  // [2, 4, 6, 8, 10]

  // expand - 展开每个元素
  var nested = [[1, 2], [3, 4], [5]];
  var flattened = nested.expand((e) =&gt; e);
  print(flattened.toList());  // [1, 2, 3, 4, 5]

  // take - 取前 n 个元素
  var taken = list.take(3);
  print(taken.toList());  // [1, 2, 3]

  // skip - 跳过前 n 个元素
  var skipped = list.skip(2);
  print(skipped.toList());  // [3, 4, 5]

  // takeWhile - 满足条件时取元素
  var takeWhile = list.takeWhile((e) =&gt; e &lt; 4);
  print(takeWhile.toList());  // [1, 2, 3]

  // skipWhile - 满足条件时跳过元素
  var skipWhile = list.skipWhile((e) =&gt; e &lt; 3);
  print(skipWhile.toList());  // [3, 4, 5]

  // distinct - 去重
  var dup = [1, 2, 2, 3, 3, 3];
  var unique = dup.distinct();
  print(unique.toList());  // [1, 2, 3]

  // toList / toSet - 转换
  var list2 = [1, 2, 3];
  print(list2.toList());  // [1, 2, 3]
  print(list2.toSet());   // {1, 2, 3}

  // join - 连接为字符串
  var words = [&#039;Hello&#039;, &#039;World&#039;];
  print(words.join(&#039; &#039;));  // Hello World
}
排序
排序方法
void main() {
  var list = [3, 1, 4, 1, 5, 9, 2, 6];

  // sort - 原地排序
  list.sort();
  print(list);  // [1, 1, 2, 3, 4, 5, 6, 9]

  // 自定义排序
  list.sort((a, b) =&gt; b.compareTo(a));  // 降序
  print(list);  // [9, 6, 5, 4, 3, 2, 1, 1]

  // 字符串排序
  var fruits = [&#039;banana&#039;, &#039;apple&#039;, &#039;cherry&#039;];
  fruits.sort();
  print(fruits);  // [apple, banana, cherry]

  // 对象排序
  var people = [
    Person(&#039;Alice&#039;, 30),
    Person(&#039;Bob&#039;, 25),
    Person(&#039;Charlie&#039;, 35),
  ];
  people.sort((a, b) =&gt; a.age.compareTo(b.age));
  people.forEach(print);
  // Bob(25), Alice(30), Charlie(35)
}

class Person {
  String name;
  int age;
  Person(this.name, this.age);

  @override
  String toString() =&gt; &#039;$name($age)&#039;;
}
折叠和归约
高阶操作
void main() {
  var list = [1, 2, 3, 4, 5];

  // reduce - 折叠
  var sum = list.reduce((a, b) =&gt; a + b);
  print(sum);  // 15

  // fold - 带初始值的折叠
  var product = list.fold(1, (a, b) =&gt; a * b);
  print(product);  // 120

  // 使用 fold 进行复杂操作
  var stats = list.fold(
    {&#039;sum&#039;: 0, &#039;count&#039;: 0},
    (map, element) {
      map[&#039;sum&#039;] += element;
      map[&#039;count&#039;]++;
      return map;
    },
  );
  print(stats);  // {sum: 15, count: 5}
  print(stats[&#039;sum&#039;] / stats[&#039;count&#039;]);  // 3.0（平均值）
}
