扩展运算符
展开运算符
void main() {
  var list1 = [1, 2, 3];
  var list2 = [4, 5, 6];

  // ... - 展开运算符
  var combined = [...list1, ...list2];
  print(combined);  // [1, 2, 3, 4, 5, 6]

  // ...? - 空值展开
  List&lt;int&gt;? maybeList;
  var combined2 = [0, ...?maybeList, 1];
  print(combined2);  // [0, 1]

  maybeList = [2, 3];
  var combined3 = [0, ...?maybeList, 1];
