List 的性能考虑
性能特点
void performance() {
  // List 操作的时间复杂度：
  // add() - O(1) 平摊
  // addAll() - O(m)，m 是添加的元素数
  // insert() - O(n)
  // remove() - O(n)
  // removeAt() - O(n)
  // indexOf() - O(n)
  // [] - O(1)
  // length - O(1)
  // first / last - O(1)

  // 性能建议
  var list = [1, 2, 3, 4, 5];

  // ✅ 快速操作
  var first = list.first;        // O(1)
  var last = list.last;          // O(1)
  var element = list[2];         // O(1)

  // ⚠️ 较慢操作
  list.insert(0, 0);             // O(n) - 需要移动所有元素
  list.remove(3);                // O(n) - 需要查找和移动

  // ✅ 批量操作
  var filtered = list.where((e) =&gt; e &gt; 2);  // 惰性求值
}
最佳实践

[!tip&gt; List 使用建议



使用字面量创建
var list = [1, 2, 3];  // ✅ 推荐
var list2 = List&lt;int&gt;.from([1, 2, 3]);  // ❌ 不必要


使用展开运算符
var combined = [...list1, ...list2];  // ✅ 简洁


优先使用 where 而不是 forEach 过滤
var evens = list.where((n) =&gt; n % 2 == 0);  // ✅ 惰性求值


避免在循环中修改 List
// ❌ 可能导致错误
for (var item in list) {
  if (item % 2 == 0) {
    list.remove(item);  // ❌ 不要这样做
  }
}

// ✅ 使用 removeWhere
list.removeWhere((item) =&gt; item % 2 == 0);


使用不可变列表保护数据
var unmodifiable = List.unmodifiable([1, 2, 3]);


常见陷阱

[!danger&gt; 陷阱 1：越界访问

var list = [1, 2, 3];
print(list[5]);  // ❌ RangeError
print(list.elementAt(2));  // ✅ 3
print(list.elementAtOrNull(5));  // ✅ null

[!danger&gt; 陷阱 2：修改正在遍历的列表

var list = [1, 2, 3];
for (var item in list) {
  list.remove(item);  // ❌ ConcurrentModificationError
}

// ✅ 正确做法
var list = [1, 2, 3];
var toRemove = list.where((e) =&gt; e % 2 == 0);
list.removeAll(toRemove);

[!danger&gt; 陷阱 3：sort 会修改原列表

var list = [3, 1, 2];
var sorted = list..sort();
print(list);  // [1, 2, 3] - 原列表被修改

// ✅ 如需保留原列表
var list = [3, 1, 2];
var sorted = [...list]..sort();
print(list);    // [3, 1, 2] - 原列表不变
print(sorted);  // [1, 2, 3] - 新列表已排序
