更新元素
update 和 updateAll
void main() {
  var prices = {&#039;apple&#039;: 5.5, &#039;banana&#039;: 3.2};

  // 更新单个值
  prices.update(&#039;apple&#039;, (value) =&gt; value * 0.9); // 打 9 折
  print(prices); // {apple: 4.95, banana: 3.2}

  // 更新不存在的键时提供默认值
  prices.update(&#039;orange&#039;, (value) =&gt; value * 0.9, ifAbsent: () =&gt; 4.8);
  print(prices); // {apple: 4.95, banana: 3.2, orange: 4.8}

  // 批量更新
  prices.updateAll((key, value) =&gt; value * 0.8); // 全部 8 折
  print(prices); // {apple: 3.96, banana: 2.56, orange: 3.84}
}
putIfAbsent
void main() {
  var cache = &lt;String, int&gt;{};

  // 键不存在时添加
  cache.putIfAbsent(&#039;result1&#039;, () =&gt; computeExpensive());
  print(cache); // {result1: 42}

  // 键已存在时不修改
  cache.putIfAbsent(&#039;result1&#039;, () =&gt; 999);
  print(cache); // {result1: 42}
}

int computeExpensive() {
  return 42; // 模拟昂贵计算
}
