  print(map[&#039;missing&#039;]); // null

  // ✅ 使用 containsKey 检查
  if (map.containsKey(&#039;missing&#039;)) {
    print(map[&#039;missing&#039;]);
  }

  // ✅ 使用 ?? 提供默认值
  var value = map[&#039;missing&#039;] ?? &#039;default&#039;;
  print(value);
}
修改 Map 会影响所有引用
void main() {
  var map1 = {&#039;a&#039;: 1, &#039;b&#039;: 2};
  var map2 = map1; // map2 和 map1 指向同一个 Map

  map2[&#039;c&#039;] = 3;
  print(map1); // {a: 1, b: 2, c: 3} - map1 也被修改了

  // ✅ 需要副本时使用 Map.from
  var map3 = Map.from(map1);
  map3[&#039;d&#039;] = 4;
  print(map1); // {a: 1, b: 2, c: 3}
}
忽略 null 安全
void main() {
  // ❌ 避免：使用可能为 null 的键
  String? key;
  var map = {&#039;a&#039;: 1};
  // print(map[key]); // 编译警告

  // ✅ 推荐：处理 null 情况
  if (key != null) {
    print(map[key]);
  }
}
键的类型必须实现 hashCode
void main() {
  // ✅ 基本类型作为键
  var map1 = &lt;int, String&gt;{1: &#039;one&#039;, 2: &#039;two&#039;};
  var map2 = &lt;String, int&gt;{&#039;a&#039;: 1, &#039;b&#039;: 2};

  // ❌ 自定义类作为键需要实现 hashCode 和 ==
  class Person {
    String name;
    Person(this.name);
  }

  // var map3 = &lt;Person, int&gt;{}; // 不正确实现会导致问题
}

// ✅ 正确实现
class Person {
  String name;
  Person(this.name);

  @override
  bool operator ==(Object other) =&gt;
    other is Person &amp;&amp; other.name == name;

  @override
  int get hashCode =&gt; name.hashCode;
}
