30-resources/开发/dart/04-核心库篇/set-操作.content:
Set 操作



                  概述 



Set 是 Dart 中表示无序、唯一元素集合的数据结构，基于哈希表实现，提供高效的查找和去重功能。
创建 Set
基本创建方式
void main() {
  // 字面量创建
  var set1 = {1, 2, 3, 4, 5};
  print(set1);  // {1, 2, 3, 4, 5}

  // 指定类型
  Set&lt;int&gt; set2 = {1, 2, 3};
  Set&lt;String&gt; set3 = {&#039;a&#039;, &#039;b&#039;, &#039;c&#039;};

  // 空集合
  var emptySet = &lt;int&gt;{};
  var emptySet2 = Set&lt;int&gt;();

  // from 可迭代对象
  var fromIterable = Set&lt;int&gt;.from([1, 2, 3, 2, 1]);
  print(fromIterable);  // {1, 2, 3} - 自动去重

  // of - 创建并包含指定元素
  var setOf = Set.of([1, 2, 3]);
  print(setOf);  // {1, 2, 3}
}
不可变 Set
void main() {
  // const Set - 编译时常量
  var constSet = const {1, 2, 3};
  // constSet.add(4);  // ❌ 不支持修改

  // unmodifiable - 运行时不可变
  var unmodifiable = Set.unmodifiable({1, 2, 3});
  // unmodifiable.add(4);  // ❌ 不支持修改

  // 可变 Set
  var mutable = {1, 2, 3};
  mutable.add(4);  // ✅ 可以修改
  print(mutable);  // {1, 2, 3, 4}
}
Set vs List 对比



































特性SetList顺序无序有序唯一性自动去重允许重复查找性能O(1)O(n)插入性能O(1)O(1) 平摊适用场景去重、成员测试顺序访问、索引访问
添加元素
添加方法
void main() {
  var set = &lt;int&gt;{1, 2, 3};

  // add - 添加单个元素
  set.add(4);
  print(set);  // {1, 2, 3, 4}

  // addAll - 添加多个元素
  set.addAll({5, 6, 7});
  print(set);  // {1, 2, 3, 4, 5, 6, 7}

  // 添加重复元素会被忽略
  set.add(3);
  print(set);  // {1, 2, 3, 4, 5, 6, 7} - 3 已存在，不重复添加
}
删除元素
删除方法
void main() {
  var set = {1, 2, 3, 4, 5};

  // remove - 删除指定元素
  set.remove(3);
  print(set);  // {1, 2, 4, 5}

  // removeAll - 删除多个元素
  set.removeAll({1, 2});
  print(set);  // {4, 5}

  // removeWhere - 删除满足条件的元素
  var numbers = {1, 2, 3, 4, 5, 6};
  numbers.removeWhere((n) =&gt; n % 2 == 0);
  print(numbers);  // {1, 3, 5}

  // retainWhere - 保留满足条件的元素
  var numbers2 = {1, 2, 3, 4, 5};
  numbers2.retainWhere((n) =&gt; n &gt; 2);
  print(numbers2);  // {3, 4, 5}

  // clear - 清空集合
  set.clear();
  print(set);  // {}
  print(set.isEmpty);  // true
}
查询元素
查询方法
void main() {
  var set = {1, 2, 3, 4, 5};

  // contains - 是否包含元素
  print(set.contains(3));   // true
  print(set.contains(10));  // false

  // containsAll - 是否包含所有元素
  print(set.containsAll({1, 2, 3}));  // true
  print(set.containsAll({1, 10}));    // false

  // any - 是否有元素满足条件
  print(set.any((n) =&gt; n &gt; 3));  // true

  // every - 是否所有元素都满足条件
  print(set.every((n) =&gt; n &gt; 0));  // true
  print(set.every((n) =&gt; n &gt; 2));  // false

  // first / last - 获取元素（不保证顺序）
  print(set.first);  // 1（可能是任意元素）
  print(set.last);   // 5（可能是任意元素）

  // length - 集合大小
  print(set.length);  // 5

  // isEmpty / isNotEmpty
  print(set.isEmpty);     // false
  print(set.isNotEmpty);  // true
}
lookup 操作
void main() {
  var set = {1, 2, 3};

  // lookup - 查找元素，返回集合中的实际对象
  // 对于自定义对象，可以获取集合中相等的对象
  var found = set.lookup(2);
  print(found);  // 2
}
集合运算
数学运算
void main() {
  var setA = {1, 2, 3, 4};
  var setB = {3, 4, 5, 6};

  // union - 并集
  var union = setA.union(setB);
  print(union);  // {1, 2, 3, 4, 5, 6}

  // intersection - 交集
  var intersection = setA.intersection(setB);
  print(intersection);  // {3, 4}

  // difference - 差集（在 A 但不在 B）
  var difference = setA.difference(setB);
  print(difference);  // {1, 2}

  // 差集（在 B 但不在 A）
  var difference2 = setB.difference(setA);
  print(difference2);  // {5, 6}
}
集合关系
void main() {
  var set1 = {1, 2, 3, 4, 5};
  var set2 = {1, 2, 3};
  var set3 = {6, 7};

  // containsAll - 是否包含另一个集合的所有元素
  print(set1.containsAll(set2));  // true
  print(set2.containsAll(set1));  // false

  // 检查交集是否为空
  print(set2.intersection(set3).isEmpty);  // true
  print(set1.intersection(set2).isEmpty);  // false
}
转换操作
转换方法
void main() {
  var set = {1, 2, 3, 4, 5};

  // toList - 转换为 List
  var list = set.toList();
  print(list);  // [1, 2, 3, 4, 5]（顺序可能不同）

  // map - 转换每个元素
  var doubled = set.map((n) =&gt; n * 2);
  print(doubled.toSet());  // {2, 4, 6, 8, 10}

  // where - 过滤元素
  var evens = set.where((n) =&gt; n % 2 == 0);
  print(evens.toSet());  // {2, 4}

  // any / every - 检查条件
  print(set.any((n) =&gt; n &gt; 3));  // true
  print(set.every((n) =&gt; n &gt; 0));  // true

  // join - 连接为字符串
  var words = {&#039;Hello&#039;, &#039;World&#039;};
  print(words.join(&#039; &#039;));  // Hello World（顺序可能不同）

  // take / skip
  var taken = set.take(3);
  print(taken.toSet());  // 前 3 个元素

  var skipped = set.skip(2);
  print(skipped.toSet());  // 跳过前 2 个元素
}
遍历 Set
遍历方法
void main() {
  var colors = {&#039;red&#039;, &#039;green&#039;, &#039;blue&#039;};

  // forEach
  colors.forEach((color) {
    print(color);
  });

  // for-in
  for (var color in colors) {
    print(color);
  }

  // 转换为 List 后遍历（如果需要顺序）
  var sortedColors = colors.toList()..sort();
  for (var color in sortedColors) {
    print(color);
  }
}
Set 的性能考虑
性能特点
void performance() {
  // Set 操作的时间复杂度：
  // add() - O(1)
  // remove() - O(1)
  // contains() - O(1)
  // length - O(1)
  // first / last - O(1)
  // union() - O(n + m)
  // intersection() - O(min(n, m))

  // 性能建议
  var set = {1, 2, 3, 4, 5};

  // ✅ 快速操作
  var hasElement = set.contains(3);   // O(1)
  set.add(6);                         // O(1)
  set.remove(3);                      // O(1)

  // ⚠️ 较慢操作
  var union = set.union({6, 7, 8});   // O(n + m)
  var intersection = set.intersection({3, 4, 5});  // O(min(n, m))
}
去重性能
void deduplication() {
  // ✅ 使用 Set 去重 - 最高效
  var list = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4];
  var unique = list.toSet().toList();  // O(n)

  // ❌ 使用循环去重 - 效率低
  var unique2 = &lt;int&gt;[];
  for (var item in list) {
    if (!unique2.contains(item)) {  // 每次 contains 都是 O(n)
      unique2.add(item);
    }
  }  // 总复杂度 O(n²)
}
最佳实践

[!tip&gt; Set 使用建议



使用字面量创建
var set = {1, 2, 3};  // ✅ 推荐
var set2 = Set&lt;int&gt;.from([1, 2, 3]);  // ❌ 不必要


用于去重
var list = [1, 2, 2, 3, 3, 3];
var unique = list.toSet().toList();  // ✅ 高效去重


用于成员测试
// ✅ 使用 Set - O(1)
var validValues = {1, 2, 3, 4, 5};
if (validValues.contains(input)) {
  // 处理
}

// ❌ 使用 List - O(n)
var validList = [1, 2, 3, 4, 5];
if (validList.contains(input)) {
  // 处理
}


使用展开运算符
var set1 = {1, 2, 3};
var set2 = {4, 5, 6};
var combined = {...set1, ...set2};  // ✅ 简洁


使用不可变 Set 保护数据
var unmodifiable = Set.unmodifiable({1, 2, 3});


常见陷阱

[!danger&gt; 陷阱 1：依赖 Set 的顺序

var set = {1, 2, 3, 4, 5};
print(set.first);  // 可能不是 1
print(set.last);   // 可能不是 5

// ✅ 如需顺序，转换为 List
var list = set.toList()..sort();
print(list.first);  // 1
print(list.last);   // 5

[!danger&gt; 陷阱 2：自定义类必须正确实现 hashCode

class Person {
  String name;
  int age;
  Person(this.name, this.age);

  // ❌ 没有重写 hashCode 和 ==
  // Set 无法正确识别重复的对象
}

// ✅ 正确实现
class Person {
  String name;
  int age;
  Person(this.name, this.age);

  @override
  bool operator ==(Object other) =&gt;
      other is Person &amp;&amp; other.name == name &amp;&amp; other.age == age;

  @override
  int get hashCode =&gt; Object.hash(name, age);
}

var people = {
  Person(&#039;Alice&#039;, 30),
  Person(&#039;Alice&#039;, 30),  // 会被识别为重复
};
print(people.length);  // 1

[!danger&gt; 陷阱 3：修改正在遍历的集合

var set = {1, 2, 3, 4, 5};

// ❌ 错误：在遍历时修改
for (var item in set) {
  if (item % 2 == 0) {
    set.remove(item);  // ❌ ConcurrentModificationError
  }
}

// ✅ 正确：使用 removeWhere
set.removeWhere((item) =&gt; item % 2 == 0);

[!danger&gt; 陷阱 4：可空 Set 的类型推断

// ❌ 类型推断错误
var set = {1, 2, 3};
set.add(null);  // 编译错误

// ✅ 明确指定可空类型
Set&lt;int?&gt; nullableSet = {1, 2, 3};
nullableSet.add(null);  // ✅ 正确
