字符串处理



                  概述 



String 是 Dart 中最常用的类型之一，用于表示文本数据。Dart 提供了丰富的字符串操作方法，包括拼接、插值、分割、替换、搜索等。
创建字符串
基本创建方式
void main() {
  // 单引号或双引号
  var s1 = &#039;Hello&#039;;
  var s2 = &quot;World&quot;;

  // 多行字符串
  var multiLine1 = &#039;&#039;&#039;
  This is a
  multi-line
  string
  &#039;&#039;&#039;;

  var multiLine2 = &quot;&quot;&quot;
  Another
  multi-line
  string
  &quot;&quot;&quot;;

  // 原始字符串（不转义）
  var raw = r&#039;C:\Users\Documents&#039;;
  print(raw);  // C:\Users\Documents

  // 相邻字符串字面量自动连接
  var s3 = &#039;Hello&#039; &#039; &#039; &#039;World&#039;;
  print(s3);  // Hello World
}
字符串插值
${} 语法
void main() {
  var name = &#039;Alice&#039;;
  var age = 30;

  // $variable
  print(&#039;Name: $name&#039;);  // Name: Alice

  // ${expression}
  print(&#039;Next year: ${name} will be ${age + 1}&#039;);  // Next year: Alice will be 31

  // 表达式
  print(&#039;2 + 3 = ${2 + 3}&#039;);  // 2 + 3 = 5

  // 对象
  var person = Person(&#039;Bob&#039;, 25);
  print(&#039;Person: $person&#039;);  // Person: Bob(25)
}

class Person {
  String name;
  int age;
  Person(this.name, this.age);

  @override
  String toString() =&gt; &#039;$name($age)&#039;;
}
字符串属性
基本属性
void main() {
  var text = &#039;Hello World&#039;;

  // length - 长度
  print(text.length);  // 11

  // isEmpty - 是否为空
  print(&#039;&#039;.isEmpty);  // true

  // isNotEmpty - 是否不为空
  print(text.isNotEmpty);  // true

  // codeUnits - UTF-16 代码单元
  print(text.codeUnits);  // [72, 101, 108, 108, 111, 32, 87, 111, 114, 108, 100]

  // runes - Unicode 代码点
  var emoji = &#039;😀&#039;;
  print(emoji.runes);  // (128512)
}
字符串比较
比较方法
void main() {
  var s1 = &#039;Hello&#039;;
  var s2 = &#039;World&#039;;
  var s3 = &#039;Hello&#039;;

  // == - 内容相等
  print(s1 == s3);  // true

  // compareTo - 比较顺序
  print(s1.compareTo(s2));  // -15 (s1 &lt; s2)
  print(s2.compareTo(s1));  // 15 (s2 &gt; s1)

  // startsWith - 是否以指定字符串开始
  print(s1.startsWith(&#039;H&#039;));  // true
  print(s1.startsWith(&#039;He&#039;));  // true

  // endsWith - 是否以指定字符串结束
  print(s2.endsWith(&#039;ld&#039;));  // true
}
字符串搜索
搜索方法
void main() {
  var text = &#039;Hello World Hello&#039;;

  // indexOf - 查找子字符串位置
  print(text.indexOf(&#039;Hello&#039;));  // 0
  print(text.indexOf(&#039;World&#039;));  // 6
  print(text.indexOf(&#039;Dart&#039;));  // -1（未找到）

  // lastIndexOf - 查找最后出现位置
  print(text.lastIndexOf(&#039;Hello&#039;));  // 12

  // contains - 是否包含子字符串
  print(text.contains(&#039;World&#039;));  // true
  print(text.contains(&#039;Dart&#039;));  // false

  // indexOf - 从指定位置开始查找
  print(text.indexOf(&#039;Hello&#039;, 1));  // 12
}
字符串提取
提取方法
void main() {
  var text = &#039;Hello World&#039;;

  // [] - 索引访问
  print(text[0]);  // H
  print(text[6]);  // W

  // substring - 子字符串
  print(text.substring(0, 5));  // Hello
  print(text.substring(6));  // World

  // split - 分割
  var words = text.split(&#039; &#039;);
  print(words);  // [Hello, World]

  // split - 多字符分隔
  var csv = &#039;a,b,c,d,e&#039;;
  var parts = csv.split(&#039;,&#039;);
  print(parts);  // [a, b, c, d, e]

  // splitMapJoin - 高级分割
  var result = text.splitMapJoin(
    &#039; &#039;,
    onMatch: (m) =&gt; &#039;_&#039;,
    onNonMatch: (s) =&gt; s.toUpperCase(),
  );
  print(result);  // HELLO_WORLD
}
字符串转换
转换方法
void main() {
  var text = &#039;Hello World&#039;;

  // toLowerCase - 转小写
  print(text.toLowerCase());  // hello world

  // toUpperCase - 转大写
  print(text.toUpperCase());  // HELLO WORLD

  // trim - 去除首尾空格
  var spaced = &#039;  hello  &#039;;
  print(spaced.trim());  // hello

  // trimLeft / trimRight
  print(spaced.trimLeft());  // hello
  print(spaced.trimRight());  //   hello

  // replaceAll - 替换所有
  print(text.replaceAll(&#039;o&#039;, &#039;O&#039;));  // HellO WOrld

  // replaceFirst - 替换第一个
  print(text.replaceFirst(&#039;o&#039;, &#039;O&#039;));  // HellO World

  // replaceRange - 替换范围
  print(text.replaceRange(0, 5, &#039;Hi&#039;));  // Hi World

  // padLeft / padRight - 填充
  print(&#039;5&#039;.padLeft(3, &#039;0&#039;));  // 005
  print(&#039;5&#039;.padRight(3, &#039;0&#039;));  // 500
}
正则表达式
RegExp 使用
void main() {
  var text = &#039;Hello 123 World 456&#039;;

  // hasMatch - 是否匹配
  var hasNumber = RegExp(r&#039;\d+&#039;).hasMatch(text);
  print(hasNumber);  // true

  // allMatches - 所有匹配
  var numbers = RegExp(r&#039;\d+&#039;).allMatches(text);
  for (var match in numbers) {
    print(match.group(0));  // 123, 456
  }

  // firstMatch - 第一个匹配
  var first = RegExp(r&#039;\d+&#039;).firstMatch(text);
  print(first?.group(0));  // 123

  // string matching - 字符串方法
  print(text.contains(RegExp(r&#039;\d+&#039;)));  // true
  print(text.startsWith(RegExp(r&#039;H.*&#039;)));  // true

  // replaceAll - 使用正则替换
  var replaced = text.replaceAll(RegExp(r&#039;\d+&#039;), &#039;#&#039;);
  print(replaced);  // Hello # World #
}
字符串编码
UTF-8 和 Base64
void main() {
  // UTF-8 编码
  var text = &#039;Hello 你好&#039;;
  var utf8Bytes = utf8.encode(text);
  print(utf8Bytes);  // [72, 101, 108, 108, 111, 32, 228, 189, 160, 229, 165, 189]

  // UTF-8 解码
  var decoded = utf8.decode(utf8Bytes);
  print(decoded);  // Hello 你好

  // Base64 编码
  var base64 = base64Encode(utf8Bytes);
  print(base64);  // SGVsbG8g5L2g5aW9

  // Base64 解码
  var decodedBytes = base64Decode(base64);
  print(utf8.decode(decodedBytes));  // Hello 你好

  // runes - Unicode 代码点
  var emoji = &#039;😀👍&#039;;
  for (var rune in emoji.runes) {
    print(String.fromCharCode(rune));
  }
  // 😀
  // 👍
}
StringBuffer
高效字符串构建
void main() {
  // ❌ 低效：多次创建字符串对象
  var s = &#039;&#039;;
  for (var i = 0; i &lt; 1000; i++) {
    s += &#039;number $i &#039;;  // 每次都创建新字符串
  }

  // ✅ 高效：使用 StringBuffer
  var sb = StringBuffer();
  for (var i = 0; i &lt; 1000; i++) {
    sb.write(&#039;number $i &#039;);
  }
  var result = sb.toString();

  // StringBuffer 方法
  var buffer = StringBuffer()
    ..write(&#039;Hello&#039;)
    ..write(&#039; &#039;)
    ..write(&#039;World&#039;)
    ..write(&#039;!&#039;)
    ..writeln();  // 添加换行

  print(buffer.toString());  // Hello World!
}
字符串格式化
toStringAsFixed 等
void main() {
  // 数字格式化
  var pi = 3.1415926;

  // toStringAsFixed - 固定小数位数
  print(pi.toStringAsFixed(2));  // 3.14

  // toStringAsPrecision - 固定精度
  print(pi.toStringAsPrecision(3));  // 3.14

  // toRadixString - 进制转换
  var number = 255;
  print(number.toRadixString(16));  // ff
  print(number.toRadixString(2));   // 11111111

  // padLeft - 补零
  print(&#039;5&#039;.padLeft(2, &#039;0&#039;));  // 05

  // 字符串模板
  var name = &#039;Alice&#039;;
  var age = 30;
  print(&#039;Name: ${name.padRight(10)} Age: $age&#039;);
  // Name: Alice      Age: 30
}
常见模式
1. 验证字符串
// 使用扩展方法验证
extension StringValidation on String {
  bool get isEmail {
    return RegExp(
      r&#039;^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$&#039;,
    ).hasMatch(this);
  }

  bool get isUrl {
    return RegExp(r&#039;^https?://&#039;).hasMatch(this);
  }

  bool get isPhoneNumber {
    return RegExp(r&#039;^\+?[\d\s-]+$&#039;).hasMatch(this);
  }
}

void main() {
  print(&#039;user@example.com&#039;.isEmail);  // true
  print(&#039;dart.dev&#039;.isUrl);  // true
  print(&#039;+1 234 567 8900&#039;.isPhoneNumber);  // true
}
2. 字符串清洗
extension StringCleaning on String {
  String get removeExtraSpaces {
    return replaceAll(RegExp(r&#039;\s+&#039;), &#039; &#039;).trim();
  }

  String get onlyNumbers {
    return replaceAll(RegExp(r&#039;[^\d]&#039;), &#039;&#039;);
  }

  String get onlyLetters {
    return replaceAll(RegExp(r&#039;[^a-zA-Z]&#039;), &#039;&#039;);
  }
}

void main() {
  print(&#039;hello   world&#039;.removeExtraSpaces);  // hello world
  print(&#039;abc123def&#039;.onlyNumbers);  // 123
  print(&#039;abc123def&#039;.onlyLetters);  // abcdef
}
3. 首字母大小写
extension StringCase on String {
  String get capitalize {
    if (isEmpty) return this;
    return &#039;${this[0].toUpperCase()}${substring(1)}&#039;;
  }

  String get titleCase {
    return split(&#039; &#039;)
        .map((word) =&gt; word.isEmpty
            ? word
            : &#039;${word[0].toUpperCase()}${word.substring(1)}&#039;)
        .join(&#039; &#039;);
  }
}

void main() {
  print(&#039;hello world&#039;.capitalize);  // Hello world
  print(&#039;hello world&#039;.titleCase);  // Hello World
}
