数学运算



                  概述 



dart:math 是 Dart 的核心库，提供了数学常数、数学函数、随机数生成以及几何图形类。掌握这些工具对于科学计算、游戏开发和数据处理至关重要。
导入 dart:math 库
import &#039;dart:math&#039;;

void main() {
  // 所有示例都需要先导入 dart:math
  print(&#039;dart:math 库已导入&#039;);
}
数学常数
常用数学常数
import &#039;dart:math&#039;;

void main() {
  // e - 自然对数的底数
  print(&#039;e = $e&#039;);  // 2.718281828459045

  // pi - 圆周率
  print(&#039;pi = $pi&#039;);  // 3.141592653589793

  // 使用示例
  var radius = 5.0;
  var circle = 2 * pi * radius;
  print(&#039;圆周长 = $circle&#039;);  // 31.41592653589793

  var square = e * e;
  print(&#039;e² = $square&#039;);  // 7.3890560989306495
}
数学函数
基本数学运算
import &#039;dart:math&#039;;

void main() {
  // max - 最大值
  print(max(10, 20));  // 20
  print(max(-5, -10));  // -5

  // min - 最小值
  print(min(10, 20));  // 10
  print(min(-5, -10));  // -10

  // sqrt - 平方根
  print(sqrt(16));  // 4.0
  print(sqrt(2));   // 1.4142135623730951

  // pow - 幂运算
  print(pow(2, 3));   // 8.0
  print(pow(10, 2));  // 100.0
  print(pow(4, 0.5)); // 2.0 (相当于 sqrt(4))

  // abs - 绝对值（实例方法）
  print((-10).abs());   // 10
  print((3.14).abs());  // 3.14

  // 使用示例
  var distance = sqrt(pow(5, 2) + pow(12, 2));
  print(&#039;距离 = $distance&#039;);  // 13.0
}
三角函数
import &#039;dart:math&#039;;

void main() {
  var angle = pi / 4;  // 45 度

  // sin - 正弦
  print(sin(angle));  // 0.7071067811865475

  // cos - 余弦
  print(cos(angle));  // 0.7071067811865476

  // tan - 正切
  print(tan(angle));  // 0.9999999999999999

  // asin - 反正弦 (返回弧度)
  print(asin(0.5));  // 0.5235987755982989

  // acos - 反余弦
  print(acos(0.5));  // 1.0471975511965979

  // atan - 反正切
  print(atan(1));    // 0.7853981633974483

  // atan2 - 反正切 (考虑象限)
  print(atan2(1, 1));  // 0.7853981633974483 (45 度)
  print(atan2(-1, -1));  // -2.356194490192345 (135 度)

  // 角度转换
  var degrees = 45;
  var radians = degrees * pi / 180;
  print(&#039;45 度 = $radians 弧度&#039;);  // 0.7853981633974483
}
指数和对数函数
import &#039;dart:math&#039;;

void main() {
  // exp - e 的 x 次方
  print(exp(1));  // 2.718281828459045
  print(exp(2));  // 7.38905609893065

  // log - 自然对数
  print(log(e));   // 1.0
  print(log(10));  // 2.302585092994046

  // log10 - 以 10 为底的对数（通过换底公式计算）
  final ln10 = log(10);
  print(log(10) / ln10);   // 1.0
  print(log(100) / ln10);  // 2.0
  print(log(1000) / ln10); // 3.0

  // 使用示例：计算复利
  var principal = 1000.0;
  var rate = 0.05;
  var years = 10;
  var amount = principal * pow(e, rate * years);
  print(&#039;10 年后的金额：$amount&#039;);  // 1648.72...
}
其他数学函数
import &#039;dart:math&#039;;

void main() {
  // clamp - 限制值在范围内
  print(5.0.clamp(0, 10));   // 5.0
  print(-5.0.clamp(0, 10));  // 0.0
  print(15.0.clamp(0, 10));  // 10.0

  // truncate - 截断小数
  print(3.7.truncate());   // 3
  print((-3.7).truncate()); // -3

  // round - 四舍五入
  print(3.4.round());  // 3
  print(3.5.round());  // 4
  print((-3.5).round()); // -3

  // ceil - 向上取整
  print(3.1.ceil());   // 4
  print((-3.1).ceil()); // -3

  // floor - 向下取整
  print(3.9.floor());   // 3
  print((-3.9).floor()); // -4

  // sign - 符号函数
  print(10.sign);   // 1
  print((-10).sign); // -1
  print(0.sign);    // 0

  // isFinite - 是否有限
  print(double.infinity.isFinite);  // false
  print(10.0.isFinite);             // true

  // isInfinite - 是否无限
  print(double.infinity.isInfinite);  // true
  print(10.0.isInfinite);             // false

  // isNaN - 是否非数字
  print(double.nan.isNaN);  // true
  print(10.0.isNaN);        // false
}
Random 类
随机数生成
import &#039;dart:math&#039;;

void main() {
  var random = Random();

  // nextInt - 生成随机整数 (0 &lt;= n &lt; max)
  print(random.nextInt(10));  // 0-9 之间的随机数
  print(random.nextInt(100)); // 0-99 之间的随机数

  // nextDouble - 生成随机浮点数 (0.0 &lt;= n &lt; 1.0)
  print(random.nextDouble());  // 0.123456789...
  print(random.nextDouble());  // 0.987654321...

  // nextBool - 生成随机布尔值
  print(random.nextBool());  // true 或 false

  // 生成指定范围的随机数
  var min = 10;
  var max = 20;
  var randomInRange = min + random.nextInt(max - min);
  print(&#039;随机数 ($min-$max): $randomInRange&#039;);

  // 生成随机小数
  var randomDouble = random.nextDouble() * 100;
  print(&#039;随机小数：$randomDouble&#039;);
}
带种子的随机数
import &#039;dart:math&#039;;

void main() {
  // 使用种子创建随机数生成器
  var random1 = Random(42);
  var random2 = Random(42);

  // 相同种子产生相同序列
  print(random1.nextInt(100));  // 每次运行都相同
  print(random2.nextInt(100));  // 与上面相同

  // 不使用种子（基于当前时间）
  var random3 = Random();
  print(random3.nextInt(100));  // 每次运行不同
}
随机数实用示例
import &#039;dart:math&#039;;

void main() {
  var random = Random();

  // 生成随机密码
  var chars = &#039;abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789&#039;;
  var password = List.generate(12, (i) =&gt; chars[random.nextInt(chars.length)]).join();
  print(&#039;密码：$password&#039;);

  // 随机选择元素
  var colors = [&#039;red&#039;, &#039;green&#039;, &#039;blue&#039;, &#039;yellow&#039;];
  var randomColor = colors[random.nextInt(colors.length)];
  print(&#039;随机颜色：$randomColor&#039;);

  // 洗牌算法
  var numbers = [1, 2, 3, 4, 5];
  numbers.shuffle();
  print(&#039;洗牌后：$numbers&#039;);

  // 投掷骰子
  var dice = random.nextInt(6) + 1;  // 1-6
  print(&#039;骰子：$dice&#039;);

  // 抛硬币
  var coin = random.nextBool() ? &#039;正面&#039; : &#039;反面&#039;;
  print(&#039;硬币：$coin&#039;);
}
Point 类
点的创建和操作
import &#039;dart:math&#039;;

void main() {
  // 创建点
  var point1 = Point(10, 20);
  var point2 = Point(30, 40);
  var origin = Point(0, 0);

  print(&#039;Point1: $point1&#039;);  // Point(10, 20)
  print(&#039;Point2: $point2&#039;);  // Point(30, 40)

  // 访问坐标
  print(&#039;X: ${point1.x}&#039;);  // 10
  print(&#039;Y: ${point1.y}&#039;);  // 20

  // distanceTo - 计算两点距离
  var distance = point1.distanceTo(point2);
  print(&#039;距离：$distance&#039;);  // 28.284271247461902

  // squaredDistanceTo - 距离的平方（性能更好）
  var squaredDistance = point1.squaredDistanceTo(point2);
  print(&#039;距离平方：$squaredDistance&#039;);  // 800.0

  // 到原点距离（使用 distanceTo 方法）
  var distanceToOrigin = point1.distanceTo(Point(0, 0));
  print(&#039;到原点距离：$distanceToOrigin&#039;);  // 22.360679774997898

  // 向量长度（通过计算到原点的距离）
  var magnitude = point1.distanceTo(Point(0, 0));
  print(&#039;向量长度：$magnitude&#039;);  // 22.360679774997898
}
点的运算
import &#039;dart:math&#039;;

void main() {
  var point1 = Point(10, 20);
  var point2 = Point(5, 5);

  // 加法
  var sum = point1 + point2;
  print(&#039;加法：$sum&#039;);  // Point(15, 25)

  // 减法
