}
Rectangle 类
矩形的创建
import &#039;dart:math&#039;;

void main() {
  // 通过左上角和右下角创建（使用 Rectangle 构造函数）
  var rect1 = Rectangle(0, 0, 10, 10);
  print(&#039;矩形 1: $rect1&#039;);

