日期时间



                  概述 



DateTime 是 Dart 中处理日期和时间的核心类，支持创建、解析、格式化和计算日期时间，以及时区转换等操作。掌握 DateTime 的使用对于处理时间相关的业务逻辑至关重要。
创建 DateTime
基本创建方式
void main() {
  // 获取当前时间
  var now = DateTime.now();
  print(now);  // 2026-03-02 10:30:45.123

  // 指定日期时间
  var date1 = DateTime(2026, 3, 2);
  print(date1);  // 2026-03-02 00:00:00.000

  var date2 = DateTime(2026, 3, 2, 14, 30, 45);
  print(date2);  // 2026-03-02 14:30:45.000

  var date3 = DateTime(2026, 3, 2, 14, 30, 45, 123);
  print(date3);  // 2026-03-02 14:30:45.123

  // 使用微秒
  var date4 = DateTime(2026, 3, 2, 14, 30, 45, 123, 456);
  print(date4);  // 2026-03-02 14:30:45.000123456

  // UTC 时间
  var utc = DateTime.utc(2026, 3, 2, 14, 30);
  print(utc);  // 2026-03-02 14:30:00.000Z

  // 解析字符串
  var parsed = DateTime.parse(&#039;2026-03-02 14:30:45&#039;);
  print(parsed);  // 2026-03-02 14:30:45.000

  var parsed2 = DateTime.parse(&#039;2026-03-02T14:30:45.123Z&#039;);
  print(parsed2);  // 2026-03-02 14:30:45.123Z
}
特殊时间值
void main() {
  // Unix 时间戳
  var fromUnix = DateTime.fromMillisecondsSinceEpoch(1709350245123);
  print(fromUnix);  // 2024-03-02 14:30:45.123

  // 微秒级时间戳
  var fromMicroseconds = DateTime.fromMicrosecondsSinceEpoch(1709350245123456);
  print(fromMicroseconds);  // 2024-03-02 14:30:45.123456

  // 获取时间戳
  var now = DateTime.now();
  print(now.millisecondsSinceEpoch);  // 1709350245123
  print(now.microsecondsSinceEpoch);  // 1709350245123456
}
访问日期时间组件
获取各个组件
void main() {
  var dateTime = DateTime(2026, 3, 2, 14, 30, 45, 123);

  // 年月日
  print(dateTime.year);   // 2026
  print(dateTime.month);  // 3
