  print(dateTime.timeZoneOffset);   // Duration 时区偏移
}
日期时间比较
比较操作
void main() {
  var date1 = DateTime(2026, 3, 2);
  var date2 = DateTime(2026, 3, 3);
  var date3 = DateTime(2026, 3, 2);

  // isAtSameMomentAs - 精确比较
  print(date1.isAtSameMomentAs(date3));  // true
  print(date1.isAtSameMomentAs(date2));  // false

  // compareTo - 排序比较
  print(date1.compareTo(date2));  // -1 (date1 &lt; date2)
  print(date2.compareTo(date1));  // 1 (date2 &gt; date1)
  print(date1.compareTo(date3));  // 0 (相等)

  // isBefore / isAfter
  print(date1.isBefore(date2));  // true
  print(date1.isAfter(date2));   // false

  // 使用运算符（需要先调用 compareTo）
  print(date1.isBefore(date2));  // true
  print(date2.isAfter(date1));   // true
}
日期时间计算
加减运算
void main() {
  var now = DateTime(2026, 3, 2, 14, 30);

  // 加法
  var tomorrow = now.add(Duration(days: 1));
  print(tomorrow);  // 2026-03-03 14:30:00.000

  var nextWeek = now.add(Duration(days: 7));
  print(nextWeek);  // 2026-03-09 14:30:00.000

  var nextHour = now.add(Duration(hours: 1));
  print(nextHour);  // 2026-03-02 15:30:00.000

  // 减法
  var yesterday = now.subtract(Duration(days: 1));
  print(yesterday);  // 2026-03-01 14:30:00.000

  var lastHour = now.subtract(Duration(hours: 1));
  print(lastHour);  // 2026-03-02 13:30:00.000

  // 计算差值
  var date1 = DateTime(2026, 3, 1);
  var date2 = DateTime(2026, 3, 10);
  var difference = date2.difference(date1);
  print(difference);  // 216:00:00.000000 (9 天)
  print(difference.inDays);  // 9
  print(difference.inHours);  // 216
}
Duration 使用
void main() {
  // 创建 Duration
  var d1 = Duration(days: 1, hours: 2, minutes: 30);
  print(d1);  // 26:30:00.000000

  var d2 = Duration(seconds: 90);
  print(d2);  // 0:01:30.000000

  // Duration 属性
  var duration = Duration(days: 2, hours: 5, minutes: 30, seconds: 45);
  print(duration.inDays);  // 2
  print(duration.inHours);  // 53 (2*24 + 5)
  print(duration.inMinutes);  // 3210 (53*60 + 30)
  print(duration.inSeconds);  // 192645
  print(duration.inMilliseconds);  // 192645000

  // Duration 运算
  var d3 = Duration(hours: 2);
  var d4 = Duration(hours: 3);
  print(d3 + d4);  // 5:00:00.000000
  print(d4 - d3);  // 1:00:00.000000

  // Duration 比较
  print(d3 &gt; d2);  // true
  print(d3 == d4);  // false
}
日期时间格式化
格式化输出
void main() {
  var now = DateTime(2026, 3, 2, 14, 30, 45);

  // toString() - ISO 8601 格式
  print(now.toString());  // 2026-03-02 14:30:45.000

  // toIso8601String()
  print(now.toIso8601String());  // 2026-03-02T14:30:45.000

  // 自定义格式化（手动拼接）
  var formatted = &#039;${now.year}-${_twoDigits(now.month)}-${_twoDigits(now.day)} &#039;
      &#039;${_twoDigits(now.hour)}:${_twoDigits(now.minute)}:${_twoDigits(now.second)}&#039;;
  print(formatted);  // 2026-03-02 14:30:45

  // 使用 intl 包（推荐）
  // import &#039;package:intl/intl.dart&#039;;
  // var formatter = DateFormat(&#039;yyyy-MM-dd HH:mm:ss&#039;);
  // print(formatter.format(now));  // 2026-03-02 14:30:45
}

String _twoDigits(int n) =&gt; n.toString().padLeft(2, &#039;0&#039;);
解析字符串
void main() {
  // parse() - 解析 ISO 8601 格式
  var date1 = DateTime.parse(&#039;2026-03-02&#039;);
  print(date1);  // 2026-03-02 00:00:00.000

  var date2 = DateTime.parse(&#039;2026-03-02T14:30:45&#039;);
  print(date2);  // 2026-03-02 14:30:45.000

  var date3 = DateTime.parse(&#039;2026-03-02T14:30:45.123Z&#039;);
  print(date3);  // 2026-03-02 14:30:45.123Z (UTC)

  // 解析时区信息
  var date4 = DateTime.parse(&#039;2026-03-02T14:30:45+08:00&#039;);
  print(date4);  // 2026-03-02 14:30:45.000

  // 自定义解析（需要 intl 包）
  // import &#039;package:intl/intl.dart&#039;;
  // var formatter = DateFormat(&#039;yyyy-MM-dd HH:mm:ss&#039;);
  // var date5 = formatter.parse(&#039;2026-03-02 14:30:45&#039;);
  // print(date5);  // 2026-03-02 14:30:45.000
}
时区处理
UTC 和本地时间
void main() {
  // 本地时间
  var local = DateTime(2026, 3, 2, 14, 30);
  print(local);  // 2026-03-02 14:30:00.000 (本地时区)
  print(local.isUtc);  // false

  // UTC 时间
  var utc = DateTime.utc(2026, 3, 2, 14, 30);
  print(utc);  // 2026-03-02 14:30:00.000Z
  print(utc.isUtc);  // true

  // 转换为 UTC
  var toUtc = local.toUtc();
  print(toUtc);  // 2026-03-02 06:30:00.000Z (假设本地是 UTC+8)

  // 转换为本地时间
  var toLocal = utc.toLocal();
  print(toLocal);  // 2026-03-02 22:30:00.000 (假设本地是 UTC+8)

  // 时区偏移
  print(local.timeZoneOffset);  // 8:00:00.000000 (UTC+8)
  print(utc.timeZoneOffset);    // 0:00:00.000000 (UTC)
}
时区转换
void main() {
  // 获取当前时间的 UTC
  var now = DateTime.now();
  var utcNow = now.toUtc();
  print(&#039;Local: $now&#039;);
  print(&#039;UTC: $utcNow&#039;);

  // 从 UTC 创建本地时间
  var utcTime = DateTime.utc(2026, 3, 2, 14, 30);
  var localTime = utcTime.toLocal();
  print(&#039;UTC time: $utcTime&#039;);
  print(&#039;Local time: $localTime&#039;);

  // 计算不同时区的时间（使用 Duration）
  var baseTime = DateTime.utc(2026, 3, 2, 14, 30);
  var tokyoTime = baseTime.add(Duration(hours: 9));  // UTC+9
  var nyTime = baseTime.add(Duration(hours: -5));    // UTC-5
  print(&#039;Tokyo: $tokyoTime&#039;);
  print(&#039;New York: $nyTime&#039;);

  // 使用 intl 包处理时区
  // import &#039;package:intl/intl.dart&#039;;
  // import &#039;package:timezone/timezone.dart&#039; as tz;
  // import &#039;package:timezone/data/latest.dart&#039; as tz_data;
  //
  // tz_data.initializeTimeZones();
  // var location = tz.getLocation(&#039;America/New_York&#039;);
  // var nyDate = tz.TZDateTime.from(baseTime, location);
  // print(nyDate);
}
常用日期时间操作
日期计算
void main() {
  var date = DateTime(2026, 3, 2);

  // 本月第一天
  var firstDayOfMonth = DateTime(date.year, date.month, 1);
  print(firstDayOfMonth);  // 2026-03-01 00:00:00.000

  // 本月最后一天
  var firstDayOfNextMonth = DateTime(date.year, date.month + 1, 1);
  var lastDayOfMonth = firstDayOfNextMonth.subtract(Duration(days: 1));
  print(lastDayOfMonth);  // 2026-03-31 00:00:00.000

  // 本周第一天（周一）
  var monday = date.subtract(Duration(days: date.weekday - 1));
  print(monday);  // 2026-03-02 00:00:00.000 (如果今天是周一)

  // 本周最后一天（周日）
  var sunday = date.add(Duration(days: 7 - date.weekday));
  print(sunday);  // 2026-03-08 00:00:00.000

  // N 天后
  var nextDays = date.add(Duration(days: 7));
  print(nextDays);  // 2026-03-09 00:00:00.000

  // N 天前
  var prevDays = date.subtract(Duration(days: 7));
  print(prevDays);  // 2026-02-23 00:00:00.000
}
时间范围判断
void main() {
  var now = DateTime(2026, 3, 2, 14, 30);
  var start = DateTime(2026, 3, 1, 9, 0);
  var end = DateTime(2026, 3, 3, 18, 0);

  // 判断是否在时间范围内
  var isInRange = now.isAfter(start) &amp;&amp; now.isBefore(end);
  print(isInRange);  // true

  // 判断是否是今天
  var today = DateTime.now();
  var isToday = now.year == today.year &amp;&amp;
               now.month == today.month &amp;&amp;
               now.day == today.day;
  print(isToday);  // 取决于运行时间

  // 判断是否是工作日
  var isWeekday = now.weekday &gt;= 1 &amp;&amp; now.weekday &lt;= 5;
  print(isWeekday);  // true

  // 判断是否是周末
  var isWeekend = now.weekday == 6 || now.weekday == 7;
  print(isWeekend);  // false
}
实用工具函数
日期时间工具
void main() {
  // 计算年龄
  var birthDate = DateTime(1990, 5, 15);
  var today = DateTime.now();
  var age = today.year - birthDate.year;
  if (today.month &lt; birthDate.month ||
      (today.month == birthDate.month &amp;&amp; today.day &lt; birthDate.day)) {
    age--;
  }
  print(&#039;Age: $age&#039;);  // 根据当前日期计算

  // 计算两个日期之间的工作日
  var startDate = DateTime(2026, 3, 1);
  var endDate = DateTime(2026, 3, 31);
  var workDays = 0;
  var current = startDate;
  while (current.isBefore(endDate) || current.isAtSameMomentAs(endDate)) {
    if (current.weekday &gt;= 1 &amp;&amp; current.weekday &lt;= 5) {
      workDays++;
    }
    current = current.add(Duration(days: 1));
  }
  print(&#039;Work days in March 2026: $workDays&#039;);  // 22

  // 格式化为相对时间
  var timestamp = DateTime.now().subtract(Duration(minutes: 5));
  var diff = DateTime.now().difference(timestamp);
  if (diff.inSeconds &lt; 60) {
    print(&#039;${diff.inSeconds} seconds ago&#039;);
  } else if (diff.inMinutes &lt; 60) {
    print(&#039;${diff.inMinutes} minutes ago&#039;);
  } else if (diff.inHours &lt; 24) {
    print(&#039;${diff.inHours} hours ago&#039;);
  } else {
    print(&#039;${diff.inDays} days ago&#039;);
  }
}
最佳实践



                  DateTime 使用建议 





使用 UTC 存储和传输时间
// ✅ 推荐：使用 UTC 存储
var utcTime = DateTime.utc(2026, 3, 2, 14, 30);
// ✅ 显示时转换为本地时间
var localTime = utcTime.toLocal();


使用 Duration 进行时间计算
// ✅ 使用 Duration
var tomorrow = now.add(Duration(days: 1));
// ❌ 避免手动计算毫秒
var tomorrow2 = DateTime.fromMillisecondsSinceEpoch(
  now.millisecondsSinceEpoch + 24 * 60 * 60 * 1000
);


使用 intl 包进行格式化
import &#039;package:intl/intl.dart&#039;;

// ✅ 使用 intl 包
var formatter = DateFormat(&#039;yyyy-MM-dd HH:mm:ss&#039;);
var formatted = formatter.format(now);


处理时区转换
// ✅ 明确使用 UTC 或本地时间
var utcNow = DateTime.now().toUtc();
var localNow = utcNow.toLocal();


使用不可变 DateTime
// DateTime 对象本身是不可变的
var now = DateTime.now();
var tomorrow = now.add(Duration(days: 1));
print(now);  // 原时间不变
print(tomorrow);  // 新时间


常见陷阱



                  陷阱 1：月份从 1 开始 



// ❌ 错误
var date1 = DateTime(2026, 0, 1);  // RangeError

// ✅ 正确
var date2 = DateTime(2026, 1, 1);  // 1 月



                  陷阱 2：DateTime 是不可变的 



var now = DateTime.now();
now.add(Duration(days: 1));  // ❌ 这样不会改变 now
print(now);  // 仍然是原时间

// ✅ 正确做法
var tomorrow = now.add(Duration(days: 1));
print(tomorrow);  // 新时间



                  陷阱 3：时区混淆 



var local = DateTime(2026, 3, 2, 14, 30);
var utc = DateTime.utc(2026, 3, 2, 14, 30);

// ❌ 直接比较可能有问题
print(local == utc);  // false（即使表示同一时刻）

// ✅ 转换为同一时区再比较
print(local.toUtc().isAtSameMomentAs(utc));  // true



                  陷阱 4：跨月计算 



var date = DateTime(2026, 3, 31);

// ❌ 可能导致错误
var nextMonth = DateTime(date.year, date.month + 1, date.day);
// 4 月 31 日不存在，会自动调整为 5 月 1 日

// ✅ 更安全的方式
var nextMonthSafe = DateTime(date.year, date.month + 1, 1)
    .add(Duration(days: date.day - 1));
