Dart 代码风格指南



                  概述 



本指南基于 Dart 官方代码风格规范，涵盖命名约定、格式化规则、文档注释和代码组织。遵循这些规范将使你的代码更易读、更易维护，并与 Dart 生态系统保持一致。
命名约定
类型命名（UpperCamelCase）
类、枚举、类型定义和泛型参数使用大驼峰命名法。
void main() {
  // 类名、枚举、typedef、泛型
  class MyClass {}
  enum Color { red, green, blue }
  typedef UserId = String;
  class Cache&lt;T&gt; {}
  class Repository&lt;TKey, TValue&gt; {}

  print(&#039;命名约定示例&#039;);
}



                  类型命名规则 




类名：MyClass, DatabaseConnection
枚举：HttpStatus, UserRole
typedef：JsonObject, FilterCallback
泛型：T, E, TKey, TValue

变量和成员命名（lowerCamelCase）
变量、参数、函数、成员使用小驼峰命名法。
void main() {
  // 变量、函数、常量、私有成员
  var itemCount = 10;
  int calculateSum(int a, int b) =&gt; a + b;
  const maxItems = 100;

  class User {
    String _name;  // 私有成员使用下划线前缀
    int get age =&gt; _age;
  }

  print(calculateSum(5, 3));
}



                  变量命名规则 




变量：myVariable, userCount
函数：getUserName, calculateTotal
常量：pi, maxConnections
私有成员：_privateField, _internalMethod()

库和文件命名（lowercase_with_underscores）
// 文件名：my_library.dart
class MyClass {}

// 文件名：database_helper.dart
class DatabaseHelper {}

// 文件名：user_auth_service.dart
class UserAuthService {}



                  文件命名规则 




使用小写字母
单词之间用下划线分隔
文件名应与主要类名相关

前缀和后缀命名
void main() {
  // 布尔变量：is/has/can/should
  var isValid = true;
  var hasPermission = false;
  var canExecute = true;

  // 回调：on 前缀
  Function? onClick;
  Function? onDataReceived;

  // 转换方法：toXxx
  var text = number.toString();
  var data = object.toJson();

  print(&#039;前缀示例：$isValid, $hasPermission&#039;);
}
代码格式化
使用 dart format
void main() {
  // 格式化前：var x=1+2;var y=3;if(x&gt;0){print(x);}
  // 格式化后：
  var x = 1 + 2;
  var y = 3;
  if (x &gt; 0) {
    print(x);
  }
}



                  格式化命令 



# 格式化当前目录
dart format .

# 格式化指定文件
dart format lib/main.dart

# 只检查格式（CI/CD）
dart format --output=none --set-exit-if-changed .

# 查看格式化差异
dart format --output=diff .
格式化规则
缩进和空格
void main() {
  // 使用 2 个空格缩进
  class Example {
    void method() {
      if (true) {
        print(&#039;缩进 2 个空格&#039;);
      }
    }
  }

  // 操作符两边添加空格
  var sum = 1 + 2;
  var list = [1, 2, 3];
  function(arg1, arg2, arg3);
}
行长度
void main() {
  // 函数调用换行
  someFunction(
    argument1,
    argument2,
    argument3,
  );

  // 链式调用换行
  final result = objects
      .map((obj) =&gt; obj.value)
      .where((value) value &gt; 0)
      .toList();

  // 级联调用格式
  var user = User()
    ..name = &#039;Alice&#039;
    ..email = &#039;alice@example.com&#039;
    ..age = 25;
}



                  风格违规警告 



❌ 不要使用制表符缩进
❌ 不要在一行写多条语句
❌ 不要省略大括号
文档注释
文档注释语法
使用 /// 编写文档注释，支持 Markdown 格式。
/// 计算两个整数的和。
///
/// 参数：
/// - [a] 第一个加数
/// - [b] 第二个加数
///
/// 返回两个数的和。
///
/// 示例：
/// ```dart
/// var result = add(5, 3); // 8
/// ```
int add(int a, int b) {
  return a + b;
}

/// 从 JSON 字符串创建用户对象。
///
/// 抛出 [FormatException] 当 JSON 格式不正确时。
factory User.fromJson(String jsonString) {
  final json = jsonDecode(jsonString) as Map&lt;String, dynamic&gt;;
  return User(
    name: json[&#039;name&#039;] as String,
    age: json[&#039;age&#039;] as int,
  );
}



                  文档注释最佳实践 




第一行是摘要：简短描述，以句号结尾
使用 [引用]：引用其他 API 元素
包含示例：使用代码块展示用法
说明参数和返回值：清晰的参数说明
记录异常：说明可能抛出的异常

类和成员文档
/// 表示系统中的一个用户。
///
/// 用户包含基本信息如姓名、年龄和邮箱地址。
class User {
  /// 用户的唯一标识符。
  final String id;

  /// 用户的姓名。
  String name;

  /// 用户的年龄。
  int age;

  /// 创建一个新用户实例。
  User({
    required this.id,
    required this.name,
    required this.age,
  });

  /// 将用户信息转换为 JSON 格式。
  Map&lt;String, dynamic&gt; toJson() {
    return {&#039;id&#039;: id, &#039;name&#039;: name, &#039;age&#039;: age};
  }

  /// 验证用户信息是否有效。
  bool isValid() {
    return name.length &gt;= 2 &amp;&amp; age &gt; 0;
  }
}

void main() {
  var user = User(id: &#039;1&#039;, name: &#039;Alice&#039;, age: 25);
  print(&#039;用户：${user.toJson()}&#039;);
}



                  文档注释警告 



❌ 不要使用单行注释编写文档
// 不好：// 计算两个数的和
// 好：/// 计算两个数的和。
❌ 不要省略公共 API 的文档
// 不好：缺少文档
// 好：/// 表示系统中的用户
Import 语句组织
Import 顺序
// 1. Dart SDK 导入
import &#039;dart:async&#039;;
import &#039;dart:convert&#039;;
import &#039;dart:io&#039;;

// 2. Package 导入
import &#039;package:flutter/material.dart&#039;;
import &#039;package:http/http.dart&#039; as http;

// 3. 项目相对导入
import &#039;models/user.dart&#039;;
import &#039;services/api_service.dart&#039;;
import &#039;utils/helpers.dart&#039;;

void main() {
  print(&#039;Import 组织示例&#039;);
}



                  Import 组织规则 




dart: - Dart 核心库
package: - 第三方包
相对路径 - 项目内文件
各部分内部按字母顺序排列
使用空行分隔各个部分

Import 别名和显示/隐藏
import &#039;dart:math&#039; as math;

void main() {
  var random = math.Random();
  var maxValue = math.pi;
  print(&#039;随机数：${random.nextInt(100)}&#039;);
}

// 处理命名冲突
import &#039;models/user.dart&#039; as auth;
import &#039;models/user_profile.dart&#039; as profile;

// 只导入需要的部分
import &#039;dart:math&#039; show pi, sqrt;

// 排除特定部分
import &#039;my_library.dart&#039; hide InternalClass;
延迟加载
import &#039;package:heavy_library/heavy_library.dart&#039; deferred as heavy;

void main() async {
  print(&#039;应用启动&#039;);
  await heavy.loadLibrary();
  heavy.doSomething();
}



                  Import 最佳实践 




使用相对导入导入项目文件
使用 package 导入导入包文件
避免使用 ../ 超过两级
使用 show 明确需要的内容
使用 hide 排除不需要的内容
为冲突的导入添加别名

代码组织
文件结构
// 1. 文件级文档注释
/// 提供用户认证相关的功能。
library;

// 2. Import 语句
import &#039;dart:async&#039;;

// 3. 常量定义
const int _maxAttempts = 3;

// 4. 异常类
class AuthException implements Exception {
  final String message;
  AuthException(this.message);
}

// 5. 主要类
class AuthService {
  String? currentUser;
  int _attempts = 0;

  Future&lt;bool&gt; login(String username, String password) async {
    return true;
  }
}

void main() {
  final service = AuthService();
  print(&#039;认证服务&#039;);
}



                  文件组织建议 




文档注释在前
按顺序排列：imports → exports → constants → classes
公共在前：公共成员在私有成员之前
相关内容分组：功能相关的代码放在一起

检查清单
在提交代码前，确保：

 所有标识符遵循命名约定
 代码已通过 dart format 格式化
 所有公共 API 都有文档注释
 Import 语句按正确顺序组织
 没有使用制表符缩进
 行长度不超过 80 字符
 布尔变量使用 is/has 前缀
 私有成员使用下划线前缀

