常见性能陷阱



                  避免这些性能陷阱 



1. 过度使用字符串拼接
void main() {
  // ❌ 不好：在循环中使用 + 拼接
  final sw1 = Stopwatch()..start();
  String result1 = &#039;&#039;;
  for (int i = 0; i &lt; 10000; i++) {
    result1 += &#039;Item $i&#039;; // 每次创建新字符串
  }
  sw1.stop();
  print(&#039;String + concatenation: ${sw1.elapsedMilliseconds}ms&#039;);
  // 输出：String + concatenation: 800-1200ms

  // ✅ 最佳实践：使用 StringBuffer
  final sw2 = Stopwatch()..start();
  final buffer = StringBuffer();
  for (int i = 0; i &lt; 10000; i++) {
    buffer.write(&#039;Item $i&#039;);
  }
  final result2 = buffer.toString();
  sw2.stop();
  print(&#039;StringBuffer: ${sw2.elapsedMilliseconds}ms&#039;);
  // 输出：StringBuffer: 5-15ms (快 100 倍)
}
2. 在热路径使用反射
import &#039;dart:mirrors&#039;;

void main() {
