3. 不必要的类型转换
void main() {
  avoidUnnecessaryCasting();
}

void avoidUnnecessaryCasting() {
  const iterations = 1000000;

  // ❌ 不好：不必要的类型转换
  final sw1 = Stopwatch()..start();
  final list = &lt;Object&gt;[1, 2, 3, 4, 5];
  for (int i = 0; i &lt; iterations; i++) {
    for (final item in list) {
      final value = item as int; // 不必要的转换
      value * 2;
    }
  }
  sw1.stop();
  print(&#039;With casting: ${sw1.elapsedMilliseconds}ms&#039;);
  // 输出：With casting: 200-400ms

  // ✅ 最佳实践：使用正确的类型
  final sw2 = Stopwatch()..start();
  final list2 = &lt;int&gt;[1, 2, 3, 4, 5];
  for (int i = 0; i &lt; iterations; i++) {
    for (final item in list2) {
      item * 2;
    }
  }
  sw2.stop();
  print(&#039;Without casting: ${sw2.elapsedMilliseconds}ms&#039;);
  // 输出：Without casting: 50-150ms (快 2-4 倍)
}
4. 过度的函数调用开销
void main() {
  minimizeFunctionCallOverhead();
}

void minimizeFunctionCallOverhead() {
  const iterations = 10000000;

  // ❌ 不好：过度的小函数调用
  final sw1 = Stopwatch()..start();
  int sum = 0;
  for (int i = 0; i &lt; iterations; i++) {
    sum = addOne(sum); // 函数调用开销
  }
  sw1.stop();
  print(&#039;Function calls: ${sw1.elapsedMilliseconds}ms&#039;);
  // 输出：Function calls: 200-400ms

  // ✅ 最佳实践：内联简单操作
  final sw2 = Stopwatch()..start();
  int sum2 = 0;
  for (int i = 0; i &lt; iterations; i++) {
    sum2 += 1; // 直接操作
  }
  sw2.stop();
  print(&#039;Inlined: ${sw2.elapsedMilliseconds}ms&#039;);
  // 输出：Inlined: 20-50ms (快 5-10 倍)
}

int addOne(int value) =&gt; value + 1;

