快速示例



                  Isolate 并发编程 



import &#039;dart:isolate&#039;;

// Isolate 的工作函数
void worker(SendPort sendPort) {
  // 处理耗时计算
  int result = 0;
  for (int i = 0; i &lt; 1000000000; i++) {
    result += i;
  }
  // 发送结果回主 Isolate
  sendPort.send(result);
}

Future&lt;void&gt; runInIsolate() async {
  // 创建 ReceivePort 接收消息
  final receivePort = ReceivePort();

  // 启动新的 Isolate
  await Isolate.spawn(
    worker,
    receivePort.sendPort,
  );

  // 等待结果
  final result = await receivePort.first as int;
  print(&#039;计算结果：$result&#039;);

  // 关闭端口
  receivePort.close();
}

void main() async {
  print(&#039;开始计算...&#039;);
  await runInIsolate();
  print(&#039;计算完成&#039;);
}



