print(identical(p1, p2)); // true

// 2. 懒加载大数据
class DataLoader {
  List&lt;String&gt;? _data;

  List&lt;String&gt; get data {
    _data ??= _loadData(); // 只加载一次
    return _data!;
  }

  List&lt;String&gt; _loadData() {
    // 模拟加载数据
    return List.generate(10000, (i) =&gt; &#039;Item $i&#039;);
