}

// 3. 及时释放资源
class ResourceHandler {
  List&lt;int&gt;? _largeList;

  void process() {
    _largeList = List.generate(1000000, (i) =&gt; i);
    // 处理数据
    processLargeData(_largeList!);

    // 处理完成后释放
    _largeList = null;
  }

  void processLargeData(List&lt;int&gt; data) {
    // ...
  }
}
