self.onmessage = function() {
  let result = 0;
  for (let i = 0; i &lt; 1000000000; i++) {
    result += i;
  }
  self.postMessage(result);
};

// main.js
const worker = new Worker(&#039;worker.js&#039;);
worker.onmessage = function(e) {
  console.log(&#039;Result:&#039;, e.data);
