                  类定义对比 



// Dart - 简洁明了
class Person {
  final String name;
  int _age; // 私有字段（库级别）

  Person(this.name, {int age = 0}) : _age = age;

  int get age =&gt; _age;
  set age(int value) {
    if (value &gt;= 0) _age = value;
  }

  @override
  String toString() =&gt; &#039;Person: $name, $_age&#039;;
}

void main() {
  final person = Person(&#039;Alice&#039;, age: 30);
  print(person); // Person: Alice, 30
