空安全对比



                  空安全对比 



// Dart - Sound null safety
String? getNullableString() =&gt; null;

void main() {
  String? nullable = getNullableString();

  // 必须处理空值
  if (nullable != null) {
    print(nullable.length); // 安全
  }

  // 或使用空安全操作符
  print(nullable?.length ?? 0); // 安全

  // 非空断言（谨慎使用）
  print(nullable!.length); // 运行时错误
}
// Java - Optional (Java 8+)
import java.util.Optional;

public class Main {
    static Optional&lt;String&gt; getNullableString() {
        return Optional.empty();
    }

    public static void main(String[] args) {
        Optional&lt;String&gt; nullable = getNullableString();

        // 使用 Optional 处理
        nullable.ifPresent(s -&gt; System.out.println(s.length()));

        // 或提供默认值
        System.out.println(nullable.orElse(&quot;&quot;).length());

        // 传统方式（仍可能出现 NPE）
        String value = nullable.orElse(null);
        System.out.println(value.length()); // NullPointerException
    }
}
