Dart vs Kotlin
协程 vs Async/Await



                  并发编程对比 



// Dart - async/await + Future
Future&lt;int&gt; fetchData() async {
  await Future.delayed(Duration(milliseconds: 100));
  return 42;
}

Future&lt;void&gt; main() async {
  // 并行执行多个异步操作
  final results = await Future.wait([
    fetchData(),
    fetchData(),
    fetchData(),
  ]);
  print(&#039;Results: $results&#039;); // [42, 42, 42]

  // 错误处理
  try {
    final data = await fetchData();
    print(&#039;Data: $data&#039;);
  } catch (e) {
    print(&#039;Error: $e&#039;);
  }
}
// Kotlin - Coroutines
import kotlinx.coroutines.*

suspend fun fetchData(): Int {
    delay(100)
    return 42
}

suspend fun main() = coroutineScope {
    // 并行执行多个协程
    val deferred = listOf(
        async { fetchData() },
        async { fetchData() },
        async { fetchData() }
    )
    val results = deferred.awaitAll()
    println(&quot;Results: $results&quot;) // [42, 42, 42]

    // 错误处理
    try {
        val data = fetchData()
        println(&quot;Data: $data&quot;)
    } catch (e: Exception) {
        println(&quot;Error: $e&quot;)
    }
}
