                  空安全语法对比 



// Dart - 空安全
String? nullableName;
String nonNullName = &#039;Alice&#039;;

void main() {
  // 安全调用
  print(nullableName?.length);

  // 空值合并
  print(nullableName ?? &#039;Unknown&#039;);

  // 非空断言
  // print(nullableName!.length); // 运行时错误

