var nullableName: String? = null
var nonNullName: String = &quot;Alice&quot;

fun main() {
    // 安全调用
    println(nullableName?.length)

    // 空值合并 (Elvis 操作符)
    println(nullableName ?: &quot;Unknown&quot;)

    // 非空断言
    // println(nullableName!!.length) // 运行时错误

    // List 的空安全
    val nullableList: List&lt;String?&gt; = listOf(null, &quot;a&quot;, null)
    println(nullableList[0]?.length ?: 0) // 0
}
