内存泄漏避免策略



                  最佳实践 



// 1. 使用 WeakReference 构建缓存
class SafeCache {
  final Map&lt;String, WeakReference&lt;Object&gt;&gt; _cache = {};

  void put(String key, Object value) {
    _cache[key] = WeakReference(value);
  }

  Object? get(String key) {
    return _cache[key]?.target;
  }
}

// 2. 及时释放资源
class ResourceManager {
  StreamSubscription? _subscription;
  List&lt;int&gt;? _largeData;

  void start(Stream&lt;int&gt; stream) {
    _subscription = stream.listen(handleData);
  }

  void stop() {
    // 取消订阅
    _subscription?.cancel();
    _subscription = null;

    // 释放大对象
    _largeData = null;
  }

  void handleData(int data) {
    // 处理数据
  }
}

// 3. 使用 Finalizer 清理资源
import &#039;dart:ffi&#039;;

class NativeResource {
  final Pointer&lt;Void&gt; _ptr;

  NativeResource(this._ptr);

  // 注册终结器
  static final finalizer = NativeFinalizer(_freePtr.cast());

  static void _freePtr(Pointer&lt;Void&gt; ptr) {
    // 释放原生资源
    print(&#039;Freeing native resource&#039;);
  }
}
内存优化技巧
1. 使用 const 构造函数
class Point {
  final int x;
  final int y;

  const Point(this.x, this.y);
}

void main() {
  // const 对象在编译时创建，只占用一份内存
  final p1 = const Point(0, 0);
  final p2 = const Point(0, 0);

  print(identical(p1, p2)); // true - 同一个对象

  // 大量使用 const 可以显著减少内存占用
  var points = List.generate(
    10000,
    (i) =&gt; const Point(0, 0), // 所有引用指向同一对象
  );
}
2. 懒加载与延迟初始化
class LazyLoader {
  late List&lt;int&gt; _heavyData;

  List&lt;int&gt; get heavyData {
    // 只在首次访问时初始化
    if (!(_heavyData.isNotEmpty)) {
      _heavyData = _loadHeavyData();
    }
    return _heavyData;
  }

  List&lt;int&gt; _loadHeavyData() {
    print(&#039;Loading heavy data...&#039;);
    return List.generate(1000000, (i) =&gt; i);
  }
}

void main() {
  var loader = LazyLoader();
  print(&#039;Loader created&#039;);

  // 只在需要时才加载数据
  print(&#039;Accessing data...&#039;);
  var data = loader.heavyData;
  print(&#039;Data loaded: ${data.length}&#039;);
}
3. 对象池模式
class ObjectPool&lt;T&gt; {
  final List&lt;T&gt; _pool = [];
  final T Function() _factory;

  ObjectPool(this._factory);

  T acquire() {
    if (_pool.isNotEmpty) {
      return _pool.removeLast();
    }
    return _factory();
  }

  void release(T object) {
    _pool.add(object);
  }
}

// 使用示例
class Resource {
  Resource();

  void reset() {
    // 重置对象状态
  }
}

void main() {
  var pool = ObjectPool(() =&gt; Resource());

  // 获取对象
  var res1 = pool.acquire();
  var res2 = pool.acquire();

  // 使用完毕后归还
  pool.release(res1);
  pool.release(res2);

  // 对象被复用，减少 GC 压力
}
