Dart 并发模型



                  核心概念 



Dart 采用基于 Isolate 的并发模型，每个 Isolate 拥有独立的内存堆，通过消息传递进行通信。这种设计避免了传统多线程编程中的竞态条件和数据竞争问题，同时保持了高效的并发处理能力。
学习目标
完成本文学习后，你将能够：

理解 Dart 的单线程事件循环模型
掌握 Isolate 的创建和通信机制
使用 SendPort/ReceivePort 进行跨 Isolate 通信
理解并发安全的概念和实现
选择合适的并发编程策略

并发模型架构
┌─────────────────────────────────────────────────────┐
│                    Dart 应用                         │
├─────────────────────────────────────────────────────┤
│  主 Isolate (Main Isolate)                          │
│  ┌───────────────────────────────────────────┐      │
│  │         事件循环 (Event Loop)              │      │
│  │  ┌──────────┐         ┌──────────┐        │      │
│  │  │ 微任务队列 │  ←───  │ 事件队列   │        │      │
│  │  │ Microtask│         │  Event   │        │      │
│  │  └──────────┘         └──────────┘        │      │
│  └───────────────────────────────────────────┘      │
│                      ↕ 消息传递                      │
│  ┌────────────┐  ┌────────────┐  ┌────────────┐   │
│  │ Isolate 1  │  │ Isolate 2  │  │ Isolate 3  │   │
│  │ 独立内存   │  │ 独立内存   │  │ 独立内存   │   │
│  └────────────┘  └────────────┘  └────────────┘   │
└─────────────────────────────────────────────────────┘

1. 单线程事件循环
1.1 事件循环机制
Dart 采用单线程事件循环模型，所有代码都在主 Isolate 中执行，通过事件循环处理异步操作。



                  事件循环示例 



void main() {
  print(&#039;1. 同步代码&#039;);

  // 微任务：优先级最高
  scheduleMicrotask(() {
    print(&#039;2. 微任务 1&#039;);
  });

  // 事件队列：定时器
  Future.delayed(Duration.zero, () {
    print(&#039;4. 事件队列任务 1&#039;);
  });

  // 微任务
  scheduleMicrotask(() {
    print(&#039;3. 微任务 2&#039;);
  });

  // 事件队列：普通 Future
  Future(() {
    print(&#039;5. 事件队列任务 2&#039;);
  });

  print(&#039;6. 同步代码结束&#039;);
}

// 输出顺序：
// 1. 同步代码
// 6. 同步代码结束
// 2. 微任务 1
// 3. 微任务 2
// 4. 事件队列任务 1
// 5. 事件队列任务 2
1.2 执行顺序规则



                  事件循环执行顺序 




同步代码：立即执行
微任务队列：清空所有微任务后处理事件
事件队列：按 FIFO 顺序处理

void eventLoopDemo() async {
  // 同步代码
  print(&#039;Start&#039;);

  // Future: 添加到事件队列
  Future(() =&gt; print(&#039;Future 1&#039;));

  // scheduleMicrotask: 添加到微任务队列
  scheduleMicrotask(() =&gt; print(&#039;Microtask 1&#039;));

  // async/await: 语法糖，实际是 Future
  await Future(() =&gt; print(&#039;Future 2&#039;));

  // await 后的代码会被调度为微任务
  scheduleMicrotask(() =&gt; print(&#039;Microtask 2&#039;));

  print(&#039;End&#039;);
}

// 输出：Start → Future 1 → Microtask 1 → Future 2 → Microtask 2 → End
2. Isolate 机制
2.1 Isolate 特性
Isolate 是 Dart 中的并发执行单元，具有以下特性：



                  Isolate 核心特性 




独立内存：每个 Isolate 有自己的内存堆
消息传递：通过 SendPort/ReceivePort 通信
无共享状态：避免竞态条件和数据竞争
轻量级：相比线程更轻量，启动更快

2.2 创建 Isolate



                  基本用法 



import &#039;dart:isolate&#039;;

// Isolate 工作函数
void isolateWorker(SendPort sendPort) {
  print(&#039;Worker Isolate: 开始执行&#039;);

  // 执行耗时计算
  int result = 0;
  for (int i = 0; i &lt; 1000000000; i++) {
    result += i;
  }

  // 发送结果回主 Isolate
  sendPort.send(result);

  print(&#039;Worker Isolate: 执行完成&#039;);
}

void main() async {
  print(&#039;Main Isolate: 启动&#039;);

  // 创建 ReceivePort 接收消息
  final receivePort = ReceivePort();

  // 启动新的 Isolate
  final isolate = await Isolate.spawn(
    isolateWorker,
    receivePort.sendPort,
  );

  // 监听消息
  receivePort.listen((message) {
    print(&#039;Main Isolate: 收到结果 - $message&#039;);
    receivePort.close();
    isolate.kill();
  });

  print(&#039;Main Isolate: 等待结果&#039;);
}
2.3 双向通信



                  完整的双向通信示例 



import &#039;dart:isolate&#039;;

// Worker 端
void worker(SendPort mainSendPort) {
  // 创建自己的 ReceivePort
  final workerReceivePort = ReceivePort();

  // 将 SendPort 发送给主 Isolate
  mainSendPort.send(workerReceivePort.sendPort);

  // 监听来自主 Isolate 的消息
  workerReceivePort.listen((message) {
    if (message == &#039;ping&#039;) {
      print(&#039;Worker: 收到 ping，发送 pong&#039;);
      mainSendPort.send(&#039;pong&#039;);
    } else if (message == &#039;stop&#039;) {
      print(&#039;Worker: 收到停止指令&#039;);
      workerReceivePort.close();
    }
  });
}

// 主 Isolate 端
Future&lt;void&gt; bidirectionalCommunication() async {
  final mainReceivePort = ReceivePort();

  // 启动 Worker
  await Isolate.spawn(worker, mainReceivePort.sendPort);

  SendPort? workerSendPort;

  // 监听 Worker 的消息
  mainReceivePort.listen((message) {
    if (message is SendPort) {
      // 收到 Worker 的 SendPort
      workerSendPort = message;
      print(&#039;Main: 已建立连接&#039;);

      // 发送消息给 Worker
      workerSendPort!.send(&#039;ping&#039;);
    } else if (message is String) {
      print(&#039;Main: 收到消息 - $message&#039;);

      if (message == &#039;pong&#039;) {
        // 再次发送
        workerSendPort!.send(&#039;ping&#039;);
      }
    }
  });

  // 等待一段时间后停止
  await Future.delayed(Duration(seconds: 1));
  workerSendPort?.send(&#039;stop&#039;);
  mainReceivePort.close();
}

void main() async {
  await bidirectionalCommunication();
}
3. SendPort 和 ReceivePort
3.1 端口通信原理
SendPort 和 ReceivePort 是 Isolate 间通信的桥梁：
import &#039;dart:isolate&#039;;

// 端口通信模型
void portCommunicationDemo() async {
  // 创建接收端口
  final receiver = ReceivePort();

  // 从接收端口获取发送端口
  final sender = receiver.sendPort;

  // 发送消息
  sender.send(&#039;Hello&#039;);

  // 监听消息
  receiver.listen((message) {
    print(&#039;收到：$message&#039;);
  });

  // 关闭端口
  receiver.close();
}
3.2 传递复杂数据



                  传递不同类型的数据 



import &#039;dart:isolate&#039;;

// 传递各种类型的数据
void dataWorker(SendPort sendPort) {
  // 发送不同类型的数据
  sendPort.send(&#039;String message&#039;);
  sendPort.send(42);
  sendPort.send([1, 2, 3, 4, 5]);
  sendPort.send({&#039;key&#039;: &#039;value&#039;, &#039;name&#039;: &#039;Dart&#039;});
  sendPort.send(User(id: 1, name: &#039;Alice&#039;));
}

// 自定义类（必须可序列化）
class User {
  final int id;
  final String name;

  User({required this.id, required this.name});
}

Future&lt;void&gt; complexDataTransfer() async {
  final receiver = ReceivePort();

  await Isolate.spawn(dataWorker, receiver.sendPort);

  receiver.listen((message) {
    print(&#039;收到数据类型：${message.runtimeType} - $message&#039;);
  });

  // 等待处理完成
  await Future.delayed(Duration(seconds: 1));
  receiver.close();
}

void main() async {
  await complexDataTransfer();
}
3.3 流式通信



                  使用 Stream 处理多条消息 



import &#039;dart:isolate&#039;;
import &#039;dart:async&#039;;

// 流式数据处理
void streamWorker(SendPort sendPort) {
  // 发送多条数据
  for (int i = 0; i &lt; 10; i++) {
    sendPort.send(i);
    Future.delayed(Duration(milliseconds: 100));
  }

  // 发送完成信号
  sendPort.send(&#039;done&#039;);
}

Future&lt;void&gt; streamCommunication() async {
  final receiver = ReceivePort();

  await Isolate.spawn(streamWorker, receiver.sendPort);

  // 将 ReceivePort 转换为 Stream
  final stream = receiver.asBroadcastStream();

  // 处理数据流
  await for (final message in stream) {
    if (message == &#039;done&#039;) {
      print(&#039;处理完成&#039;);
      receiver.close();
      break;
    }

    print(&#039;处理数据：$message&#039;);
  }
}

void main() async {
  await streamCommunication();
}
4. 并发安全
4.1 为什么 Isolate 是线程安全的



                  并发安全的保证 




无共享内存：每个 Isolate 拥有独立的内存堆
消息传递：通过复制数据传递消息，避免共享状态
不可变性：传递的消息默认是不可变的

// 演示并发安全
void safeConcurrencyDemo() async {
  // 在不同的 Isolate 中操作相同的数据
  final receiver1 = ReceivePort();
  final receiver2 = ReceivePort();

  final data = [1, 2, 3, 4, 5];

  // Isolate 1 修改数据
  Isolate.spawn((SendPort sendPort) {
    data[0] = 999; // 修改不影响其他 Isolate
    sendPort.send(&#039;Isolate 1: $data&#039;);
  }, receiver1.sendPort);

  // Isolate 2 读取数据
  Isolate.spawn((SendPort sendPort) {
    sendPort.send(&#039;Isolate 2: $data&#039;);
  }, receiver2.sendPort);

  // 两个 Isolate 互不影响
}
4.2 避免常见陷阱



                  并发编程常见错误 



// 错误示例 1: 忘记关闭端口
void badExample1() async {
  final receiver = ReceivePort();

  await Isolate.spawn(worker, receiver.sendPort);

  // 错误：没有关闭端口，导致内存泄漏
  // 正确做法：在适当时候调用 receiver.close()
}

// 错误示例 2: 阻塞主 Isolate
void badExample2() async {
  final receiver = ReceivePort();

  await Isolate.spawn(worker, receiver.sendPort);

  // 错误：使用 await 可能阻塞主 Isolate
  // 正确做法：使用 listener 而不是 await
  final result = await receiver.first;
  print(result);
}

// 错误示例 3: 传递不可序列化的对象
void badExample3() async {
  final receiver = ReceivePort();

  // 错误：尝试传递不可序列化的对象
  final file = File(&#039;some.txt&#039;); // File 不能直接传递

  await Isolate.spawn(
    (SendPort sendPort) {
      // 这会导致运行时错误
    },
    receiver.sendPort,
  );
}
4.3 最佳实践



                  并发编程最佳实践 



// 1. 使用 Compute 函数（Flutter 中常用）
import &#039;package:flutter/foundation.dart&#039;;

int heavyComputation(int n) {
  int result = 0;
  for (int i = 0; i &lt; n; i++) {
    result += i;
  }
  return result;
}

void useCompute() async {
  // 自动管理 Isolate 的生命周期
  final result = await compute(heavyComputation, 1000000000);
  print(&#039;结果：$result&#039;);
}

// 2. 使用 IsolatePool 管理多个 Isolate
class IsolatePool {
  final List&lt;Isolate&gt; _isolates = [];
  final List&lt;ReceivePort&gt; _ports = [];
  final int size;

  IsolatePool(this.size);

  Future&lt;void&gt; spawn(void Function(SendPort) worker) async {
    for (int i = 0; i &lt; size; i++) {
      final port = ReceivePort();
      final isolate = await Isolate.spawn(worker, port.sendPort);
      _isolates.add(isolate);
      _ports.add(port);
    }
  }

  void close() {
    for (final isolate in _isolates) {
      isolate.kill();
    }
    for (final port in _ports) {
      port.close();
    }
  }
}

// 3. 错误处理
void safeWorker(SendPort sendPort) {
  try {
    // 执行可能出错的操作
    throw Exception(&#039;发生错误&#039;);
  } catch (e) {
    // 发送错误信息
    sendPort.send({&#039;error&#039;: e.toString()});
  }
}

Future&lt;void&gt; errorHandling() async {
  final receiver = ReceivePort();

  await Isolate.spawn(safeWorker, receiver.sendPort);

  receiver.listen((message) {
    if (message is Map &amp;&amp; message.containsKey(&#039;error&#039;)) {
      print(&#039;Worker 出错：${message[&#039;error&#039;]}&#039;);
    }
  });
}
5. 性能优化
5.1 选择合适的并发策略



                  并发策略对比 

































场景推荐方案原因简单异步操作async/await事件循环处理，开销小CPU 密集型计算Isolate利用多核 CPUIO 密集型操作async/await不阻塞主线程大量并行任务Isolate Pool充分利用多核
5.2 性能考虑
// 性能测试示例
import &#039;dart:isolate&#039;;
import &#039;dart:async&#039;;

void performanceTest() async {
  final stopwatch = Stopwatch()..start();

  // 测试 1: 单 Isolate
  await singleIsolateTest();

  // 测试 2: 多 Isolate
  await multipleIsolateTest();

  stopwatch.stop();
  print(&#039;总耗时：${stopwatch.elapsedMilliseconds}ms&#039;);
}

Future&lt;void&gt; singleIsolateTest() async {
  final sw = Stopwatch()..start();

  final receiver = ReceivePort();
  await Isolate.spawn((SendPort sendPort) {
    int result = 0;
    for (int i = 0; i &lt; 1000000000; i++) {
      result += i;
    }
    sendPort.send(result);
  }, receiver.sendPort);

  await receiver.first;
  receiver.close();

  sw.stop();
  print(&#039;单 Isolate: ${sw.elapsedMilliseconds}ms&#039;);
}

Future&lt;void&gt; multipleIsolateTest() async {
  final sw = Stopwatch()..start();

  final futures = &lt;Future&gt;[];
  for (int i = 0; i &lt; 4; i++) {
    futures.append(Isolate.spawn((SendPort sendPort) {
      int result = 0;
      for (int j = 0; j &lt; 250000000; j++) {
        result += j;
      }
      sendPort.send(result);
    }, ReceivePort().sendPort));
  }

  await Future.wait(futures);
  sw.stop();
  print(&#039;多 Isolate: ${sw.elapsedMilliseconds}ms&#039;);
}
6. 实际应用场景
6.1 JSON 解析



                  在 Isolate 中解析大型 JSON 



import &#039;dart:isolate&#039;;
import &#039;dart:convert&#039;;

// 在 Isolate 中解析 JSON
void jsonParserWorker(SendPort sendPort) {
  final jsonString = &#039;&#039;&#039;
  {
    &quot;users&quot;: [
      {&quot;id&quot;: 1, &quot;name&quot;: &quot;Alice&quot;},
      {&quot;id&quot;: 2, &quot;name&quot;: &quot;Bob&quot;},
      {&quot;id&quot;: 3, &quot;name&quot;: &quot;Charlie&quot;}
    ]
  }
  &#039;&#039;&#039;;

  final data = jsonDecode(jsonString);
  sendPort.send(data);
}

Future&lt;void&gt; parseJsonInIsolate() async {
  final receiver = ReceivePort();

  await Isolate.spawn(jsonParserWorker, receiver.sendPort);

  final result = await receiver.first;
  print(&#039;解析结果：$result&#039;);

  receiver.close();
}
6.2 图像处理
import &#039;dart:isolate&#039;;
import &#039;dart:typed_data&#039;;

// 图像处理 Worker
void imageProcessor(SendPort sendPort) {
  // 模拟图像处理
  final imageData = Uint8List(1920 * 1080 * 4); // RGBA

  // 处理图像数据
  for (int i = 0; i &lt; imageData.length; i += 4) {
    imageData[i] = 255; // R
    imageData[i + 1] = 128; // G
    imageData[i + 2] = 64; // B
    imageData[i + 3] = 255; // A
  }

  sendPort.send(imageData);
}

Future&lt;void&gt; processImage() async {
  final receiver = ReceivePort();

  await Isolate.spawn(imageProcessor, receiver.sendPort);

  final processedImage = await receiver.first as Uint8List;
  print(&#039;图像处理完成，大小：${processedImage.length} bytes&#039;);

  receiver.close();
}
7. 调试与监控



                  调试并发代码 



// 添加日志追踪
void debuggableWorker(SendPort sendPort) {
  print(&#039;Worker: 启动&#039;);

  try {
    // 执行任务
    sendPort.send({&#039;status&#039;: &#039;started&#039;, &#039;timestamp&#039;: DateTime.now()});

    // 处理数据
    final result = performTask();

    sendPort.send({&#039;status&#039;: &#039;completed&#039;, &#039;result&#039;: result});
  } catch (e) {
    sendPort.send({&#039;status&#039;: &#039;error&#039;, &#039;error&#039;: e.toString()});
  } finally {
    print(&#039;Worker: 完成&#039;);
  }
}

int performTask() {
  // 任务实现
  return 42;
}

// 使用日志监控
Future&lt;void&gt; debugConcurrency() async {
  final receiver = ReceivePort();

  await Isolate.spawn(debuggableWorker, receiver.sendPort);

  receiver.listen((message) {
    print(&#039;Main: 收到消息 - $message&#039;);
  });
}
8. 常见问题与解决方案
8.1 Isolate 泄漏



                  问题：未正确关闭 Isolate 



// 错误示例
void leakedIsolate() async {
  final receiver = ReceivePort();
  await Isolate.spawn(worker, receiver.sendPort);
  // 忘记关闭 receiver 和 isolate
}

// 正确示例
void properIsolate() async {
  final receiver = ReceivePort();
  final isolate = await Isolate.spawn(worker, receiver.sendPort);

  receiver.listen((message) {
    // 处理消息
    receiver.close();
    isolate.kill(); // 显式关闭
  });
}
8.2 消息顺序问题
// 保证消息顺序
void orderedMessages() async {
  final receiver = ReceivePort();

  await Isolate.spawn((SendPort sendPort) {
    for (int i = 0; i &lt; 5; i++) {
      sendPort.send(i);
    }
  }, receiver.sendPort);

  // 按顺序处理消息
  final messages = &lt;int&gt;[];
  receiver.listen((message) {
    if (message is int) {
      messages.add(message);
      if (messages.length == 5) {
        print(&#039;所有消息：$messages&#039;);
        receiver.close();
      }
    }
  });
}
