    &quot;fmt&quot;
    &quot;strings&quot;
 
    &quot;github.com/elliotchance/pie/pie&quot;
)
 
// 示例
func main() {
    name := pie.Strings{&quot;Bob&quot;, &quot;Sally&quot;, &quot;John&quot;, &quot;Jane&quot;}.
