30-resources/开发/kotlin-学习笔记.content:
Kotlin 学习笔记



                  概述 



Kotlin 是运行在 JVM 上的静态类型编程语言，与 Java 100% 兼容。


基础语法
变量
// 只读变量（val）
val name = &quot;Kotlin&quot;
val age: Int = 10

// 可变变量（var）
var count = 0
count += 1

// 类型推导
val message = &quot;Hello&quot;  // 自动推导为 String
函数
// 基本函数
fun greet(name: String): String {
    return &quot;Hello, $name&quot;
}

// 表达式函数体
fun add(a: Int, b: Int) = a + b

// 默认参数
fun greet(name: String = &quot;World&quot;) = &quot;Hello, $name&quot;

// 命名参数
greet(name = &quot;Kotlin&quot;)

// 可变参数
fun printAll(vararg messages: String) {
    for (msg in messages) {
        println(msg)
    }
}
面向对象
类与继承
// 主构造函数
class Person(val name: String, var age: Int)

// 次构造函数
class Person(val name: String) {
    var age: Int = 0
    constructor(name: String, age: Int) : this(name) {
        this.age = age
    }
}

// 数据类
data class User(val name: String, val age: Int)

// 继承
open class Animal(val name: String)
class Dog(name: String) : Animal(name) {
    fun bark() = &quot;$name says Woof!&quot;
}
空安全
可空类型
// 非空类型
var name: String = &quot;Kotlin&quot;
// name = null  // 编译错误

// 可空类型
var nickname: String? = &quot;Kotlin&quot;
nickname = null  // OK

// 安全调用
val length = nickname?.length  // 如果 nickname 为 null，返回 null

// Elvis 操作符
val len = nickname?.length ?: 0  // 如果为 null，使用默认值 0

// 安全转换
val str: Any = &quot;Hello&quot;
val length = (str as? String)?.length ?: 0
集合操作
List/Set/Map
// 不可变列表
val list = listOf(1, 2, 3)
list[0]  // 1

// 可变列表
val mutable = mutableListOf(1, 2, 3)
mutable.add(4)

// Set
val set = setOf(1, 2, 3, 3)  // {1, 2, 3}

// Map
val map = mapOf(&quot;key&quot; to &quot;value&quot;, &quot;foo&quot; to &quot;bar&quot;)
map[&quot;key&quot;]  // &quot;value&quot;
函数式操作
val numbers = listOf(1, 2, 3, 4, 5)

// filter
val evens = numbers.filter { it % 2 == 0 }  // [2, 4]

// map
val squared = numbers.map { it * it }  // [1, 4, 9, 16, 25]

// reduce
val sum = numbers.reduce { acc, n -&gt; acc + n }  // 15

// fold
val sum = numbers.fold(0) { acc, n -&gt; acc + n }
协程
基础
import kotlinx.coroutines.*

// 启动协程
runBlocking {
    launch {
        delay(1000L)
        println(&quot;World!&quot;)
    }
    print(&quot;Hello, &quot;)
}

// 异步函数
suspend fun fetchData(): String {
    delay(1000L)
    return &quot;Data&quot;
}

// 返回值
val result = async { fetchData() }.await()
Android 开发
Activity
class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
    }
}
与 Java 互操作
调用 Java
val list = ArrayList&lt;String&gt;()
list.add(&quot;Hello&quot;)
Kotlin 属性
// Java 代码调用
// Kotlin: val name: String
// Java: person.getName()

// @JvmField 注解
@JvmField
var name = &quot;Kotlin&quot;  // Java: person.name
最佳实践

优先使用 val：不可变性更安全
数据类：用于数据模型
空安全：避免 NullPointerException
协程：异步编程的首选
扩展函数：为现有类添加功能

