30-resources/开发/python/魔术方法.content:
Python 魔术方法



                  概述 



Python 特殊方法 (Magic Methods/Dunder Methods)。
对象创建和销毁
class MyClass:
    def __new__(cls, *args, **kwargs):
        print(&quot;Creating instance&quot;)
        return super().__new__(cls)

    def __init__(self):
        print(&quot;Initializing instance&quot;)

    def __del__(self):
        print(&quot;Destroying instance&quot;)
字符串表示
class Point:
    def __str__(self):
        return &quot;Point (user-friendly)&quot;

    def __repr__(self):
        return &quot;Point(x=1, y=2)&quot;  # 用于调试
比较操作
class Number:
    def __eq__(self, other):
        return self.value == other.value

    def __lt__(self, other):
        return self.value &lt; other.value

    def __le__(self, other):
        return self.value &lt;= other.value

    def __gt__(self, other):
        return self.value &gt; other.value

    def __ge__(self, other):
        return self.value &gt;= other.value

    def __ne__(self, other):
        return self.value != other.value
算术操作
class Vector:
    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector(self.x / scalar, self.y / scalar)

    def __floordiv__(self, scalar):
        return Vector(self.x // scalar, self.y // scalar)

    def __mod__(self, scalar):
        return Vector(self.x % scalar, self.y % scalar)

    def __pow__(self, exponent):
        return Vector(self.x ** exponent, self.y ** exponent)
反向算术操作
class Number:
    def __radd__(self, other):
        # other + self
        return self.__add__(other)

    def __rmul__(self, other):
        # other * self
        return self.__mul__(other)
增量操作
class Number:
    def __iadd__(self, other):
        # self += other
        self.value += other.value
        return self
类型转换
class MyNumber:
    def __int__(self):
        return int(self.value)

    def __float__(self):
        return float(self.value)

    def __bool__(self):
        return bool(self.value)

    def __str__(self):
        return str(self.value)
容器协议
class CustomList:
    def __len__(self):
        return len(self.data)

    def __getitem__(self, key):
        return self.data[key]

    def __setitem__(self, key, value):
        self.data[key] = value

    def __delitem__(self, key):
        del self.data[key]

    def __contains__(self, item):
        return item in self.data

    def __iter__(self):
        return iter(self.data)
可调用对象
class Multiplier:
    def __init__(self, factor):
        self.factor = factor

    def __call__(self, x):
        return x * self.factor

times3 = Multiplier(3)
print(times3(10))  # 30
属性访问
class MyClass:
    def __getattr__(self, name):
        # 访问不存在的属性时调用
        return f&quot;Unknown attribute: {name}&quot;

    def __setattr__(self, name, value):
        # 设置属性时调用
        object.__setattr__(self, name, value)

    def __delattr__(self, name):
        # 删除属性时调用
        object.__delattr__(self, name)
描述器协议
class ValidatedAttribute:
    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__[self.name]

    def __set__(self, obj, value):
        if not isinstance(value, (int, float)):
            raise TypeError(&quot;Expected number&quot;)
        obj.__dict__[self.name] = value

    def __set_name__(self, owner, name):
        self.name = name

class Person:
    age = ValidatedAttribute()
上下文管理器
class FileManager:
    def __enter__(self):
        self.file = open(&quot;file.txt&quot;, &quot;r&quot;)
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file.close()
        return False  # 不抑制异常

with FileManager() as f:
    content = f.read()
上下文管理器装饰器
from contextlib import contextmanager

@contextmanager
def file_manager(filename):
    f = open(filename, &quot;r&quot;)
    try:
        yield f
    finally:
        f.close()
哈希和相等
class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)
