30-resources/开发/zig/zig-笔记.content:
Zig 学习笔记
安装
# Arch Linux
yay -S zig

# 从源码
git clone github.com/ziglang/zig.git
cd zig
zig build
基础语法
变量
// 常量
const PI = 3.14159;

// 变量
var count: u32 = 42;

// 类型推导
const value = 100;
函数
fn add(a: i32, b: i32) i32 {
    return a + b;
}

// 无返回值
fn greet(name: []const u8) void {
    std.debug.print(&quot;Hello, {s}\n&quot;, .{name});
}
数组和切片
数组
// 固定大小数组
const numbers = [5]u32{ 1, 2, 3, 4, 5 };

// 数组长度
const len = numbers.len;
切片
// 切片
const slice = numbers[0..3];

// 切片长度和指针
const slice_len = slice.len;
const slice_ptr = slice.ptr;
结构体
定义
const Point = struct {
    x: f32,
    y: f32,

    fn new(x: f32, y: f32) Point {
        return Point{ .x = x, .y = y };
    }

    fn distance(self: Point, other: Point) f32 {
        const dx = self.x - other.x;
        const dy = self.y - other.y;
        return @sqrt(dx * dx + dy * dy);
    }
};

const p = Point.new(1.0, 2.0);
错误处理
Error Union
// 错误集
const ParseError = error{
    InvalidCharacter,
    UnexpectedEnd,
};

// 返回错误
fn parse(str: []const u8) ParseError!i32 {
    if (str.len == 0) return ParseError.UnexpectedEnd;
    // ...
    return 42;
}

// 处理错误
const result = parse(&quot;123&quot;) catch |err| {
    std.debug.print(&quot;Error: {}\n&quot;, .{err});
    return 0;
};
try
fn tryParse(str: []const u8) !i32 {
    const value = try parse(str);  // 错误向上传播
    return value * 2;
}
可选值
Optional
// 可选类型
fn find(array: []const i32, target: i32) ?usize {
    for (array, 0..) |item, index| {
        if (item == target) return index;
    }
    return null;
}

// 处理可选值
const index = find(&amp;items, 42) orelse {
    std.debug.print(&quot;Not found\n&quot;);
    return;
};
并发
async/await
fn fetchData() ![]const u8 {
    // 异步操作
    return &quot;data&quot;;
}

const data = try fetchData();
内存管理
Allocator
// 分配器
var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
defer arena.deinit();

const allocator = arena.allocator();

// 分配内存
const slice = try allocator.alloc(u8, 100);
defer allocator.free(slice);
泛型
函数泛型
fn max(comptime T: type, a: T, b: T) T {
    return if (a &gt; b) a else b;
}

const result = max(i32, 10, 20);
编译时
comptime
// 编译时执行
const value = comptime 2 + 3;

// 编译时函数
fn double(x: i32) i32 {
    return x * 2;
}
const result = comptime double(5);  // 编译时计算
与 C 交互
C ABI
const c = @cImport({
    @cInclude(&quot;stdio.h&quot;);
});

export fn add(a: c_int, b: c_int) c_int {
    return a + b;
}
