文章分析
const COLUMNS = [
    { id: &quot;文件&quot;, value: row =&gt; row.page.$link },
    { id: &quot;标签&quot;, value: row =&gt; row.tags.length ? row.tags.map(tag =&gt; `${tag}`).join(&quot;, &quot;) : &quot;—&quot; },
];

return function View() {
    const pages = dc.useQuery(&quot;@page&quot;);
    const rows = dc.useMemo(() =&gt; {
        return Array.from(pages ?? [])
            .map(page =&gt; ({ page, tags: page.$tags ?? [] }))
            .sort((a, b) =&gt; a.page.$path.localeCompare(b.page.$path));
    }, [pages]);

    return &lt;dc.Table rows={rows} columns={COLUMNS} /&gt;;
}
标签数量统计
const TAG_COLUMNS = [
    { id: &quot;标签&quot;, value: row =&gt; row.tag },
    { id: &quot;数量&quot;, value: row =&gt; row.count },
];

return function View() {
    const pages = dc.useQuery(&quot;@page&quot;);
    const tagCounts = dc.useMemo(() =&gt; {
        const countMap = new Map();
        for (const page of (pages ?? [])) {
            for (const tag of (page.$tags ?? [])) {
                const tagStr = String(tag);
                countMap.set(tagStr, (countMap.get(tagStr) ?? 0) + 1);
            }
        }
        return Array.from(countMap.entries())
            .map(([tag, count]) =&gt; ({ tag, count }))
            .sort((a, b) =&gt; b.count - a.count);
    }, [pages]);

    return &lt;dc.Table rows={tagCounts} columns={TAG_COLUMNS} /&gt;;
}
缺少日期字段的文档
排查 frontmatter 中缺少 createDate、updateDate、learnDate 中任意一个字段的文档（排除 assets/ 目录）。
const MISSING_COLUMNS = [
    { id: &quot;文件&quot;, value: row =&gt; row.link },
];

const REQUIRED = [&quot;createDate&quot;, &quot;updateDate&quot;, &quot;learnDate&quot;];

return function View() {
    const pages = dc.useQuery(&quot;@page&quot;);
    const rows = dc.useMemo(() =&gt; {
        return Array.from(pages ?? [])
            .filter(page =&gt; !page.$path.startsWith(&quot;assets/&quot;))
            .map(page =&gt; {
                const fm = page.$frontmatter ?? {};
                const missing = REQUIRED.filter(field =&gt; !(field in fm));
                return { link: page.$link, path: page.$path, missing };
            })
            .filter(row =&gt; row.missing.length &gt; 0)
            .sort((a, b) =&gt; a.path.localeCompare(b.path));
    }, [pages]);

    return &lt;dc.Table rows={rows} columns={MISSING_COLUMNS} /&gt;;
}
